class BoundaryFragmentV3CoreRecallRidgeCandidateSoftRidgeBarrierHeadLoss(
    BoundaryFragmentV3CoreRecallRidgeCandidateBinaryBarrierHeadLoss
):
    """Candidate-restricted barrier head with a soft distance/ridge target."""

    def __init__(
        self,
        base_loss: nn.Module,
        *,
        aux_ridge_lambda: float = 0.56,
        aux_shell_ceiling_lambda: float = 0.10,
        aux_margin_lambda: float = 0.12,
        aux_ridge_near_shell: float = 0.34,
        aux_ridge_far_shell: float = 0.12,
        aux_shell_ceiling: float = 0.42,
        aux_margin: float = 0.22,
        **kwargs,
    ):
        super().__init__(
            base_loss,
            aux_bce_lambda=0.34,
            aux_focal_lambda=0.24,
            aux_tversky_lambda=0.32,
            aux_positive_floor_lambda=0.28,
            aux_shell_topk_lambda=0.08,
            aux_pos_weight=16.0,
            aux_positive_floor=0.58,
            aux_focal_alpha=0.82,
            aux_topk_fraction=0.02,
            **kwargs,
        )
        self.aux_ridge_lambda = float(aux_ridge_lambda)
        self.aux_shell_ceiling_lambda = float(aux_shell_ceiling_lambda)
        self.aux_margin_lambda = float(aux_margin_lambda)
        self.aux_ridge_near_shell = float(aux_ridge_near_shell)
        self.aux_ridge_far_shell = float(aux_ridge_far_shell)
        self.aux_shell_ceiling = float(aux_shell_ceiling)
        self.aux_margin = float(aux_margin)

    def _soft_ridge_target(self, labels: torch.Tensor, dtype: torch.dtype) -> tuple[torch.Tensor, torch.Tensor]:
        barrier = labels == 2
        shell = labels == 3
        target = torch.zeros(labels.shape, dtype=dtype, device=labels.device)
        if not barrier.any():
            return target, torch.zeros_like(barrier)

        barrier_f = barrier.to(dtype=dtype).unsqueeze(1)
        near_barrier = F.max_pool3d(barrier_f, kernel_size=3, stride=1, padding=1)[:, 0] > 0.5
        far_barrier = F.max_pool3d(barrier_f, kernel_size=5, stride=1, padding=2)[:, 0] > 0.5
        near_shell = shell & near_barrier
        far_shell = shell & far_barrier & ~near_shell

        # [DATA][Risk:High][Scope:barrier_shell_localization]
        # The hard binary target made class2 disappear or overpaint shell. This
        # fixed soft ridge target gives one- and two-voxel shell neighborhoods a
        # sub-threshold value, so the aux head learns a local peak at class2
        # rather than a global shell detector. Evaluation threshold remains 0.5.
        target[far_shell] = self.aux_ridge_far_shell
        target[near_shell] = self.aux_ridge_near_shell
        target[barrier] = 1.0
        return target, near_shell

    def _ridge_regression_loss(
        self,
        aux_prob: torch.Tensor,
        ridge_target: torch.Tensor,
        labels: torch.Tensor,
        near_shell: torch.Tensor,
    ) -> torch.Tensor:
        candidate = (labels == 2) | (labels == 3)
        if not candidate.any():
            return aux_prob.new_zeros(())
        weights = torch.ones_like(ridge_target, dtype=aux_prob.dtype)
        weights = torch.where(labels == 2, weights.new_full((), 4.0), weights)
        weights = torch.where(near_shell, weights.new_full((), 1.5), weights)
        err = F.smooth_l1_loss(aux_prob.float(), ridge_target.float(), reduction="none")
        vals = err[candidate] * weights[candidate]
        denom = weights[candidate].sum().clamp_min(self.smooth)
        return vals.sum() / denom

    def _shell_ceiling_loss(self, aux_prob: torch.Tensor, labels: torch.Tensor) -> torch.Tensor:
        shell = labels == 3
        if not shell.any():
            return aux_prob.new_zeros(())
        vals = aux_prob[shell].float()
        if vals.numel() == 0:
            return aux_prob.new_zeros(())
        k = max(1, int(round(float(vals.numel()) * self.aux_topk_fraction)))
        hard_vals = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return F.relu(hard_vals - self.aux_shell_ceiling).mean()

    def _barrier_shell_margin_loss(self, aux_prob: torch.Tensor, labels: torch.Tensor) -> torch.Tensor:
        barrier_vals = aux_prob[labels == 2].float()
        shell_vals = aux_prob[labels == 3].float()
        if barrier_vals.numel() == 0 or shell_vals.numel() == 0:
            return aux_prob.new_zeros(())
        k_pos = max(1, int(round(float(barrier_vals.numel()) * self.aux_topk_fraction)))
        k_neg = max(1, int(round(float(shell_vals.numel()) * self.aux_topk_fraction)))
        weak_barrier = torch.topk(barrier_vals, k=min(k_pos, barrier_vals.numel()), largest=False).values.mean()
        hard_shell = torch.topk(shell_vals, k=min(k_neg, shell_vals.numel()), largest=True).values.mean()
        return F.relu(hard_shell + self.aux_margin - weak_barrier)

    def forward(self, pred_logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        labels = self._labels(target).to(device=pred_logits.device)
        aux_prob = torch.sigmoid(pred_logits[:, 5].float())
        ridge_target, near_shell = self._soft_ridge_target(labels, aux_prob.dtype)
        total = total + self.aux_ridge_lambda * self._ridge_regression_loss(
            aux_prob, ridge_target, labels, near_shell
        )
        total = total + self.aux_shell_ceiling_lambda * self._shell_ceiling_loss(aux_prob, labels)
        total = total + self.aux_margin_lambda * self._barrier_shell_margin_loss(aux_prob, labels)
        if not torch.isfinite(total):
            raise ValueError(f"BFV3 candidate soft-ridge barrier-head loss produced non-finite loss: {float(total.detach().cpu())}")
        return total


