        labels = self._labels(target).to(device=pred_logits.device)
        aux_prob = torch.sigmoid(pred_logits[:, 5].float())
        total = total + self._barrier_contrast_loss(aux_prob, labels)
        if not torch.isfinite(total):
            raise ValueError(f"BFV3 dense-candidate barrier-contrast loss produced non-finite loss: {float(total.detach().cpu())}")
        return total


