class BoundaryFragmentV3CoreRecallRidgeDenseCandidateInstanceCoreGuardBarrierHeadLoss(
    BoundaryFragmentV3CoreRecallRidgeDenseCandidateBinaryBarrierHeadLoss
):
    """V197 dense barrier head with instance-aware semantic-core topology guards."""

    def __init__(
        self,
        base_loss: nn.Module,
        *,
        fragment_presence_lambda: float = 0.18,
        fragment_presence_floor: float = 0.52,
        fragment_core_mass_cap: float = 8.0,
        fragment_core_mass_lambda: float = 0.18,
        bridge_core_false_lambda: float = 0.18,
        bridge_core_margin_lambda: float = 0.12,
        bridge_core_margin: float = 0.20,
        bridge_topk_fraction: float = 0.03,
        **kwargs,
    ):
        super().__init__(base_loss, **kwargs)
        self.fragment_presence_lambda = float(fragment_presence_lambda)
        self.fragment_presence_floor = float(fragment_presence_floor)
        self.fragment_core_mass_cap = float(fragment_core_mass_cap)
        self.fragment_core_mass_lambda = float(fragment_core_mass_lambda)
        self.bridge_core_false_lambda = float(bridge_core_false_lambda)
        self.bridge_core_margin_lambda = float(bridge_core_margin_lambda)
        self.bridge_core_margin = float(bridge_core_margin)
        self.bridge_topk_fraction = float(bridge_topk_fraction)

    @staticmethod
    def _semantic_target(target):
        if isinstance(target, dict):
            if "semantic" not in target:
                raise KeyError("instance-core-guard loss requires target['semantic']")
            return target["semantic"]
        return target

    @staticmethod
    def _instance_target(target):
        if not isinstance(target, dict) or "instance" not in target:
            raise KeyError("instance-core-guard loss requires target['instance']")
        instance = target["instance"]
        if instance.ndim == 5 and instance.shape[1] == 1:
            instance = instance[:, 0]
        return instance.long()

    def _fragment_presence_loss(self, core_prob: torch.Tensor, labels: torch.Tensor, instance: torch.Tensor) -> torch.Tensor:
        losses = []
        for batch_idx in range(labels.shape[0]):
            inst = instance[batch_idx]
            lbl = labels[batch_idx]
            prob = core_prob[batch_idx]
            for frag_id in torch.unique(inst):
                fid = int(frag_id.detach().cpu())
                if fid <= 0 or fid > MAX_INSTANCE_ID:
                    continue
                core_mask = (inst == fid) & (lbl == 4)
                if not core_mask.any():
                    continue
                # [DATA][Risk:High][Scope:fragment_core_presence]
                # Core coverage can look acceptable in aggregate while a small
                # fragment has no usable marker. Use per-fragment target-core max
                # probability so coverage pressure stays local to each fragment.
                top_prob = prob[core_mask].float().max()
                losses.append(F.relu(self.fragment_presence_floor - top_prob))
        if not losses:
            return core_prob.new_zeros(())
        return torch.stack(losses).mean()

    def _fragment_core_mass_cap_loss(self, core_prob: torch.Tensor, labels: torch.Tensor, instance: torch.Tensor) -> torch.Tensor:
        losses = []
        for batch_idx in range(labels.shape[0]):
            inst = instance[batch_idx]
            lbl = labels[batch_idx]
            prob = core_prob[batch_idx].float()
            for frag_id in torch.unique(inst):
                fid = int(frag_id.detach().cpu())
                if fid <= 0 or fid > MAX_INSTANCE_ID:
                    continue
                fragment = inst == fid
                support = fragment & ((lbl == 2) | (lbl == 3) | (lbl == 4))
                if not support.any():
                    continue
                target_mass = (fragment & (lbl == 4)).float().sum()
                if not bool((target_mass > 0).detach().cpu().item()):
                    continue
                pred_mass = prob[support].sum()
                allowed = self.fragment_core_mass_cap * target_mass
                # [QC][Invariant:fragment_core_mass]
                # Broad anatomy-level core markers cause watershed markers to span
                # more than one fragment. This cap is per fragment, not per patch,
                # so it penalizes overgrown core mass without deleting small-frag
                # core presence.
                losses.append(F.relu(torch.log((pred_mass + 1.0) / (allowed + 1.0))).pow(2))
        if not losses:
            return core_prob.new_zeros(())
        return torch.stack(losses).mean()

    def _bridge_core_false_loss(self, core_prob: torch.Tensor, labels: torch.Tensor, instance: torch.Tensor) -> torch.Tensor:
        bridge = (instance > 0) & (instance <= MAX_INSTANCE_ID) & ((labels == 2) | (labels == 3))
        if not bridge.any():
            return core_prob.new_zeros(())
        vals = core_prob[bridge].float()
        k = max(1, int(round(float(vals.numel()) * self.bridge_topk_fraction)))
        return torch.topk(vals, k=min(k, vals.numel()), largest=True).values.mean()

    def _bridge_core_margin_loss(self, logits: torch.Tensor, labels: torch.Tensor, instance: torch.Tensor) -> torch.Tensor:
        bridge = (instance > 0) & (instance <= MAX_INSTANCE_ID) & ((labels == 2) | (labels == 3))
        if not bridge.any():
            return logits.new_zeros(())
        logits_f = logits.float()
        core_logit = logits_f[:, 4]
        separator_logit = logits_f[:, 2:4].amax(dim=1)
        return F.relu(self.bridge_core_margin + core_logit[bridge] - separator_logit[bridge]).mean()

    def forward(self, pred_logits: torch.Tensor, target) -> torch.Tensor:
        semantic_target = self._semantic_target(target)
        total = super().forward(pred_logits, semantic_target)
        labels = self._labels(semantic_target).to(device=pred_logits.device)
        instance = self._instance_target(target).to(device=pred_logits.device)
        if tuple(instance.shape) != tuple(labels.shape):
            raise ValueError(
                "instance-core-guard target shape mismatch: "
                f"instance={tuple(instance.shape)} labels={tuple(labels.shape)}"
            )
        prob = torch.softmax(pred_logits[:, :5].float(), dim=1)
        core_prob = prob[:, 4]
        # [AUDIT][Risk:High][Scope:multi_fragment_core_marker]
        # V211/V212 showed missing seedless support is not the main blocker.
        # These terms keep V197's six-channel contract and target only the
        # instance-aware failure where core probability becomes a bridge across
        # contact/shell voxels or grows too large within each fragment.
        total = total + self.fragment_presence_lambda * self._fragment_presence_loss(core_prob, labels, instance)
        total = total + self.fragment_core_mass_lambda * self._fragment_core_mass_cap_loss(core_prob, labels, instance)
        total = total + self.bridge_core_false_lambda * self._bridge_core_false_loss(core_prob, labels, instance)
        total = total + self.bridge_core_margin_lambda * self._bridge_core_margin_loss(pred_logits[:, :5], labels, instance)
        if not torch.isfinite(total):
            raise ValueError(f"BFV3 instance-core-guard barrier-head loss produced non-finite loss: {float(total.detach().cpu())}")
        return total


