class BICMV132SupportVetoGateLoss(BICMV130SupportTopologyRepairLoss):
    """V132 loss: repurpose row5 as an independent support-veto gate.

    V130 showed semantic support false bridges remain high-confidence. This
    objective does not ask row5 to be contact; row5 becomes a deployable support
    gate trained to keep true support and veto non-support bridge zones.
    """

    def __init__(self):
        super().__init__()
        self.gate_lambda = 1.85
        self.gate_bce_lambda = 0.62
        self.gate_tversky_lambda = 0.92
        self.gate_bridge_lambda = 1.22
        self.gate_bridge_bce_lambda = 0.54
        self.gate_positive_floor_lambda = 0.48
        self.gate_false_ceiling_lambda = 0.84
        self.gate_positive_floor = 0.74
        self.gate_false_ceiling = 0.12
        self.gate_positive_fraction = 0.18
        self.gate_bridge_fraction = 0.26
        self.gate_global_false_fraction = 0.018
        self.gate_tversky_alpha = 0.86
        self.gate_tversky_beta = 0.34
        self.semantic_support_lambda = 0.0
        self.core_teacher_lambda = 0.92
        self.semantic_teacher_lambda = 0.16
        self.topology_teacher_lambda = 0.94
        self.dense_contact_teacher_lambda = 0.0

    def _support_veto_gate_loss(
        self,
        gate_logit: torch.Tensor,
        semantic: torch.Tensor,
        instance: torch.Tensor,
    ) -> torch.Tensor:
        labels = semantic.to(device=gate_logit.device).long()
        if labels.ndim == 5 and int(labels.shape[1]) == 1:
            labels = labels[:, 0]
        if labels.ndim != 4:
            raise ValueError(f"BICMV132 expected semantic labels [B,D,H,W], got {tuple(labels.shape)}")
        labels = labels.clamp(0, 4)
        support_target = (labels >= 2) & (labels <= 4)
        bridge_zone = self._instance_bridge_zone(instance, support_target)
        boundary = self._support_boundary_band(support_target, int(self.instance_bridge_iters))
        gate_prob = torch.sigmoid(gate_logit).clamp(self.eps, 1.0 - self.eps)
        target_float = support_target.float()
        weights = (
            torch.ones_like(gate_prob)
            + 4.0 * boundary.float()
            + 8.0 * bridge_zone.float()
        )
        bce_raw = F.binary_cross_entropy_with_logits(gate_logit, target_float, reduction="none")
        loss = self.gate_bce_lambda * (bce_raw * weights).sum() / weights.sum().clamp_min(1.0)

        dims = tuple(range(1, gate_prob.ndim))
        tp = (gate_prob * target_float).sum(dim=dims)
        fp = (gate_prob * (1.0 - target_float)).sum(dim=dims)
        fn = ((1.0 - gate_prob) * target_float).sum(dim=dims)
        tversky = (tp + self.eps) / (
            tp
            + float(self.gate_tversky_alpha) * fp
            + float(self.gate_tversky_beta) * fn
            + self.eps
        )
        loss = loss + self.gate_tversky_lambda * (1.0 - tversky.mean())

        if support_target.any():
            low_pos = self._hard_values(gate_prob[support_target], self.gate_positive_fraction, largest=False)
            loss = loss + self.gate_positive_floor_lambda * F.relu(float(self.gate_positive_floor) - low_pos.mean())
        non_support = ~support_target
        if non_support.any():
            hard_false = self._hard_values(gate_prob[non_support], self.gate_global_false_fraction, largest=True)
            loss = loss + self.gate_false_ceiling_lambda * F.relu(
                hard_false.mean() - float(self.gate_false_ceiling)
            )
        if bridge_zone.any():
            bridge_prob = self._hard_values(gate_prob[bridge_zone], self.gate_bridge_fraction, largest=True)
            bridge_logit = self._hard_values(gate_logit[bridge_zone], self.gate_bridge_fraction, largest=True)
            # [AUDIT][Risk:High][Scope:v132_support_veto_gate]
            # Row5 is deliberately no longer a contact band. It is a support
            # veto gate, so the hardest multi-fragment non-support zones are
            # treated as negatives even if their semantic support logits are high.
            loss = loss + self.gate_bridge_lambda * (
                self.gate_bridge_bce_lambda * F.softplus(bridge_logit).mean()
                + F.relu(bridge_prob.mean() - float(self.gate_false_ceiling))
            )
        return loss

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if "teacher_logits" not in target:
            raise ValueError("BICMV132SupportVetoGateLoss requires target['teacher_logits'].")
        if "instance" not in target:
            raise ValueError("BICMV132SupportVetoGateLoss requires target['instance'].")
        logits = pred_logits.float()
        semantic = target["semantic"].to(logits.device)
        total = self.gate_lambda * self._support_veto_gate_loss(
            logits[:, 5],
            semantic,
            target["instance"],
        )
        if float(self.semantic_support_lambda) > 0.0:
            total = total + self.semantic_support_lambda * self._semantic_boundary_support_loss(
                logits[:, 0:5],
                semantic,
            )
        total = total + self._teacher_stability_loss(logits, target["teacher_logits"])
        if not torch.isfinite(total):
            raise ValueError(f"BICMV132SupportVetoGateLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV133SupportVetoSemanticLoss(BICMV132SupportVetoGateLoss):
    """V133 loss: support-veto gate plus semantic support co-adaptation."""

    def __init__(self):
        super().__init__()
        self.gate_lambda = 1.54
        self.semantic_support_lambda = 0.76
        self.semantic_teacher_lambda = 0.06
        self.topology_teacher_lambda = 0.92


class BICMV122WarmEdgeProductPrecisionLoss(BICMV113AdaptiveBoundaryProductLoss):
    """V122 loss: keep semantic-topology product contact with a precision lock.

    V120/V121 showed that redefining rows 7..9 as affinity graph edges is not a
    fulltrain candidate. V121 nevertheless exposed a recall-opening signal when
    rows 7..9 are warm-started from support geometry. V122 keeps the original
    `semantic_topology_v68` product contract and adds a teacher-relative
    negative-expansion lock so recall gains cannot be bought by broad false
    contact.
    """

    def __init__(self):
        super().__init__()
        self.adaptive_contact_lambda = 0.86
        self.precision_lock_lambda = 1.24
        self.core_teacher_lambda = 0.64
        self.semantic_teacher_lambda = 0.0
        self.topology_teacher_lambda = 0.0
        self.contact_precision_floor = 0.64
        self.contact_recall_floor = 0.58
        self.contact_positive_floor = 0.70
        self.dense_positive_floor = 0.70
        self.edge_positive_floor = 0.68
        self.contact_false_ceiling = 0.31
        self.contact_margin = 0.14
        self.contact_mass_ratio_ceiling = 0.72
        self.adaptive_recall_gain = 1.10
        self.adaptive_precision_gain = 2.45
        self.contact_positive_fraction = 0.36
        self.contact_false_fraction = 0.016
        self.no_contact_false_fraction = 0.012
        self.teacher_positive_gain = 0.055
        self.teacher_negative_margin = 0.030
        self.teacher_positive_gain_lambda = 0.36
        self.teacher_negative_expansion_lambda = 0.74
        self.product_soft_recall_lambda = 0.48
        self.product_soft_recall_floor = 0.56
        self.false_mass_budget_lambda = 0.42
        self.hard_false_bce_lambda = 0.18
        self.edge_false_bce_lambda = 0.14

    def _teacher_product_precision_lock_loss(
        self,
        dense_contact_logit: torch.Tensor,
        edge_logits: torch.Tensor,
        semantic: torch.Tensor,
        teacher_logits: torch.Tensor,
    ) -> torch.Tensor:
        dense_prob = torch.sigmoid(dense_contact_logit).clamp(self.eps, 1.0 - self.eps)
        edge_prob = torch.sigmoid(edge_logits).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        product = torch.sqrt((dense_prob * edge_prob).clamp(self.eps, 1.0))
        edge_logit_max = edge_logits.max(dim=1).values

        teacher = teacher_logits.to(device=dense_contact_logit.device, dtype=dense_contact_logit.dtype).detach()
        if teacher.shape[0] != dense_contact_logit.shape[0] or teacher.shape[2:] != dense_contact_logit.shape[1:]:
            raise ValueError(
                "BICMV122 teacher/student shape mismatch: "
                f"dense={tuple(dense_contact_logit.shape)} teacher={tuple(teacher.shape)}"
            )
        teacher_dense = torch.sigmoid(teacher[:, 5]).clamp(self.eps, 1.0 - self.eps)
        teacher_edge = torch.sigmoid(teacher[:, 7:10]).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_product = torch.sqrt((teacher_dense * teacher_edge).clamp(self.eps, 1.0))

        support = self._semantic_support_mask(semantic).to(dense_prob.device)
        band_contact = self._semantic_contact_band(semantic).to(dense_prob.device)
        losses: list[torch.Tensor] = []
        for b in range(int(dense_prob.shape[0])):
            pos = band_contact[b] & support[b]
            neg = support[b] & ~band_contact[b]
            outside = ~support[b]
            sample_loss = dense_prob.new_zeros(())

            if pos.any():
                dense_pos = dense_prob[b][pos]
                edge_pos = edge_prob[b][pos]
                product_pos = product[b][pos]
                teacher_pos = teacher_product[b][pos]
                low_dense = self._hard_mean(dense_pos, self.contact_positive_fraction, largest=False)
                low_edge = self._hard_mean(edge_pos, self.contact_positive_fraction, largest=False)
                low_product = self._hard_mean(product_pos, self.contact_positive_fraction, largest=False)
                soft_recall = torch.sigmoid(
                    (product_pos - 0.5) / max(float(self.contact_soft_recall_temperature), self.eps)
                ).mean()

                sample_loss = sample_loss + 0.48 * F.binary_cross_entropy_with_logits(
                    dense_contact_logit[b][pos],
                    torch.ones_like(dense_contact_logit[b][pos]),
                )
                sample_loss = sample_loss + 0.30 * F.binary_cross_entropy_with_logits(
                    edge_logit_max[b][pos],
                    torch.ones_like(edge_logit_max[b][pos]),
                )
                sample_loss = sample_loss + 0.76 * F.relu(float(self.contact_positive_floor) - low_product)
                sample_loss = sample_loss + 0.22 * F.relu(float(self.dense_positive_floor) - low_dense)
                sample_loss = sample_loss + 0.18 * F.relu(float(self.edge_positive_floor) - low_edge)
                sample_loss = sample_loss + self.product_soft_recall_lambda * F.relu(
                    float(self.product_soft_recall_floor) - soft_recall
                ).pow(2)
                # [AUDIT][Risk:High][Scope:v122_precision_recall_tradeoff]
                # V121 improved recall but violated precision. Positive expansion
                # is allowed only where it exceeds the V96 teacher on true contact
                # band voxels; negative expansion is penalized below.
                sample_loss = sample_loss + self.teacher_positive_gain_lambda * F.relu(
                    teacher_pos + float(self.teacher_positive_gain) - product_pos
                ).mean()

                if neg.any():
                    hard_product = self._hard_values(product[b][neg], self.contact_false_fraction, largest=True)
                    hard_dense_logits = self._hard_values(
                        dense_contact_logit[b][neg],
                        self.contact_false_fraction,
                        largest=True,
                    )
                    hard_edge_logits = self._hard_values(
                        edge_logit_max[b][neg],
                        self.contact_false_fraction,
                        largest=True,
                    )
                    hard_product_mean = hard_product.mean()
                    sample_loss = sample_loss + 0.62 * F.relu(
                        float(self.contact_margin) + hard_product_mean - low_product
                    )
                    sample_loss = sample_loss + 0.58 * F.relu(
                        hard_product_mean - float(self.contact_false_ceiling)
                    )
                    sample_loss = sample_loss + self.hard_false_bce_lambda * F.softplus(hard_dense_logits).mean()
                    sample_loss = sample_loss + self.edge_false_bce_lambda * F.softplus(hard_edge_logits).mean()

                    false_mass = product[b][neg].sum()
                    false_budget = pos.float().sum() * float(self.contact_mass_ratio_ceiling)
                    sample_loss = sample_loss + self.false_mass_budget_lambda * F.relu(
                        torch.log((false_mass + 1.0) / (false_budget + 1.0))
                    ).pow(2)

                    expansion = (
                        product[b][neg]
                        - teacher_product[b][neg]
                        - float(self.teacher_negative_margin)
                    ).clamp_min(0.0)
                    hard_expansion = self._hard_values(expansion, self.contact_false_fraction, largest=True)
                    if hard_expansion.numel() > 0:
                        # [QC][Invariant:teacher_negative_lock]
                        # The lock is relative to the measured V96 checkpoint, so
                        # V122 can add true positives without increasing the
                        # existing false-positive budget on non-contact support.
                        sample_loss = sample_loss + self.teacher_negative_expansion_lambda * hard_expansion.mean()
            elif neg.any():
                hard_product = self._hard_values(product[b][neg], self.no_contact_false_fraction, largest=True)
                hard_dense_logits = self._hard_values(
                    dense_contact_logit[b][neg],
                    self.no_contact_false_fraction,
                    largest=True,
                )
                hard_edge_logits = self._hard_values(
                    edge_logit_max[b][neg],
                    self.no_contact_false_fraction,
                    largest=True,
                )
                sample_loss = sample_loss + 0.46 * (
                    F.relu(hard_product.mean() - float(self.contact_false_ceiling))
                    + 0.30 * F.softplus(hard_dense_logits).mean()
                    + 0.24 * F.softplus(hard_edge_logits).mean()
                )

            if outside.any():
                outside_dense = self._hard_values(
                    dense_contact_logit[b][outside],
                    self.outside_support_fraction,
                    largest=True,
                )
                outside_edge = self._hard_values(
                    edge_logit_max[b][outside],
                    self.outside_support_fraction,
                    largest=True,
                )
                if outside_dense.numel() > 0:
                    sample_loss = sample_loss + 0.05 * (
                        F.softplus(outside_dense).mean()
                        + 0.6 * F.softplus(outside_edge).mean()
                    )
            losses.append(sample_loss)

        if not losses:
            return dense_prob.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if "teacher_logits" not in target:
            raise ValueError("BICMV122WarmEdgeProductPrecisionLoss requires target['teacher_logits'].")
        logits = pred_logits.float()
        semantic = target["semantic"].to(logits.device)
        total = self._semantic_boundary_support_loss(logits[:, 0:5], semantic)
        total = total + self.adaptive_contact_lambda * self._adaptive_product_contact_loss(
            logits[:, 5],
            logits[:, 7:10],
            semantic,
        )
        total = total + self.precision_lock_lambda * self._teacher_product_precision_lock_loss(
            logits[:, 5],
            logits[:, 7:10],
            semantic,
            target["teacher_logits"],
        )
        total = total + self._teacher_stability_loss(logits, target["teacher_logits"])
        if not torch.isfinite(total):
            raise ValueError(f"BICMV122WarmEdgeProductPrecisionLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV123HighRecallGateCleanupLoss(BICMV109PrecisionLockedRecallLoss):
    """V123 loss: row5 precision cleanup over a high-recall edge field.

    V121 opened contact recall through rows 7..9 but over-produced false
    contact. V122 tried to train edge rows and row5 together and still left
    precision low. V123 freezes the high-recall topology rows and trains only
    row5 as a dense gate, making the single question whether product precision
    can be recovered without losing the recall-opening edge state.
    """

    def __init__(self):
        super().__init__()
        self.dense_positive_bce_lambda = 0.62
        self.dense_positive_floor_lambda = 0.74
        self.product_positive_floor_lambda = 0.78
        self.product_rank_lambda = 0.58
        self.hard_false_bce_lambda = 0.34
        self.hard_false_ceiling_lambda = 0.72
        self.no_contact_false_lambda = 0.48
        self.outside_support_false_lambda = 0.06
        self.product_mass_ceiling_lambda = 0.0
        self.dense_positive_floor = 0.80
        self.product_positive_floor = 0.58
        self.product_margin = 0.16
        self.hard_false_ceiling = 0.34
        self.no_contact_false_ceiling = 0.28
        self.mass_ratio_ceiling = 0.82
        self.positive_low_fraction = 0.34
        self.hard_false_fraction = 0.020
        self.no_contact_false_fraction = 0.014
        self.soft_recall_lambda = 0.42
        self.soft_recall_floor = 0.54
        self.positive_teacher_gain_lambda = 0.18
        self.positive_teacher_gain = 0.02
        self.false_mass_budget_lambda = 0.82
        self.false_mass_budget_ratio = 0.42
        self.teacher_negative_expansion_lambda = 0.08
        self.teacher_negative_margin = 0.020


class BICMV124SupportConditionedEdgePrecisionLoss(BICMV113AdaptiveBoundaryProductLoss):
    """V124 loss: reduce rows7..9 false field under the existing product decoder.

    V123 showed row5 cleanup cannot remove the broad false-contact field created
    by V121 high-recall edge rows. V124 freezes semantic/core/row5 and trains
    only rows7..9 from the V121 checkpoint, directly suppressing non-contact
    support hard negatives while preserving contact-band recall against the
    teacher.
    """

    def __init__(self):
        super().__init__()
        self.edge_precision_lambda = 1.0
        self.product_positive_floor = 0.56
        self.edge_positive_floor = 0.60
        self.soft_recall_floor = 0.54
        self.soft_recall_temperature = 0.055
        self.teacher_positive_floor_margin = 0.010
        self.product_false_ceiling = 0.30
        self.edge_false_ceiling = 0.28
        self.product_margin = 0.16
        self.false_mass_budget_ratio = 0.44
        self.teacher_negative_margin = 0.018
        self.positive_fraction = 0.34
        self.false_fraction = 0.022
        self.no_contact_false_fraction = 0.014
        self.outside_support_fraction = 0.001
        self.positive_floor_lambda = 0.82
        self.soft_recall_lambda = 0.46
        self.positive_teacher_lambda = 0.22
        self.rank_lambda = 0.72
        self.false_ceiling_lambda = 0.84
        self.false_bce_lambda = 0.38
        self.false_mass_lambda = 0.86
        self.teacher_negative_lambda = 0.54
        self.axis_false_lambda = 0.24
        self.hard_negative_lambda = 0.34
        self.outside_false_lambda = 0.06
        self.core_teacher_lambda = 0.0
        self.semantic_teacher_lambda = 0.0
        self.topology_teacher_lambda = 0.0

    def _edge_precision_loss(
        self,
        dense_contact_logit: torch.Tensor,
        edge_logits: torch.Tensor,
        semantic: torch.Tensor,
        teacher_logits: torch.Tensor,
        hard_negative: torch.Tensor | None = None,
    ) -> torch.Tensor:
        dense_prob = torch.sigmoid(dense_contact_logit.detach()).clamp(self.eps, 1.0 - self.eps)
        edge_prob_axis = torch.sigmoid(edge_logits).clamp(self.eps, 1.0 - self.eps)
        edge_prob = edge_prob_axis.amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        edge_logit_max = edge_logits.max(dim=1).values
        product = torch.sqrt((dense_prob * edge_prob).clamp(self.eps, 1.0))

        teacher = teacher_logits.to(device=edge_logits.device, dtype=edge_logits.dtype).detach()
        if teacher.shape[0] != edge_logits.shape[0] or teacher.shape[2:] != edge_logits.shape[2:]:
            raise ValueError(
                "BICMV124 teacher/student shape mismatch: "
                f"edge={tuple(edge_logits.shape)} teacher={tuple(teacher.shape)}"
            )
        teacher_dense = torch.sigmoid(teacher[:, 5]).clamp(self.eps, 1.0 - self.eps)
        teacher_edge = torch.sigmoid(teacher[:, 7:10]).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_product = torch.sqrt((teacher_dense * teacher_edge).clamp(self.eps, 1.0))

        support = self._semantic_support_mask(semantic).to(edge_logits.device)
        contact = self._semantic_contact_band(semantic).to(edge_logits.device)
        hard_negative_mask = None
        if hard_negative is not None:
            hard_negative_mask = hard_negative.to(edge_logits.device).float()
            if hard_negative_mask.ndim == 5 and int(hard_negative_mask.shape[1]) == 1:
                hard_negative_mask = hard_negative_mask[:, 0]
            if hard_negative_mask.shape != support.shape:
                raise ValueError(
                    f"BICMV124 hard_negative shape mismatch: got {tuple(hard_negative_mask.shape)}, "
                    f"expected {tuple(support.shape)}"
                )
            hard_negative_mask = hard_negative_mask > 0.5

        losses: list[torch.Tensor] = []
        for b in range(int(edge_prob.shape[0])):
            pos = contact[b] & support[b]
            neg = support[b] & ~contact[b]
            outside = ~support[b]
            sample_loss = edge_prob.new_zeros(())

            if pos.any():
                product_pos = product[b][pos]
                edge_pos = edge_prob[b][pos]
                teacher_pos = teacher_product[b][pos]
                low_product = self._hard_mean(product_pos, self.positive_fraction, largest=False)
                low_edge = self._hard_mean(edge_pos, self.positive_fraction, largest=False)
                soft_recall = torch.sigmoid(
                    (product_pos - 0.5) / max(float(self.soft_recall_temperature), self.eps)
                ).mean()
                # [AUDIT][Risk:High][Scope:v124_recall_preservation]
                # V124 is allowed to reduce false edges, but not by collapsing the
                # V121 contact-band recall signal. Positive constraints are tied
                # to fixed 0.5 product behavior and the V121 teacher response.
                sample_loss = sample_loss + self.positive_floor_lambda * (
                    F.relu(float(self.product_positive_floor) - low_product)
                    + 0.45 * F.relu(float(self.edge_positive_floor) - low_edge)
                )
                sample_loss = sample_loss + self.soft_recall_lambda * F.relu(
                    float(self.soft_recall_floor) - soft_recall
                ).pow(2)
                sample_loss = sample_loss + self.positive_teacher_lambda * F.relu(
                    teacher_pos - float(self.teacher_positive_floor_margin) - product_pos
                ).mean()
                sample_loss = sample_loss + 0.24 * F.binary_cross_entropy_with_logits(
                    edge_logit_max[b][pos],
                    torch.ones_like(edge_logit_max[b][pos]),
                )

                if neg.any():
                    hard_product = self._hard_values(product[b][neg], self.false_fraction, largest=True)
                    hard_edge = self._hard_values(edge_prob[b][neg], self.false_fraction, largest=True)
                    hard_edge_logits = self._hard_values(edge_logit_max[b][neg], self.false_fraction, largest=True)
                    hard_product_mean = hard_product.mean()
                    sample_loss = sample_loss + self.rank_lambda * F.relu(
                        float(self.product_margin) + hard_product_mean - low_product
                    )
                    sample_loss = sample_loss + self.false_ceiling_lambda * (
                        F.relu(hard_product_mean - float(self.product_false_ceiling))
                        + 0.5 * F.relu(hard_edge.mean() - float(self.edge_false_ceiling))
                    )
                    sample_loss = sample_loss + self.false_bce_lambda * F.softplus(hard_edge_logits).mean()
                    false_mass = product[b][neg].sum()
                    false_budget = pos.float().sum() * float(self.false_mass_budget_ratio)
                    sample_loss = sample_loss + self.false_mass_lambda * F.relu(
                        torch.log((false_mass + 1.0) / (false_budget + 1.0))
                    ).pow(2)

                    expansion = (
                        product[b][neg]
                        - teacher_product[b][neg]
                        - float(self.teacher_negative_margin)
                    ).clamp_min(0.0)
                    hard_expansion = self._hard_values(expansion, self.false_fraction, largest=True)
                    if hard_expansion.numel() > 0:
                        # [QC][Invariant:v124_support_negative_lock]
                        # This is the key V124 variable: suppress expansion on
                        # non-contact support voxels while preserving true contact
                        # band response. Row5 and semantic/core rows are frozen by
                        # the trainer, so this isolates rows7..9 false field.
                        sample_loss = sample_loss + self.teacher_negative_lambda * hard_expansion.mean()

                    axis_neg = edge_prob_axis[b][:, neg]
                    if axis_neg.numel() > 0:
                        hard_axis = self._hard_values(axis_neg.reshape(-1), self.false_fraction, largest=True)
                        hard_axis_logits = self._hard_values(edge_logits[b][:, neg].reshape(-1), self.false_fraction, largest=True)
                        sample_loss = sample_loss + self.axis_false_lambda * (
                            F.relu(hard_axis.mean() - float(self.edge_false_ceiling))
                            + 0.3 * F.softplus(hard_axis_logits).mean()
                        )
            elif neg.any():
                hard_product = self._hard_values(product[b][neg], self.no_contact_false_fraction, largest=True)
                hard_logits = self._hard_values(edge_logit_max[b][neg], self.no_contact_false_fraction, largest=True)
                sample_loss = sample_loss + 0.48 * (
                    F.relu(hard_product.mean() - float(self.product_false_ceiling))
                    + 0.34 * F.softplus(hard_logits).mean()
                )

            if hard_negative_mask is not None:
                hard_mask = hard_negative_mask[b] & ~contact[b]
                if hard_mask.any():
                    hard_product = self._hard_values(product[b][hard_mask], self.false_fraction, largest=True)
                    hard_logits = self._hard_values(edge_logit_max[b][hard_mask], self.false_fraction, largest=True)
                    sample_loss = sample_loss + self.hard_negative_lambda * (
                        F.relu(hard_product.mean() - float(self.product_false_ceiling))
                        + 0.35 * F.softplus(hard_logits).mean()
                    )

            if outside.any():
                outside_product = self._hard_values(product[b][outside], self.outside_support_fraction, largest=True)
                outside_logits = self._hard_values(edge_logit_max[b][outside], self.outside_support_fraction, largest=True)
                if outside_product.numel() > 0:
                    sample_loss = sample_loss + self.outside_false_lambda * (
                        F.relu(outside_product.mean() - float(self.product_false_ceiling))
                        + 0.35 * F.softplus(outside_logits).mean()
                    )
            losses.append(sample_loss)

        if not losses:
            return edge_prob.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if "teacher_logits" not in target:
            raise ValueError("BICMV124SupportConditionedEdgePrecisionLoss requires target['teacher_logits'].")
        logits = pred_logits.float()
        semantic = target["semantic"].to(logits.device)
        total = self.edge_precision_lambda * self._edge_precision_loss(
            logits[:, 5],
            logits[:, 7:10],
            semantic,
            target["teacher_logits"],
            target.get("hard_negative"),
        )
        if not torch.isfinite(total):
            raise ValueError(
                f"BICMV124SupportConditionedEdgePrecisionLoss produced non-finite loss: {float(total.detach().cpu())}"
            )
        return total


class BICMV125SaturatedEdgeDenseGateLoss(BICMV102DistanceRankDenseGateLoss):
    """V125 loss: recalibrate row5 when the V121/V124 edge field is saturated.

    Full-volume diagnostics after V124 showed rows 7..9 are almost everywhere
    1.0 inside support. Under `semantic_topology_v68`, contact then becomes
    effectively `sqrt(row5)`, so row5 must carry the true contact geometry.
    This loss keeps the fixed decoder contract, preserves semantic/core/edge
    outputs with a frozen teacher, and trains row5 plus decoder features against
    a distance-ranked false-field budget.
    """

    def __init__(self):
        super().__init__()
        self.gate_lambda = 1.35
        self.semantic_distill_lambda = 0.16
        self.support_distill_lambda = 0.18
        self.core_distill_lambda = 0.34
        self.edge_distill_lambda = 0.44
        self.distill_temperature = 2.0
        self.dense_positive_bce_lambda = 0.82
        self.dense_positive_floor_lambda = 0.58
        self.product_positive_floor_lambda = 0.82
        self.soft_recall_lambda = 0.86
        self.soft_recall_floor = 0.62
        self.soft_recall_temperature = 0.045
        self.dense_positive_floor = 0.44
        self.product_positive_floor = 0.56
        self.positive_low_fraction = 0.46
        self.shoulder1_bce_lambda = 0.30
        self.shoulder2_bce_lambda = 0.22
        self.shoulder1_target = 0.18
        self.shoulder2_target = 0.08
        self.shoulder1_product_ceiling = 0.46
        self.shoulder2_product_ceiling = 0.38
        self.shoulder1_product_ceiling_lambda = 0.30
        self.shoulder2_product_ceiling_lambda = 0.24
        self.product_rank_lambda = 0.62
        self.product_margin = 0.12
        self.hard_false_bce_lambda = 0.42
        self.hard_false_ceiling_lambda = 0.70
        self.far_false_fraction = 0.080
        self.far_mid_fraction = 0.24
        self.far_product_ceiling = 0.43
        self.far_mid_product_ceiling = 0.31
        self.far_mid_ceiling_lambda = 0.34
        self.false_mass_budget_lambda = 0.72
        self.false_mass_budget_ratio = 0.56
        self.no_contact_false_lambda = 0.62
        self.no_contact_false_fraction = 0.026
        self.no_contact_false_ceiling = 0.30
        self.outside_support_false_lambda = 0.06
        self.outside_support_fraction = 0.002
        self.teacher_positive_preserve_lambda = 0.38
        self.teacher_positive_drop_margin = 0.025
        self.teacher_far_contraction_lambda = 0.46
        self.teacher_far_contraction_margin = 0.075

    def _teacher_distill_loss(self, logits: torch.Tensor, teacher_logits: torch.Tensor) -> torch.Tensor:
        teacher = teacher_logits.to(device=logits.device, dtype=logits.dtype).detach()
        if teacher.shape != logits.shape:
            raise ValueError(
                "BICMV125 teacher_logits shape mismatch: "
                f"student={tuple(logits.shape)} teacher={tuple(teacher.shape)}"
            )
        temperature = max(float(self.distill_temperature), self.eps)
        student_sem_log = F.log_softmax(logits[:, 0:5] / temperature, dim=1)
        teacher_sem_prob = torch.softmax(teacher[:, 0:5] / temperature, dim=1)
        semantic_kl = (
            teacher_sem_prob
            * (torch.log(teacher_sem_prob.clamp_min(self.eps)) - student_sem_log)
        ).sum(dim=1).mean() * (temperature ** 2)

        student_support = torch.softmax(logits[:, 0:5], dim=1)[:, 2:5].sum(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_support = torch.softmax(teacher[:, 0:5], dim=1)[:, 2:5].sum(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_core = torch.sigmoid(teacher[:, 6]).clamp(self.eps, 1.0 - self.eps)
        teacher_edge = torch.sigmoid(teacher[:, 7:10]).clamp(self.eps, 1.0 - self.eps)

        # [AUDIT][Risk:High][Scope:v125_feature_opening]
        # V125 opens decoder features because row5-only V123 barely moved the
        # full-volume output. Distillation excludes row5, the variable under
        # test, but preserves semantic support, core seed topology, and the
        # already-measured saturated edge state so contact changes remain
        # attributable to the dense gate.
        return (
            self.semantic_distill_lambda * semantic_kl
            + self.support_distill_lambda * F.mse_loss(student_support, teacher_support)
            + self.core_distill_lambda * F.binary_cross_entropy_with_logits(logits[:, 6], teacher_core)
            + self.edge_distill_lambda * F.binary_cross_entropy_with_logits(logits[:, 7:10], teacher_edge)
        )

    def _saturated_edge_dense_gate_loss(
        self,
        dense_contact_logit: torch.Tensor,
        edge_logits: torch.Tensor,
        semantic: torch.Tensor,
        teacher_logits: torch.Tensor,
    ) -> torch.Tensor:
        dense_prob = torch.sigmoid(dense_contact_logit).clamp(self.eps, 1.0 - self.eps)
        edge_prob = torch.sigmoid(edge_logits).amax(dim=1).detach().clamp(self.eps, 1.0 - self.eps)
        product = torch.sqrt((dense_prob * edge_prob).clamp(self.eps, 1.0))

        teacher = teacher_logits.to(device=dense_contact_logit.device, dtype=dense_contact_logit.dtype).detach()
        if teacher.shape[0] != dense_contact_logit.shape[0] or teacher.shape[2:] != dense_contact_logit.shape[1:]:
            raise ValueError(
                "BICMV125 teacher/student shape mismatch: "
                f"dense={tuple(dense_contact_logit.shape)} teacher={tuple(teacher.shape)}"
            )
        teacher_dense = torch.sigmoid(teacher[:, 5]).clamp(self.eps, 1.0 - self.eps)
        teacher_edge = torch.sigmoid(teacher[:, 7:10]).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_product = torch.sqrt((teacher_dense * teacher_edge).clamp(self.eps, 1.0))

        support = self._semantic_support_mask(semantic).to(dense_prob.device)
        band_contact = self._semantic_contact_band(semantic).to(dense_prob.device)
        shoulder1_all = self._dilate_mask(band_contact, radius=1) & support
        shoulder2_all = self._dilate_mask(band_contact, radius=3) & support
        losses: list[torch.Tensor] = []

        for b in range(int(dense_prob.shape[0])):
            pos = band_contact[b] & support[b]
            shoulder1 = shoulder1_all[b] & ~pos
            shoulder2 = shoulder2_all[b] & ~shoulder1_all[b]
            far = support[b] & ~shoulder2_all[b]
            outside = ~support[b]
            sample_loss = dense_prob.new_zeros(())

            if pos.any():
                dense_pos = dense_prob[b][pos]
                product_pos = product[b][pos]
                teacher_pos = teacher_product[b][pos]
                low_dense = self._hard_mean(dense_pos, self.positive_low_fraction, largest=False)
                low_product = self._hard_mean(product_pos, self.positive_low_fraction, largest=False)
                soft_recall = torch.sigmoid(
                    (product_pos - 0.5) / max(float(self.soft_recall_temperature), self.eps)
                ).mean()

                # [METRIC][Risk:High][Scope:v125_fixed_threshold_proxy]
                # With rows7..9 saturated, the fixed product gate promotes a
                # voxel when row5 is roughly above 0.25. Positive supervision
                # therefore targets product recall directly, while far support
                # below suppresses the measured 30k false-positive field.
                sample_loss = sample_loss + self.dense_positive_floor_lambda * F.relu(
                    self.dense_positive_floor - low_dense
                )
                sample_loss = sample_loss + self.product_positive_floor_lambda * F.relu(
                    self.product_positive_floor - low_product
                )
                sample_loss = sample_loss + self.soft_recall_lambda * F.relu(
                    self.soft_recall_floor - soft_recall
                ).pow(2)
                sample_loss = sample_loss + self.teacher_positive_preserve_lambda * F.relu(
                    teacher_pos - float(self.teacher_positive_drop_margin) - product_pos
                ).mean()
                sample_loss = sample_loss + self.dense_positive_bce_lambda * F.binary_cross_entropy_with_logits(
                    dense_contact_logit[b][pos],
                    torch.ones_like(dense_contact_logit[b][pos]),
                )

                if shoulder1.any():
                    shoulder1_logits = dense_contact_logit[b][shoulder1]
                    hard_shoulder1 = self._hard_mean(product[b][shoulder1], self.hard_false_fraction, largest=True)
                    sample_loss = sample_loss + self.shoulder1_bce_lambda * self._soft_target_bce(
                        shoulder1_logits,
                        self.shoulder1_target,
                    )
                    sample_loss = sample_loss + self.shoulder1_product_ceiling_lambda * F.relu(
                        hard_shoulder1 - self.shoulder1_product_ceiling
                    )

                if shoulder2.any():
                    shoulder2_logits = dense_contact_logit[b][shoulder2]
                    hard_shoulder2 = self._hard_mean(product[b][shoulder2], self.hard_false_fraction, largest=True)
                    sample_loss = sample_loss + self.shoulder2_bce_lambda * self._soft_target_bce(
                        shoulder2_logits,
                        self.shoulder2_target,
                    )
                    sample_loss = sample_loss + self.shoulder2_product_ceiling_lambda * F.relu(
                        hard_shoulder2 - self.shoulder2_product_ceiling
                    )

                if far.any():
                    hard_product_vals = self._hard_values(product[b][far], self.far_false_fraction, largest=True)
                    hard_dense_logits = self._hard_values(
                        dense_contact_logit[b][far],
                        self.far_false_fraction,
                        largest=True,
                    )
                    hard_teacher_vals = self._hard_values(teacher_product[b][far], self.far_false_fraction, largest=True)
                    hard_product = hard_product_vals.mean()
                    mid_product = self._hard_values(product[b][far], self.far_mid_fraction, largest=True).mean()
                    sample_loss = sample_loss + self.product_rank_lambda * F.relu(
                        self.product_margin + hard_product - low_product
                    )
                    sample_loss = sample_loss + self.hard_false_ceiling_lambda * F.relu(
                        hard_product - self.far_product_ceiling
                    )
                    sample_loss = sample_loss + self.far_mid_ceiling_lambda * F.relu(
                        mid_product - self.far_mid_product_ceiling
                    )
                    sample_loss = sample_loss + self.hard_false_bce_lambda * F.softplus(
                        hard_dense_logits
                    ).mean()
                    # [QC][Invariant:teacher_relative_contraction]
                    # The V121/V124 far-support false field is already too
                    # large. Unlike V109, this lock is intentionally
                    # contractive on far negatives instead of merely preventing
                    # further expansion.
                    sample_loss = sample_loss + self.teacher_far_contraction_lambda * F.relu(
                        hard_product_vals
                        - hard_teacher_vals
                        + float(self.teacher_far_contraction_margin)
                    ).mean()

                false_mass = product[b][far].sum() if far.any() else product[b].new_zeros(())
                false_budget = pos.float().sum() * float(self.false_mass_budget_ratio)
                sample_loss = sample_loss + self.false_mass_budget_lambda * F.relu(
                    torch.log((false_mass + 1.0) / (false_budget + 1.0))
                ).pow(2)
            elif far.any():
                hard_product_vals = self._hard_values(product[b][far], self.no_contact_false_fraction, largest=True)
                hard_dense_logits = self._hard_values(
                    dense_contact_logit[b][far],
                    self.no_contact_false_fraction,
                    largest=True,
                )
                sample_loss = sample_loss + self.no_contact_false_lambda * (
                    F.softplus(hard_dense_logits).mean()
                    + F.relu(hard_product_vals.mean() - self.no_contact_false_ceiling)
                )

            if outside.any():
                outside_logits = self._hard_values(
                    dense_contact_logit[b][outside],
                    self.outside_support_fraction,
                    largest=True,
                )
                if outside_logits.numel() > 0:
                    sample_loss = sample_loss + self.outside_support_false_lambda * F.softplus(
                        outside_logits
                    ).mean()
            losses.append(sample_loss)

        if not losses:
            return dense_prob.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if "teacher_logits" not in target:
            raise ValueError("BICMV125SaturatedEdgeDenseGateLoss requires target['teacher_logits'].")
        logits = pred_logits.float()
        semantic = target["semantic"].to(logits.device)
        total = self.gate_lambda * self._saturated_edge_dense_gate_loss(
            logits[:, 5],
            logits[:, 7:10],
            semantic,
            target["teacher_logits"],
        )
        total = total + self._teacher_distill_loss(logits, target["teacher_logits"])
        if not torch.isfinite(total):
            raise ValueError(f"BICMV125SaturatedEdgeDenseGateLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV126LocalAdjacencyProductLoss(BICMV125SaturatedEdgeDenseGateLoss):
    """V126 loss: local instance-adjacency contrast under semantic_topology_v68.

    V125 confirmed row5 can move but remains on the same precision/recall
    tradeoff. V126 adds a different source of separability: sidecar instance
    IDs define local edges where neighboring voxels are either same-fragment
    negatives or different-fragment fracture positives. Rows 7..9 are trained
    back into break probabilities while row5 learns the voxel contact gate.
    """

    def __init__(self):
        super().__init__()
        self.gate_lambda = 0.92
        self.edge_adjacency_lambda = 1.45
        self.edge_pos_floor = 0.68
        self.edge_same_false_ceiling = 0.18
        self.edge_support_false_ceiling = 0.26
        self.edge_margin = 0.20
        self.edge_pos_fraction = 0.36
        self.edge_same_fraction = 0.020
        self.edge_support_fraction = 0.026
        self.edge_background_fraction = 0.002
        self.edge_pos_bce_lambda = 0.64
        self.edge_same_bce_lambda = 0.72
        self.edge_support_bce_lambda = 0.46
        self.edge_rank_lambda = 0.62
        self.edge_background_lambda = 0.06
        self.product_positive_floor = 0.58
        self.soft_recall_floor = 0.58
        self.dense_positive_floor = 0.38
        self.product_rank_lambda = 0.54
        self.hard_false_ceiling_lambda = 0.56
        self.false_mass_budget_lambda = 0.58
        self.false_mass_budget_ratio = 0.50
        self.teacher_far_contraction_lambda = 0.18
        self.semantic_distill_lambda = 0.18
        self.support_distill_lambda = 0.18
        self.core_distill_lambda = 0.38
        self.edge_distill_lambda = 0.0

    @staticmethod
    def _edge_voxel_mask(edge_mask: torch.Tensor) -> torch.Tensor:
        if edge_mask.ndim != 5 or int(edge_mask.shape[1]) != 3:
            raise ValueError(f"BICMV126 expected edge mask [B,3,D,H,W], got {tuple(edge_mask.shape)}")
        edge = edge_mask.bool()
        vox = torch.zeros(
            (int(edge.shape[0]), *tuple(int(v) for v in edge.shape[2:])),
            dtype=torch.bool,
            device=edge.device,
        )
        for axis in range(3):
            e_sl = [slice(None)] * 5
            a_sl = [slice(None)] * 4
            b_sl = [slice(None)] * 4
            e_sl[1] = axis
            e_sl[axis + 2] = slice(0, -1)
            a_sl[axis + 1] = slice(0, -1)
            b_sl[axis + 1] = slice(1, None)
            edge_axis = edge[tuple(e_sl)]
            a_view = vox[tuple(a_sl)]
            b_view = vox[tuple(b_sl)]
            a_view |= edge_axis
            b_view |= edge_axis
            vox[tuple(a_sl)] = a_view
            vox[tuple(b_sl)] = b_view
        return vox

    @staticmethod
    def _instance_edge_context_masks(
        instance: torch.Tensor,
        edge_valid: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        inst = instance.long()
        if inst.ndim == 5 and int(inst.shape[1]) == 1:
            inst = inst[:, 0]
        if inst.ndim != 4:
            raise ValueError(f"BICMV126 expected instance labels [B,D,H,W], got {tuple(inst.shape)}")
        valid = edge_valid.float() > 0.5
        expected_shape = (int(inst.shape[0]), 3, *tuple(int(v) for v in inst.shape[1:]))
        if tuple(valid.shape) != expected_shape:
            raise ValueError(
                f"BICMV126 edge_valid shape mismatch: expected {expected_shape}, got {tuple(valid.shape)}"
            )
        same = torch.zeros(expected_shape, dtype=torch.bool, device=inst.device)
        diff = torch.zeros_like(same)
        foreground_touch = torch.zeros_like(same)
        for axis in range(3):
            a_sl = [slice(None)] * 4
            b_sl = [slice(None)] * 4
            out_sl = [slice(None)] * 5
            a_sl[axis + 1] = slice(0, -1)
            b_sl[axis + 1] = slice(1, None)
            out_sl[1] = axis
            out_sl[axis + 2] = slice(0, -1)
            a = inst[tuple(a_sl)]
            b = inst[tuple(b_sl)]
            valid_axis = valid[tuple(out_sl)]
            a_fg = a > 0
            b_fg = b > 0
            same[tuple(out_sl)] = valid_axis & a_fg & b_fg & (a == b)
            diff[tuple(out_sl)] = valid_axis & a_fg & b_fg & (a != b)
            foreground_touch[tuple(out_sl)] = valid_axis & (a_fg | b_fg)
        return same, diff, foreground_touch

    def _edge_adjacency_contrast_loss(
        self,
        edge_logits: torch.Tensor,
        target: dict[str, torch.Tensor],
    ) -> torch.Tensor:
        for key in ("edge_break", "edge_valid", "instance"):
            if key not in target:
                raise ValueError(f"BICMV126LocalAdjacencyProductLoss requires target[{key!r}].")
        edge_prob = torch.sigmoid(edge_logits).clamp(self.eps, 1.0 - self.eps)
        edge_break = target["edge_break"].to(edge_logits.device).float() > 0.5
        edge_valid = target["edge_valid"].to(edge_logits.device).float() > 0.5
        same, _diff, foreground_touch = self._instance_edge_context_masks(
            target["instance"].to(edge_logits.device),
            edge_valid.float(),
        )
        valid = edge_valid
        if tuple(edge_prob.shape) != tuple(edge_break.shape):
            raise ValueError(
                f"BICMV126 edge shape mismatch: logits={tuple(edge_logits.shape)} "
                f"edge_break={tuple(edge_break.shape)}"
            )
        losses: list[torch.Tensor] = []
        for b in range(int(edge_prob.shape[0])):
            pos = edge_break[b] & valid[b]
            same_neg = same[b] & (~edge_break[b]) & valid[b]
            support_neg = foreground_touch[b] & (~same[b]) & (~edge_break[b]) & valid[b]
            background_neg = (~foreground_touch[b]) & valid[b]
            sample_loss = edge_prob.new_zeros(())

            if pos.any():
                pos_prob = edge_prob[b][pos]
                low_pos = self._hard_mean(pos_prob, self.edge_pos_fraction, largest=False)
                sample_loss = sample_loss + self.edge_pos_bce_lambda * F.binary_cross_entropy_with_logits(
                    edge_logits[b][pos],
                    torch.ones_like(edge_logits[b][pos]),
                )
                sample_loss = sample_loss + F.relu(float(self.edge_pos_floor) - low_pos)

                if same_neg.any():
                    hard_same = self._hard_values(edge_prob[b][same_neg], self.edge_same_fraction, largest=True)
                    hard_same_logits = self._hard_values(edge_logits[b][same_neg], self.edge_same_fraction, largest=True)
                    sample_loss = sample_loss + self.edge_rank_lambda * F.relu(
                        float(self.edge_margin) + hard_same.mean() - low_pos
                    )
                    sample_loss = sample_loss + self.edge_same_bce_lambda * F.softplus(hard_same_logits).mean()
                    sample_loss = sample_loss + 0.58 * F.relu(
                        hard_same.mean() - float(self.edge_same_false_ceiling)
                    )

                if support_neg.any():
                    hard_support = self._hard_values(edge_prob[b][support_neg], self.edge_support_fraction, largest=True)
                    hard_support_logits = self._hard_values(edge_logits[b][support_neg], self.edge_support_fraction, largest=True)
                    sample_loss = sample_loss + 0.42 * self.edge_rank_lambda * F.relu(
                        float(self.edge_margin) + hard_support.mean() - low_pos
                    )
                    sample_loss = sample_loss + self.edge_support_bce_lambda * F.softplus(hard_support_logits).mean()
                    sample_loss = sample_loss + 0.42 * F.relu(
                        hard_support.mean() - float(self.edge_support_false_ceiling)
                    )
            elif same_neg.any() or support_neg.any():
                neg = same_neg | support_neg
                hard_neg = self._hard_values(edge_prob[b][neg], self.edge_support_fraction, largest=True)
                hard_logits = self._hard_values(edge_logits[b][neg], self.edge_support_fraction, largest=True)
                sample_loss = sample_loss + 0.55 * (
                    F.softplus(hard_logits).mean()
                    + F.relu(hard_neg.mean() - float(self.edge_support_false_ceiling))
                )

            if background_neg.any():
                hard_bg = self._hard_values(edge_prob[b][background_neg], self.edge_background_fraction, largest=True)
                hard_bg_logits = self._hard_values(edge_logits[b][background_neg], self.edge_background_fraction, largest=True)
                if hard_bg.numel() > 0:
                    sample_loss = sample_loss + self.edge_background_lambda * (
                        F.softplus(hard_bg_logits).mean()
                        + F.relu(hard_bg.mean() - float(self.edge_support_false_ceiling))
                    )
            losses.append(sample_loss)
        if not losses:
            return edge_prob.new_zeros(())
        # [AUDIT][Risk:High][Scope:v126_instance_adjacency]
        # This is the first post-V125 loss term that directly uses fragment IDs
        # to separate local fracture-positive edges from same-fragment support
        # negatives. It targets the observed saturated edge failure instead of
        # retuning only row5 thresholds.
        return torch.stack(losses).mean()

    def _local_adjacency_product_loss(
        self,
        dense_contact_logit: torch.Tensor,
        edge_logits: torch.Tensor,
        semantic: torch.Tensor,
        target: dict[str, torch.Tensor],
        teacher_logits: torch.Tensor,
    ) -> torch.Tensor:
        edge_break = target["edge_break"].to(dense_contact_logit.device).float() > 0.5
        pair_contact = self._edge_voxel_mask(edge_break)
        if "contact" in target:
            contact_target = target["contact"].to(dense_contact_logit.device).float()
            if contact_target.ndim == 5 and int(contact_target.shape[1]) == 1:
                contact_target = contact_target[:, 0]
            pair_contact = pair_contact | (contact_target > 0.5)
        semantic_contact = self._semantic_contact_band(semantic).to(dense_contact_logit.device)
        support = self._semantic_support_mask(semantic).to(dense_contact_logit.device)
        product_pos_mask = (semantic_contact | pair_contact) & support

        dense_prob = torch.sigmoid(dense_contact_logit).clamp(self.eps, 1.0 - self.eps)
        edge_prob = torch.sigmoid(edge_logits).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        product = torch.sqrt((dense_prob * edge_prob).clamp(self.eps, 1.0))
        teacher = teacher_logits.to(device=dense_contact_logit.device, dtype=dense_contact_logit.dtype).detach()
        teacher_dense = torch.sigmoid(teacher[:, 5]).clamp(self.eps, 1.0 - self.eps)
        teacher_edge = torch.sigmoid(teacher[:, 7:10]).amax(dim=1).clamp(self.eps, 1.0 - self.eps)
        teacher_product = torch.sqrt((teacher_dense * teacher_edge).clamp(self.eps, 1.0))

        shoulder1_all = self._dilate_mask(product_pos_mask, radius=1) & support
        shoulder2_all = self._dilate_mask(product_pos_mask, radius=3) & support
        losses: list[torch.Tensor] = []
        for b in range(int(product.shape[0])):
            pos = product_pos_mask[b]
            shoulder1 = shoulder1_all[b] & ~pos
            shoulder2 = shoulder2_all[b] & ~shoulder1_all[b]
            far = support[b] & ~shoulder2_all[b]
            outside = ~support[b]
            sample_loss = product.new_zeros(())

            if pos.any():
                dense_pos = dense_prob[b][pos]
                product_pos = product[b][pos]
                low_dense = self._hard_mean(dense_pos, self.positive_low_fraction, largest=False)
                low_product = self._hard_mean(product_pos, self.positive_low_fraction, largest=False)
                soft_recall = torch.sigmoid(
                    (product_pos - 0.5) / max(float(self.soft_recall_temperature), self.eps)
                ).mean()
                sample_loss = sample_loss + self.dense_positive_floor_lambda * F.relu(
                    self.dense_positive_floor - low_dense
                )
                sample_loss = sample_loss + self.product_positive_floor_lambda * F.relu(
                    self.product_positive_floor - low_product
                )
                sample_loss = sample_loss + self.soft_recall_lambda * F.relu(
                    self.soft_recall_floor - soft_recall
                ).pow(2)
                sample_loss = sample_loss + self.dense_positive_bce_lambda * F.binary_cross_entropy_with_logits(
                    dense_contact_logit[b][pos],
                    torch.ones_like(dense_contact_logit[b][pos]),
                )

                if shoulder1.any():
                    sample_loss = sample_loss + self.shoulder1_bce_lambda * self._soft_target_bce(
                        dense_contact_logit[b][shoulder1],
                        self.shoulder1_target,
                    )
                if shoulder2.any():
                    sample_loss = sample_loss + self.shoulder2_bce_lambda * self._soft_target_bce(
                        dense_contact_logit[b][shoulder2],
                        self.shoulder2_target,
                    )
                if far.any():
                    hard_product = self._hard_values(product[b][far], self.far_false_fraction, largest=True)
                    hard_dense_logits = self._hard_values(
                        dense_contact_logit[b][far],
                        self.far_false_fraction,
                        largest=True,
                    )
                    hard_teacher = self._hard_values(teacher_product[b][far], self.far_false_fraction, largest=True)
                    sample_loss = sample_loss + self.product_rank_lambda * F.relu(
                        self.product_margin + hard_product.mean() - low_product
                    )
                    sample_loss = sample_loss + self.hard_false_ceiling_lambda * F.relu(
                        hard_product.mean() - self.far_product_ceiling
                    )
                    sample_loss = sample_loss + self.hard_false_bce_lambda * F.softplus(hard_dense_logits).mean()
                    sample_loss = sample_loss + self.teacher_far_contraction_lambda * F.relu(
                        hard_product - hard_teacher + float(self.teacher_far_contraction_margin)
                    ).mean()
                    false_budget = pos.float().sum() * float(self.false_mass_budget_ratio)
                    sample_loss = sample_loss + self.false_mass_budget_lambda * F.relu(
                        torch.log((product[b][far].sum() + 1.0) / (false_budget + 1.0))
                    ).pow(2)
            elif (support[b]).any():
                hard_product = self._hard_values(product[b][support[b]], self.no_contact_false_fraction, largest=True)
                hard_dense_logits = self._hard_values(
                    dense_contact_logit[b][support[b]],
                    self.no_contact_false_fraction,
                    largest=True,
                )
                sample_loss = sample_loss + self.no_contact_false_lambda * (
                    F.softplus(hard_dense_logits).mean()
                    + F.relu(hard_product.mean() - self.no_contact_false_ceiling)
                )

            if outside.any():
                outside_logits = self._hard_values(
                    dense_contact_logit[b][outside],
                    self.outside_support_fraction,
                    largest=True,
                )
                if outside_logits.numel() > 0:
                    sample_loss = sample_loss + self.outside_support_false_lambda * F.softplus(
                        outside_logits
                    ).mean()
            losses.append(sample_loss)
        if not losses:
            return product.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if "teacher_logits" not in target:
            raise ValueError("BICMV126LocalAdjacencyProductLoss requires target['teacher_logits'].")
        logits = pred_logits.float()
        semantic = target["semantic"].to(logits.device)
        total = self.gate_lambda * self._local_adjacency_product_loss(
            logits[:, 5],
            logits[:, 7:10],
            semantic,
            target,
            target["teacher_logits"],
        )
        total = total + self.edge_adjacency_lambda * self._edge_adjacency_contrast_loss(
            logits[:, 7:10],
            target,
        )
        total = total + self._teacher_distill_loss(logits, target["teacher_logits"])
        if not torch.isfinite(total):
            raise ValueError(f"BICMV126LocalAdjacencyProductLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV39EdgePrimaryLoss(BICMV38EdgeAffinityLoss):
    """V39 edge-primary diagnostic loss.

    [AUDIT][Risk:High][Scope:root_cause_response]
    V38 proved that sidecar alignment and runtime were valid, but the fixed
    ROI contact gate erased all contact on full-volume case003. V39 keeps the
    same 8-channel output and sidecars, then removes ROI presence as a hard
    training objective. The single question is whether explicit edge-break
    supervision can survive the fixed 0.5 full-volume decoder without ROI
    scalar gating.

    [QA][Gate:case003_before_159][Status:Required]
    This loss is only justified for the locked 003 diagnostic. It must pass
    support/core/contact/IoU-F gates before 159, 20-case, fold0, or fulltrain.
    """

    def __init__(self):
        super().__init__(
            support_weight=1.25,
            contact_weight=0.25,
            core_weight=1.50,
            exterior_weight=0.45,
            roi_weight=0.0,
            edge_weight=5.0,
            edge_pos_weight=24.0,
            edge_same_fragment_neg_weight=6.0,
            edge_support_neg_weight=2.5,
            edge_background_neg_weight=0.5,
            topk_fraction=0.01,
            gamma=2.0,
            eps=1e-6,
        )


class BICMV43EdgeContactViabilityLoss(BICMV39EdgePrimaryLoss):
    """V43 contact viability objective on top of V39 edge-primary supervision.

    [AUDIT][Risk:High][Scope:single_variable_after_v42]
    V40 final is the only recent checkpoint with nonzero useful contact
    precision, while V42 restored core coverage but predicted zero contact.
    This loss intentionally does not change architecture, input channels,
    sidecars, decoder, threshold, or core target geometry. It changes only the
    contact/edge supervision contract so the next 003 diagnostic can answer a
    single question: can edge-primary contact stay alive without broad
    no-contact ROI overpaint?

    [QA][Gate:case003_before_159][Status:Required]
    Passing patch metrics is not acceptance evidence. Full-volume `003`
    `bicm-v6-eval` must pass before any 159/20-case/fold0/fulltrain run.
    """

    def __init__(
        self,
        *,
        contact_positive_floor_lambda: float = 0.70,
        edge_positive_floor_lambda: float = 1.20,
        contact_support_cap_lambda: float = 0.40,
        edge_absent_cap_lambda: float = 0.80,
        viability_floor: float = 0.58,
        negative_cap: float = 0.35,
        topk_viability_fraction: float = 0.02,
    ):
        super().__init__()
        self.contact_positive_floor_lambda = float(contact_positive_floor_lambda)
        self.edge_positive_floor_lambda = float(edge_positive_floor_lambda)
        self.contact_support_cap_lambda = float(contact_support_cap_lambda)
        self.edge_absent_cap_lambda = float(edge_absent_cap_lambda)
        self.viability_floor = float(viability_floor)
        self.negative_cap = float(negative_cap)
        self.topk_viability_fraction = float(topk_viability_fraction)

    def _positive_floor(self, prob: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        """Keep sparse true contact/edge positives above the fixed 0.5 gate.

        [METRIC][Risk:High][Scope:fixed_threshold]
        The evaluator does not tune thresholds. A target that is learned as
        probability 0.3 is equivalent to no contact at inference, even if its
        ranking is locally correct. This term is deliberately applied only on
        GT positives to avoid creating another broad-contact pressure.
        """
        if not mask.any():
            return prob.new_zeros(())
        return F.relu(float(self.viability_floor) - prob[mask]).pow(2).mean()

    def _topk_cap(self, prob: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        """Cap the highest false-contact probabilities without threshold search."""
        if not mask.any():
            return prob.new_zeros(())
        vals = prob[mask]
        if vals.numel() == 0:
            return prob.new_zeros(())
        k = max(1, int(round(float(vals.numel()) * self.topk_viability_fraction)))
        hard = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return F.relu(hard - float(self.negative_cap)).pow(2).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        logits = pred_logits.float()
        prob = torch.sigmoid(logits)
        support = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1)
        contact = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1)
        edge_break = target["edge_break"].to(logits.device).float() > 0.5
        edge_valid = target["edge_valid"].to(logits.device).float() > 0.5

        contact_prob = prob[:, 1:2]
        edge_prob = prob[:, 5:8]

        # [QC][Invariant:shape_alignment]
        # `contact_prob` is [B,1,D,H,W] and `edge_prob` is [B,3,D,H,W].
        # These guards catch sidecar/channel mismatches before silent boolean
        # indexing can flatten the wrong axes.
        if contact_prob.shape != contact.shape:
            raise ValueError(f"V43 contact shape mismatch: prob={tuple(contact_prob.shape)} target={tuple(contact.shape)}")
        if edge_prob.shape != edge_break.shape:
            raise ValueError(f"V43 edge shape mismatch: prob={tuple(edge_prob.shape)} target={tuple(edge_break.shape)}")

        total = total + self.contact_positive_floor_lambda * self._positive_floor(
            contact_prob, contact > 0.5
        )
        total = total + self.edge_positive_floor_lambda * self._positive_floor(
            edge_prob, edge_valid & edge_break
        )

        support_noncontact = (support > 0.5) & (contact <= 0.5)
        total = total + self.contact_support_cap_lambda * self._topk_cap(
            contact_prob, support_noncontact
        )

        no_edge_sample = (edge_break.flatten(1).sum(dim=1) <= 0)
        if bool(no_edge_sample.any().item()):
            no_edge_mask = no_edge_sample[:, None, None, None, None] & edge_valid
            total = total + self.edge_absent_cap_lambda * self._topk_cap(edge_prob, no_edge_mask)

        if not torch.isfinite(total):
            raise ValueError(f"BICMV43EdgeContactViabilityLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV44EdgeLocalRankLoss(BICMV43EdgeContactViabilityLoss):
    """V44 local edge ranking objective.

    [AUDIT][Risk:High][Scope:single_variable_after_v43]
    V43 kept contact alive only by broad activation in no-contact ROIs and
    support-internal regions. V44 adds one local topology constraint: true
    same-anatomy cross-fragment edge breaks must outrank high-probability local
    non-break edges. Architecture, decoder, threshold, sidecars, and the V43
    viability terms remain fixed.
    """

    def __init__(
        self,
        *,
        edge_local_rank_lambda: float = 1.25,
        rank_margin: float = 0.25,
        rank_topk_fraction: float = 0.03,
    ):
        super().__init__()
        self.edge_local_rank_lambda = float(edge_local_rank_lambda)
        self.rank_margin = float(rank_margin)
        self.rank_topk_fraction = float(rank_topk_fraction)

    def _edge_local_rank(
        self,
        edge_prob: torch.Tensor,
        edge_break: torch.Tensor,
        edge_valid: torch.Tensor,
        instance: torch.Tensor,
    ) -> torch.Tensor:
        """Rank true fragment-break edges above local non-break support edges."""
        same_fragment, support_touch = self._edge_context_masks(instance)
        pos = edge_valid & edge_break
        # [METRIC][Risk:High][Scope:contact_location]
        # V43 false positives were not mainly far background; they were support
        # and no-contact ROI edges. Ranking against support-touch negatives
        # makes the signal local without adding a post-hoc gate.
        neg = edge_valid & (~edge_break) & support_touch
        if not pos.any() or not neg.any():
            return edge_prob.new_zeros(())
        pos_vals = edge_prob[pos]
        neg_vals = edge_prob[neg]
        if pos_vals.numel() == 0 or neg_vals.numel() == 0:
            return edge_prob.new_zeros(())
        k_neg = max(1, int(round(float(neg_vals.numel()) * self.rank_topk_fraction)))
        hard_neg = torch.topk(neg_vals, k=min(k_neg, neg_vals.numel()), largest=True).values
        # Use the lower half of positives so a few easy fracture voxels cannot
        # hide that most of the ridge is still below the fixed threshold.
        k_pos = max(1, int(round(float(pos_vals.numel()) * 0.50)))
        hard_pos = torch.topk(pos_vals, k=min(k_pos, pos_vals.numel()), largest=False).values
        return F.relu(float(self.rank_margin) + hard_neg.mean() - hard_pos.mean()).pow(2)

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        logits = pred_logits.float()
        edge_prob = torch.sigmoid(logits[:, 5:8])
        edge_break = target["edge_break"].to(logits.device).float() > 0.5
        edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
        instance = target["instance"].to(logits.device).long()
        total = total + self.edge_local_rank_lambda * self._edge_local_rank(
            edge_prob, edge_break, edge_valid, instance
        )
        if not torch.isfinite(total):
            raise ValueError(f"BICMV44EdgeLocalRankLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV46StagedEdgeContactLoss(BICMV44EdgeLocalRankLoss):
    """V46 staged edge/contact curriculum for the V44 objective.

    [AUDIT][Risk:High][Scope:single_variable_after_v45]
    V45 saved every short-run epoch candidate and still found no checkpoint
    where support geometry, contact precision, contact recall, and IoU-F pass
    together. This loss keeps the V44 representation, sidecars, decoder, fixed
    threshold, and local ranking term. The only training variable is the timing
    of positive-contact preservation versus support-local false-contact
    pressure.

    [QA][Gate:case003_before_159][Status:Required]
    Patch validation is a health signal only. A V46 checkpoint cannot progress
    to 159, 20-case, fold0, or fulltrain unless the full-volume case003 JSON
    passes the fixed gate.
    """

    def __init__(
        self,
        *,
        warmup_epochs: int = 2,
        ramp_epochs: int = 5,
        contact_floor_start: float = 1.20,
        contact_floor_end: float = 1.05,
        edge_floor_start: float = 1.70,
        edge_floor_end: float = 1.35,
        support_cap_start: float = 0.10,
        support_cap_end: float = 0.55,
        absent_edge_cap_start: float = 0.20,
        absent_edge_cap_end: float = 0.95,
        rank_lambda_start: float = 0.35,
        rank_lambda_end: float = 2.00,
        negative_cap_start: float = 0.46,
        negative_cap_end: float = 0.32,
        viability_floor_start: float = 0.62,
        viability_floor_end: float = 0.58,
    ):
        super().__init__(edge_local_rank_lambda=rank_lambda_start)
        self.warmup_epochs = int(warmup_epochs)
        self.ramp_epochs = max(1, int(ramp_epochs))
        self._schedule_start_end = {
            "contact_positive_floor_lambda": (float(contact_floor_start), float(contact_floor_end)),
            "edge_positive_floor_lambda": (float(edge_floor_start), float(edge_floor_end)),
            "contact_support_cap_lambda": (float(support_cap_start), float(support_cap_end)),
            "edge_absent_cap_lambda": (float(absent_edge_cap_start), float(absent_edge_cap_end)),
            "edge_local_rank_lambda": (float(rank_lambda_start), float(rank_lambda_end)),
            "negative_cap": (float(negative_cap_start), float(negative_cap_end)),
            "viability_floor": (float(viability_floor_start), float(viability_floor_end)),
        }
        self.current_epoch = 0
        self._apply_schedule()

    def set_current_epoch(self, epoch: int) -> None:
        self.current_epoch = int(epoch)
        self._apply_schedule()

    def _stage_fraction(self) -> float:
        if self.current_epoch < self.warmup_epochs:
            return 0.0
        return min(1.0, float(self.current_epoch - self.warmup_epochs + 1) / float(self.ramp_epochs))

    def _apply_schedule(self) -> None:
        frac = self._stage_fraction()
        for attr, (start, end) in self._schedule_start_end.items():
            setattr(self, attr, start + frac * (end - start))

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        # [QC][Invariant:loss_schedule]
        # The trainer calls set_current_epoch before train/val steps. Applying
        # the schedule again here makes direct unit/smoke calls deterministic
        # instead of silently using stale coefficients.
        self._apply_schedule()
        total = super().forward(pred_logits, target)
        if not torch.isfinite(total):
            raise ValueError(f"BICMV46StagedEdgeContactLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV47SeparatedContactHeadLoss(BICMV46StagedEdgeContactLoss):
    """V47 two-phase loss for separated contact-head fine-tuning.

    [AUDIT][Risk:High][Scope:optimization_decoupling]
    V46 showed the same model can individually reach support geometry,
    contact precision, and contact recall gates, but not at the same epoch.
    This loss is paired with `PengwinTrainerBICMSeparatedContactV47`, which
    freezes support/core/exterior formation after phase 1 and trains only the
    contact/edge output rows in phase 2. The loss mirrors that contract:
    phase 1 uses the V46 full topology objective; phase 2 removes support/core
    terms and optimizes only contact and edge-break placement.

    [QA][Gate:case003_before_159][Status:Required]
    This is still a case003-only root-cause experiment. If full-volume JSON
    does not pass, the result is diagnostic only and must not be expanded.
    """

    def __init__(
        self,
        *,
        contact_phase_epoch: int = 5,
        phase2_contact_lambda: float = 2.0,
        phase2_edge_lambda: float = 4.0,
        phase2_rank_lambda: float = 2.5,
        phase2_contact_floor_lambda: float = 1.20,
        phase2_edge_floor_lambda: float = 1.50,
        phase2_false_contact_lambda: float = 0.75,
        phase2_absent_edge_lambda: float = 1.00,
        phase2_contact_pos_weight: float = 18.0,
        phase2_contact_neg_weight: float = 1.50,
    ):
        super().__init__()
        self.contact_phase_epoch = int(contact_phase_epoch)
        self.phase2_contact_lambda = float(phase2_contact_lambda)
        self.phase2_edge_lambda = float(phase2_edge_lambda)
        self.phase2_rank_lambda = float(phase2_rank_lambda)
        self.phase2_contact_floor_lambda = float(phase2_contact_floor_lambda)
        self.phase2_edge_floor_lambda = float(phase2_edge_floor_lambda)
        self.phase2_false_contact_lambda = float(phase2_false_contact_lambda)
        self.phase2_absent_edge_lambda = float(phase2_absent_edge_lambda)
        self.phase2_contact_pos_weight = float(phase2_contact_pos_weight)
        self.phase2_contact_neg_weight = float(phase2_contact_neg_weight)

    def _is_contact_phase(self) -> bool:
        return int(self.current_epoch) >= int(self.contact_phase_epoch)

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if not self._is_contact_phase():
            return super().forward(pred_logits, target)

        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV47SeparatedContactHeadLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")
            support = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1)
            contact = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1)
            edge_break = target["edge_break"].to(logits.device).float() > 0.5
            edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
            instance = target["instance"].to(logits.device).long()

            contact_prob = torch.sigmoid(logits[:, 1:2])
            edge_prob = torch.sigmoid(logits[:, 5:8])
            support_noncontact = (support > 0.5) & (contact <= 0.5)

            # [METRIC][Risk:High][Scope:phase2_contact_only]
            # Phase 2 intentionally has no support/core loss. The paired
            # trainer freezes those rows and the shared feature extractor, so
            # contact can move without destroying the support geometry that
            # V46 proved is learnable.
            contact_loss = self._binary_focal(
                logits[:, 1],
                contact[:, 0],
                pos_weight=self.phase2_contact_pos_weight,
                neg_weight=self.phase2_contact_neg_weight,
            )
            contact_loss = contact_loss + self.phase2_contact_floor_lambda * self._positive_floor(
                contact_prob, contact > 0.5
            )
            contact_loss = contact_loss + self.phase2_false_contact_lambda * self._topk_cap(
                contact_prob, support_noncontact
            )

            edge_loss = self._edge_loss(
                logits[:, 5:8],
                edge_break.float(),
                edge_valid.float(),
                instance,
            )
            edge_loss = edge_loss + self.phase2_edge_floor_lambda * self._positive_floor(
                edge_prob, edge_valid & edge_break
            )
            no_edge_sample = (edge_break.flatten(1).sum(dim=1) <= 0)
            if bool(no_edge_sample.any().item()):
                no_edge_mask = no_edge_sample[:, None, None, None, None] & edge_valid
                edge_loss = edge_loss + self.phase2_absent_edge_lambda * self._topk_cap(edge_prob, no_edge_mask)
            rank_loss = self._edge_local_rank(edge_prob, edge_break, edge_valid, instance)

            total = (
                self.phase2_contact_lambda * contact_loss
                + self.phase2_edge_lambda * edge_loss
                + self.phase2_rank_lambda * rank_loss
            )
            if not torch.isfinite(total):
                raise ValueError(f"BICMV47SeparatedContactHeadLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV51DenseEdgeCostLoss(BICMV46StagedEdgeContactLoss):
    """V51 dense edge-distance/crossing-cost supervision.

    [AUDIT][Risk:High][Scope:contact_representation]
    V49 and V50 excluded branch depth and branch-only phase separation as the
    primary blocker. V51 keeps the V49 architecture, V46 base objective,
    sidecars, sampler, threshold, and decoder. The single changed variable is
    the edge/contact target representation: sparse cross-fragment edge labels
    are expanded into a support-local dense crossing-cost ridge. This tests
    whether the fixed watershed can learn a continuous ridge instead of a
    one-voxel sparse edge event.

    [METRIC][Invariant:promotion_gate]
    The evaluator still uses the fixed 0.5 threshold and raw-logit
    `edge_primary_v39` contract. This loss may improve gradients, but it does
    not introduce threshold search or post-hoc gating.
    """

    def __init__(
        self,
        *,
        dense_edge_lambda: float = 2.50,
        dense_contact_lambda: float = 0.65,
        dense_rank_lambda: float = 1.25,
        dense_pos_weight: float = 8.0,
        dense_soft_weight: float = 3.0,
        dense_neg_weight: float = 1.0,
        dense_false_cap_lambda: float = 0.75,
        dense_floor: float = 0.58,
        dense_negative_cap: float = 0.32,
    ):
        super().__init__()
        self.dense_edge_lambda = float(dense_edge_lambda)
        self.dense_contact_lambda = float(dense_contact_lambda)
        self.dense_rank_lambda = float(dense_rank_lambda)
        self.dense_pos_weight = float(dense_pos_weight)
        self.dense_soft_weight = float(dense_soft_weight)
        self.dense_neg_weight = float(dense_neg_weight)
        self.dense_false_cap_lambda = float(dense_false_cap_lambda)
        self.dense_floor = float(dense_floor)
        self.dense_negative_cap = float(dense_negative_cap)

    @staticmethod
    def _dense_edge_target(edge_break: torch.Tensor) -> torch.Tensor:
        """Return a small fixed-radius soft ridge around true edge breaks.

        [QC][Invariant:shape_dtype_device]
        The input and output stay `[B,3,D,H,W]` and on the same device. We use
        repeated 3x3x3 max-pooling instead of CPU distance transforms so the
        target is deterministic, GPU-local, and compatible with nnU-Net patch
        training. This is a train-time target expansion, not a decoder change.
        """
        edge = edge_break.float().clamp(0.0, 1.0)
        d1 = F.max_pool3d(edge, kernel_size=3, stride=1, padding=1)
        d2 = F.max_pool3d(d1, kernel_size=3, stride=1, padding=1)
        dense = torch.maximum(edge, torch.maximum(0.65 * d1, 0.35 * d2))
        return dense.clamp(0.0, 1.0)

    def _soft_bce(self,
                  logits: torch.Tensor,
                  target: torch.Tensor,
                  valid: torch.Tensor) -> torch.Tensor:
        if logits.shape != target.shape or logits.shape != valid.shape:
            raise ValueError(
                "V51 dense edge shape mismatch: "
                f"logits={tuple(logits.shape)} target={tuple(target.shape)} valid={tuple(valid.shape)}"
            )
        if not valid.any():
            return logits.new_zeros(())
        loss = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        weight = torch.full_like(target, self.dense_neg_weight)
        weight = torch.where(target >= 0.99, torch.full_like(weight, self.dense_pos_weight), weight)
        soft = (target > 0.0) & (target < 0.99)
        weight = torch.where(soft, torch.full_like(weight, self.dense_soft_weight), weight)
        return (loss[valid] * weight[valid]).mean()

    def _dense_rank(self,
                    edge_prob: torch.Tensor,
                    dense_target: torch.Tensor,
                    valid: torch.Tensor,
                    instance: torch.Tensor) -> torch.Tensor:
        same_fragment, support_touch = self._edge_context_masks(instance)
        pos = valid & (dense_target >= 0.65)
        neg = valid & (dense_target <= 0.01) & support_touch & same_fragment
        if not pos.any() or not neg.any():
            return edge_prob.new_zeros(())
        pos_vals = edge_prob[pos]
        neg_vals = edge_prob[neg]
        if pos_vals.numel() == 0 or neg_vals.numel() == 0:
            return edge_prob.new_zeros(())
        k_pos = max(1, int(round(float(pos_vals.numel()) * 0.50)))
        k_neg = max(1, int(round(float(neg_vals.numel()) * 0.03)))
        hard_pos = torch.topk(pos_vals, k=min(k_pos, pos_vals.numel()), largest=False).values
        hard_neg = torch.topk(neg_vals, k=min(k_neg, neg_vals.numel()), largest=True).values
        return F.relu(0.20 + hard_neg.mean() - hard_pos.mean()).pow(2)

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        logits = pred_logits.float()
        if logits.ndim != 5 or int(logits.shape[1]) != 8:
            raise ValueError(f"BICMV51DenseEdgeCostLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")
        edge_break = target["edge_break"].to(logits.device).float()
        edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
        instance = target["instance"].to(logits.device).long()
        support = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
        contact = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5

        edge_logits = logits[:, 5:8]
        edge_prob = torch.sigmoid(edge_logits)
        dense_edge = self._dense_edge_target(edge_break)
        dense_edge = torch.where(edge_valid, dense_edge, torch.zeros_like(dense_edge))

        total = total + self.dense_edge_lambda * self._soft_bce(edge_logits, dense_edge, edge_valid)

        dense_contact = torch.max(dense_edge, dim=1, keepdim=True).values
        contact_valid = support | contact
        total = total + self.dense_contact_lambda * self._soft_bce(
            logits[:, 1:2],
            dense_contact,
            contact_valid.expand_as(dense_contact),
        )

        total = total + self.dense_rank_lambda * self._dense_rank(edge_prob, dense_edge, edge_valid, instance)

        same_fragment, support_touch = self._edge_context_masks(instance)
        dense_false = edge_valid & support_touch & same_fragment & (dense_edge <= 0.01)
        if dense_false.any():
            hard = torch.topk(
                edge_prob[dense_false],
                k=min(max(1, int(round(float(edge_prob[dense_false].numel()) * 0.02))), edge_prob[dense_false].numel()),
                largest=True,
            ).values
            total = total + self.dense_false_cap_lambda * F.relu(hard - self.dense_negative_cap).pow(2).mean()

        dense_pos = edge_valid & (dense_edge >= 0.99)
        if dense_pos.any():
            total = total + 0.65 * F.relu(self.dense_floor - edge_prob[dense_pos]).pow(2).mean()

        if not torch.isfinite(total):
            raise ValueError(f"BICMV51DenseEdgeCostLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV52DenseEdgeCoreTopologyLoss(BICMV51DenseEdgeCostLoss):
    """V52 dense edge-cost plus explicit core-marker topology pressure.

    [AUDIT][Risk:High][Scope:single_variable_after_v51]
    V51 failed with support/core gates apparently passing, but retained JSON
    traces showed the real marker failure: `raw_core_voxels == support_voxels`
    and LeftHip had one seed component for eight GT fragments. V52 keeps the V51
    architecture, dense edge target, sampler, threshold, and decoder. The only
    changed variable is train-time pressure that prevents the core head from
    becoming anatomy-wide support.

    [METRIC][Gate:case003_only]
    Full-volume acceptance now includes seed topology, not just coverage. A V52
    checkpoint cannot proceed to 159/20-case/fold0/fulltrain unless case003 has
    fragment-scale core markers, contact precision/recall, support HD95, and
    IoU-F all passing together.
    """

    def __init__(
        self,
        *,
        core_noncore_cap_lambda: float = 1.35,
        core_contact_cap_lambda: float = 0.75,
        core_mass_ratio_lambda: float = 0.75,
        core_margin_lambda: float = 0.40,
        core_positive_floor_lambda: float = 0.55,
        core_noncore_cap: float = 0.30,
        core_contact_cap: float = 0.22,
        core_margin: float = 0.35,
        core_positive_floor: float = 0.58,
        topk_core_fraction: float = 0.03,
        warmup_epochs: int = 1,
        ramp_epochs: int = 2,
    ):
        super().__init__()
        self.core_noncore_cap_lambda = float(core_noncore_cap_lambda)
        self.core_contact_cap_lambda = float(core_contact_cap_lambda)
        self.core_mass_ratio_lambda = float(core_mass_ratio_lambda)
        self.core_margin_lambda = float(core_margin_lambda)
        self.core_positive_floor_lambda = float(core_positive_floor_lambda)
        self.core_noncore_cap = float(core_noncore_cap)
        self.core_contact_cap = float(core_contact_cap)
        self.core_margin = float(core_margin)
        self.core_positive_floor = float(core_positive_floor)
        self.topk_core_fraction = float(topk_core_fraction)
        self.warmup_epochs = int(warmup_epochs)
        self.ramp_epochs = max(1, int(ramp_epochs))
        self.current_epoch = 0

    def set_current_epoch(self, epoch: int) -> None:
        # [REPRO][Scope:loss_schedule]
        # The core-topology ramp is deterministic from the saved trainer epoch.
        # It never reads validation/full-volume metrics, so it cannot become a
        # hidden threshold-tuning loop over case003.
        self.current_epoch = int(epoch)
        parent = getattr(super(), "set_current_epoch", None)
        if callable(parent):
            parent(epoch)

    def _core_phase_weight(self) -> float:
        progress = (int(self.current_epoch) + 1 - self.warmup_epochs) / float(self.ramp_epochs)
        return float(np.clip(progress, 0.0, 1.0))

    def _topk_hinge_on_mask(self, prob: torch.Tensor, mask: torch.Tensor, cap: float) -> torch.Tensor:
        if not mask.any():
            return prob.new_zeros(())
        vals = prob[:, 0][mask[:, 0]]
        if vals.numel() == 0:
            return prob.new_zeros(())
        k = max(1, int(round(float(vals.numel()) * self.topk_core_fraction)))
        hard = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return F.relu(hard - float(cap)).pow(2).mean()

    def _core_mass_ratio_loss(
        self,
        core_prob: torch.Tensor,
        core_target: torch.Tensor,
        support_target: torch.Tensor,
    ) -> torch.Tensor:
        total = core_prob.new_zeros(())
        count = 0
        for idx in range(int(core_prob.shape[0])):
            ct = core_target[idx, 0] > 0.5
            if not ct.any():
                continue
            st = support_target[idx, 0] > 0.5
            pred_mass = (core_prob[idx, 0][st] if st.any() else core_prob[idx, 0].reshape(-1)).sum()
            target_mass = ct.float().sum()
            # [METRIC][Risk:High][Scope:marker_size]
            # This directly targets the V51 failure where core mass expands to
            # the whole support mask. The ratio is train-target based and fixed;
            # no validation threshold or component-size postprocess is introduced.
            total = total + torch.log((pred_mass + 1.0) / (target_mass + 1.0)).pow(2)
            count += 1
        return total / max(count, 1)

    def _core_vs_support_margin(
        self,
        core_logit: torch.Tensor,
        support_logit: torch.Tensor,
        core_target: torch.Tensor,
        support_noncore: torch.Tensor,
    ) -> torch.Tensor:
        if not support_noncore.any():
            return core_logit.new_zeros(())
        neg = core_logit[support_noncore] - support_logit[support_noncore] + self.core_margin
        loss = F.relu(neg).mean()
        if core_target.any():
            pos = support_logit[core_target] - core_logit[core_target] + self.core_margin
            loss = loss + 0.25 * F.relu(pos).mean()
        return loss

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        phase = self._core_phase_weight()
        if phase <= 0.0:
            return total

        logits = pred_logits.float()
        if logits.ndim != 5 or int(logits.shape[1]) != 8:
            raise ValueError(f"BICMV52DenseEdgeCoreTopologyLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")
        prob = torch.sigmoid(logits)
        support_prob = prob[:, 0:1]
        core_prob = prob[:, 2:3]
        support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
        contact_target = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5
        core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
        support_noncore = support_target & ~core_target

        total = total + phase * self.core_noncore_cap_lambda * self._topk_hinge_on_mask(
            core_prob,
            support_noncore,
            cap=self.core_noncore_cap,
        )
        total = total + phase * self.core_contact_cap_lambda * self._topk_hinge_on_mask(
            core_prob,
            contact_target,
            cap=self.core_contact_cap,
        )
        total = total + phase * self.core_mass_ratio_lambda * self._core_mass_ratio_loss(
            core_prob,
            core_target.float(),
            support_target.float(),
        )
        total = total + phase * self.core_margin_lambda * self._core_vs_support_margin(
            logits[:, 2],
            logits[:, 0],
            core_target[:, 0],
            support_noncore[:, 0],
        )
        if core_target.any():
            # [QC][Invariant:do_not_delete_markers]
            # Anti-bridge pressure can solve a giant-core failure by deleting core
            # everywhere. This floor keeps true marker voxels near the fixed 0.5
            # decoder threshold without changing the decoder itself.
            total = total + phase * self.core_positive_floor_lambda * F.relu(
                self.core_positive_floor - core_prob[core_target]
            ).pow(2).mean()

        if not torch.isfinite(total):
            raise ValueError(f"BICMV52DenseEdgeCoreTopologyLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV54SparseHeadBalancedLoss(BICMV52DenseEdgeCoreTopologyLoss):
    """V54 sparse positive normalization for fragment-marker/contact heads.

    [AUDIT][Risk:High][Scope:single_variable_after_v53]
    V53 changed the core target to fragment-center markers but measured collapse
    at the fixed 0.5 decoder threshold. The retained gradient audit shows why:
    on a case003 LeftHip contact crop, support-noncore gradients pushing the core
    logit down are roughly 10x larger in aggregate than marker-positive gradients
    pushing it up. V54 keeps the V53 target geometry, V52 dense edge/contact
    objective, sampler, model, threshold, and decoder. It changes only sparse
    positive normalization for core/contact/edge heads.

    [METRIC][Invariant:no_threshold_tuning]
    These terms alter train-time gradients only. Evaluation remains raw-logit
    export plus fixed `bicm_v6_factorized_watershed` at threshold 0.5.
    """

    def __init__(
        self,
        *,
        core_marker_positive_lambda: float = 8.0,
        contact_positive_lambda: float = 4.0,
        edge_positive_lambda: float = 1.5,
        dense_positive_threshold: float = 0.65,
    ):
        super().__init__(
            core_noncore_cap_lambda=0.75,
            core_contact_cap_lambda=0.45,
            core_mass_ratio_lambda=0.35,
            core_margin_lambda=0.35,
            core_positive_floor_lambda=0.75,
        )
        self.core_marker_positive_lambda = float(core_marker_positive_lambda)
        self.contact_positive_lambda = float(contact_positive_lambda)
        self.edge_positive_lambda = float(edge_positive_lambda)
        self.dense_positive_threshold = float(dense_positive_threshold)

    @staticmethod
    def _positive_bce(logits: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        # [QC][Invariant:sparse_positive_normalization]
        # Sparse heads must be averaged over positive voxels/edges only here.
        # Averaging over the full patch recreates the V53 failure where support
        # negatives dominate marker/contact positives by several orders of
        # magnitude. Empty masks return zero so no-contact ROIs remain valid.
        if not mask.any():
            return logits.new_zeros(())
        selected = logits[mask]
        return F.binary_cross_entropy_with_logits(selected, torch.ones_like(selected), reduction="mean")

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        logits = pred_logits.float()
        if logits.ndim != 5 or int(logits.shape[1]) != 8:
            raise ValueError(f"BICMV54SparseHeadBalancedLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

        core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
        edge_break = target["edge_break"].to(logits.device).float()
        edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
        dense_edge = torch.where(
            edge_valid,
            self._dense_edge_target(edge_break),
            torch.zeros_like(edge_break),
        )
        dense_contact = torch.max(dense_edge, dim=1, keepdim=True).values
        contact_pos = dense_contact >= self.dense_positive_threshold
        edge_pos = edge_valid & (dense_edge >= self.dense_positive_threshold)

        total = total + self.core_marker_positive_lambda * self._positive_bce(
            logits[:, 2:3],
            core_target,
        )
        total = total + self.contact_positive_lambda * self._positive_bce(
            logits[:, 1:2],
            contact_pos,
        )
        total = total + self.edge_positive_lambda * self._positive_bce(
            logits[:, 5:8],
            edge_pos,
        )

        if not torch.isfinite(total):
            raise ValueError(f"BICMV54SparseHeadBalancedLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV55CalibratedSparseHeadLoss(BICMV54SparseHeadBalancedLoss):
    """V55 calibrated sparse-head balance after the V54 overgrowth failure.

    [AUDIT][Risk:High][Scope:single_variable_after_v54]
    V54 showed the sparse-positive terms are necessary: they revived core
    coverage and made contact nonzero in some checkpoints. The same run also
    showed the positive pressure is too strong or too weak depending on epoch:
    support-stable checkpoints have zero contact and merged core markers, while
    contact-positive checkpoints overpaint contact/core and fail topology. V55
    keeps V54 target geometry, model, sampler, fixed threshold, raw-logit eval,
    and decoder. It changes only the sparse-positive vs noncore/contact
    suppression balance.

    [QA][Gate:case003_before_expansion][Status:Required]
    This is still a case003-only diagnostic. Passing patch validation or
    improving one metric is not enough; full-volume support/contact/core
    topology and IoU-F gates must pass before 159, 20-case, fold0, or fulltrain.
    """

    def __init__(
        self,
        *,
        core_marker_positive_lambda: float = 4.25,
        contact_positive_lambda: float = 2.75,
        edge_positive_lambda: float = 1.10,
        dense_positive_threshold: float = 0.65,
    ):
        # [QC][Invariant:balanced_sparse_pressure]
        # V53 negative pressure dominated marker positives; V54 reversed that
        # too aggressively. These constants intentionally sit between V52/V53
        # suppression and V54 positive normalization so the next run tests one
        # narrow question: can calibrated sparse pressure avoid both collapse
        # and overgrowth without changing the decoder or threshold?
        BICMV52DenseEdgeCoreTopologyLoss.__init__(
            self,
            core_noncore_cap_lambda=1.05,
            core_contact_cap_lambda=0.62,
            core_mass_ratio_lambda=0.55,
            core_margin_lambda=0.40,
            core_positive_floor_lambda=0.62,
            core_noncore_cap=0.30,
            core_contact_cap=0.22,
            core_margin=0.35,
            core_positive_floor=0.58,
        )
        self.core_marker_positive_lambda = float(core_marker_positive_lambda)
        self.contact_positive_lambda = float(contact_positive_lambda)
        self.edge_positive_lambda = float(edge_positive_lambda)
        self.dense_positive_threshold = float(dense_positive_threshold)


class BICMV56PhasedMarkerContactLoss(BICMV54SparseHeadBalancedLoss):
    """V56 two-phase support prefit then marker/contact refinement.

    [AUDIT][Risk:High][Scope:single_variable_after_v55]
    V55 excluded coefficient-only sparse-head calibration: reducing V54
    positive pressure prevents overgrowth, but full-volume contact collapses to
    zero and core topology remains incomplete. V56 therefore changes the
    optimization contract rather than another scalar. Phase 1 reuses V54 to
    form support/context. Phase 2 removes support/exterior loss and optimizes
    only core-marker, contact, and edge-break heads while the paired trainer
    freezes shared features and non-marker output rows.

    [QA][Gate:case003_before_expansion][Status:Required]
    Phase separation is not promotion evidence by itself. Only fixed-threshold
    full-volume case003 `bicm-v6-eval` can unlock 159/20-case/fold0/fulltrain.
    """

    def __init__(
        self,
        *,
        marker_phase_epoch: int = 5,
        phase2_core_lambda: float = 2.25,
        phase2_contact_lambda: float = 2.00,
        phase2_edge_lambda: float = 1.50,
        phase2_rank_lambda: float = 1.25,
        phase2_core_positive_lambda: float = 4.00,
        phase2_contact_positive_lambda: float = 2.75,
        phase2_edge_positive_lambda: float = 1.10,
        phase2_core_noncore_lambda: float = 1.35,
        phase2_core_mass_lambda: float = 0.80,
        phase2_false_contact_lambda: float = 0.70,
        dense_positive_threshold: float = 0.65,
    ):
        super().__init__()
        self.marker_phase_epoch = int(marker_phase_epoch)
        self.phase2_core_lambda = float(phase2_core_lambda)
        self.phase2_contact_lambda = float(phase2_contact_lambda)
        self.phase2_edge_lambda = float(phase2_edge_lambda)
        self.phase2_rank_lambda = float(phase2_rank_lambda)
        self.phase2_core_positive_lambda = float(phase2_core_positive_lambda)
        self.phase2_contact_positive_lambda = float(phase2_contact_positive_lambda)
        self.phase2_edge_positive_lambda = float(phase2_edge_positive_lambda)
        self.phase2_core_noncore_lambda = float(phase2_core_noncore_lambda)
        self.phase2_core_mass_lambda = float(phase2_core_mass_lambda)
        self.phase2_false_contact_lambda = float(phase2_false_contact_lambda)
        self.dense_positive_threshold = float(dense_positive_threshold)

    def _is_marker_phase(self) -> bool:
        return int(getattr(self, "current_epoch", 0)) >= int(self.marker_phase_epoch)

    def _phase2_core_loss(
        self,
        logits: torch.Tensor,
        core_target: torch.Tensor,
        support_target: torch.Tensor,
        contact_target: torch.Tensor,
    ) -> torch.Tensor:
        core_prob = torch.sigmoid(logits[:, 2:3])
        support_prob = torch.sigmoid(logits[:, 0:1])
        support_noncore = support_target & ~core_target
        loss = self._binary_focal(
            logits[:, 2],
            core_target[:, 0].float(),
            pos_weight=18.0,
            neg_weight=1.25,
        )
        loss = loss + self.phase2_core_positive_lambda * self._positive_bce(
            logits[:, 2:3],
            core_target,
        )
        loss = loss + self.phase2_core_noncore_lambda * self._topk_hinge_on_mask(
            core_prob,
            support_noncore,
            cap=0.28,
        )
        loss = loss + 0.60 * self.phase2_core_noncore_lambda * self._topk_hinge_on_mask(
            core_prob,
            contact_target,
            cap=0.20,
        )
        loss = loss + self.phase2_core_mass_lambda * self._core_mass_ratio_loss(
            core_prob,
            core_target.float(),
            support_target.float(),
        )
        loss = loss + 0.35 * self._core_vs_support_margin(
            logits[:, 2],
            logits[:, 0],
            core_target[:, 0],
            support_noncore[:, 0],
        )
        if core_target.any():
            loss = loss + 0.70 * F.relu(0.58 - core_prob[core_target]).pow(2).mean()
        return loss

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if not self._is_marker_phase():
            return super().forward(pred_logits, target)

        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV56PhasedMarkerContactLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

            support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
            core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
            contact_target = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5
            edge_break = target["edge_break"].to(logits.device).float()
            edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
            instance = target["instance"].to(logits.device).long()

            edge_logits = logits[:, 5:8]
            edge_prob = torch.sigmoid(edge_logits)
            dense_edge = torch.where(
                edge_valid,
                self._dense_edge_target(edge_break),
                torch.zeros_like(edge_break),
            )
            dense_contact = torch.max(dense_edge, dim=1, keepdim=True).values
            contact_valid = support_target | contact_target
            contact_pos = dense_contact >= self.dense_positive_threshold
            edge_pos = edge_valid & (dense_edge >= self.dense_positive_threshold)

            # [METRIC][Risk:High][Scope:phase2_fixed_support]
            # Phase 2 deliberately has no support/exterior objective. The
            # paired V56 trainer freezes the shared network and non-marker
            # output rows, so this loss tests whether marker/contact rows can be
            # aligned on a stable support representation without threshold
            # tuning or post-hoc support gates.
            core_loss = self._phase2_core_loss(logits, core_target, support_target, contact_target)
            contact_loss = self._soft_bce(
                logits[:, 1:2],
                dense_contact,
                contact_valid.expand_as(dense_contact),
            )
            contact_loss = contact_loss + self.phase2_contact_positive_lambda * self._positive_bce(
                logits[:, 1:2],
                contact_pos,
            )
            support_noncontact = support_target & (dense_contact < 0.01)
            contact_loss = contact_loss + self.phase2_false_contact_lambda * self._topk_cap(
                torch.sigmoid(logits[:, 1:2]),
                support_noncontact,
            )

            edge_loss = self._soft_bce(edge_logits, dense_edge, edge_valid)
            edge_loss = edge_loss + self.phase2_edge_positive_lambda * self._positive_bce(
                edge_logits,
                edge_pos,
            )
            rank_loss = self._dense_rank(edge_prob, dense_edge, edge_valid, instance)

            total = (
                self.phase2_core_lambda * core_loss
                + self.phase2_contact_lambda * contact_loss
                + self.phase2_edge_lambda * edge_loss
                + self.phase2_rank_lambda * rank_loss
            )
            if not torch.isfinite(total):
                raise ValueError(f"BICMV56PhasedMarkerContactLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV58HeatmapMarkerContactLoss(BICMV56PhasedMarkerContactLoss):
    """V58 calibrated heatmap/energy contract for sparse marker/contact heads.

    [AUDIT][Risk:High][Scope:single_variable_after_v57]
    V57 increased phase-2 marker/contact capacity with a decoder-feature branch
    but still produced zero full-volume contact and invalid fragment-scale core
    topology. V58 keeps the V57 architecture, sampler, fixed threshold, fixed
    decoder, raw-logit export, and case003-only gate. The single changed
    variable is how phase-2 marker/contact targets are interpreted: sparse
    hard positives become calibrated heatmaps/energy ridges with explicit
    fixed-threshold floor and support-local false-positive caps.

    [METRIC][Invariant:no_threshold_tuning]
    The evaluator still thresholds sigmoid outputs at 0.5. Heatmaps are
    train-time supervision only; they must not introduce validation-selected
    thresholds, probability sweeps, or post-hoc gates.
    """

    def __init__(
        self,
        *,
        marker_phase_epoch: int = 5,
        core_heatmap_lambda: float = 3.00,
        core_floor_lambda: float = 2.00,
        core_cap_lambda: float = 1.40,
        core_mass_lambda: float = 0.90,
        contact_heatmap_lambda: float = 2.80,
        contact_floor_lambda: float = 2.20,
        contact_cap_lambda: float = 1.15,
        edge_heatmap_lambda: float = 1.90,
        edge_floor_lambda: float = 1.20,
        rank_lambda: float = 1.60,
        positive_floor: float = 0.62,
        negative_cap: float = 0.22,
    ):
        super().__init__(marker_phase_epoch=marker_phase_epoch)
        self.core_heatmap_lambda = float(core_heatmap_lambda)
        self.core_floor_lambda = float(core_floor_lambda)
        self.core_cap_lambda = float(core_cap_lambda)
        self.core_mass_lambda = float(core_mass_lambda)
        self.contact_heatmap_lambda = float(contact_heatmap_lambda)
        self.contact_floor_lambda = float(contact_floor_lambda)
        self.contact_cap_lambda = float(contact_cap_lambda)
        self.edge_heatmap_lambda = float(edge_heatmap_lambda)
        self.edge_floor_lambda = float(edge_floor_lambda)
        self.rank_lambda = float(rank_lambda)
        self.positive_floor = float(positive_floor)
        self.negative_cap = float(negative_cap)

    @staticmethod
    def _dense_marker_heatmap(core_target: torch.Tensor, support_target: torch.Tensor) -> torch.Tensor:
        """Expand fragment-center markers into a compact connected heatmap.

        [QC][Invariant:marker_topology]
        The center voxel/ball remains the only target above the strongest
        supervision level, while the one-voxel halo provides gradients around
        sparse markers. This is intentionally GPU-local max-pooling, not a
        case-specific distance transform or decoder-side seed healing.
        """
        core = core_target.float().clamp(0.0, 1.0)
        d1 = F.max_pool3d(core, kernel_size=3, stride=1, padding=1)
        d2 = F.max_pool3d(d1, kernel_size=3, stride=1, padding=1)
        heatmap = torch.maximum(core, torch.maximum(0.72 * d1, 0.42 * d2))
        return torch.where(support_target, heatmap.clamp(0.0, 1.0), torch.zeros_like(heatmap))

    def _heatmap_bce(
        self,
        logits: torch.Tensor,
        target: torch.Tensor,
        valid: torch.Tensor,
        *,
        pos_weight: float,
        soft_weight: float,
        neg_weight: float,
    ) -> torch.Tensor:
        if logits.shape != target.shape or logits.shape != valid.shape:
            raise ValueError(
                "BICMV58 heatmap shape mismatch: "
                f"logits={tuple(logits.shape)} target={tuple(target.shape)} valid={tuple(valid.shape)}"
            )
        if not valid.any():
            return logits.new_zeros(())
        loss = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        weight = torch.full_like(target, float(neg_weight))
        strong = target >= 0.70
        soft = (target > 0.0) & (target < 0.70)
        weight = torch.where(strong, torch.full_like(weight, float(pos_weight)), weight)
        weight = torch.where(soft, torch.full_like(weight, float(soft_weight)), weight)
        return (loss[valid] * weight[valid]).mean()

    def _floor_on_target(self, prob: torch.Tensor, target: torch.Tensor, cutoff: float) -> torch.Tensor:
        mask = target >= float(cutoff)
        if not mask.any():
            return prob.new_zeros(())
        return F.relu(float(self.positive_floor) - prob[mask]).pow(2).mean()

    def _rank_head_against_support_negatives(
        self,
        prob: torch.Tensor,
        target: torch.Tensor,
        negative_mask: torch.Tensor,
        *,
        positive_cutoff: float = 0.70,
        negative_fraction: float = 0.02,
    ) -> torch.Tensor:
        pos = target >= float(positive_cutoff)
        neg = negative_mask & (target <= 0.01)
        if not pos.any() or not neg.any():
            return prob.new_zeros(())
        pos_vals = prob[pos]
        neg_vals = prob[neg]
        if pos_vals.numel() == 0 or neg_vals.numel() == 0:
            return prob.new_zeros(())
        k_pos = max(1, int(round(float(pos_vals.numel()) * 0.50)))
        k_neg = max(1, int(round(float(neg_vals.numel()) * float(negative_fraction))))
        hard_pos = torch.topk(pos_vals, k=min(k_pos, pos_vals.numel()), largest=False).values
        hard_neg = torch.topk(neg_vals, k=min(k_neg, neg_vals.numel()), largest=True).values
        return F.relu(0.18 + hard_neg.mean() - hard_pos.mean()).pow(2)

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if not self._is_marker_phase():
            return BICMV54SparseHeadBalancedLoss.forward(self, pred_logits, target)

        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV58HeatmapMarkerContactLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

            support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
            core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
            contact_binary = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5
            edge_break = target["edge_break"].to(logits.device).float()
            edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
            instance = target["instance"].to(logits.device).long()

            prob = torch.sigmoid(logits)
            core_heatmap = self._dense_marker_heatmap(core_target.float(), support_target)
            dense_edge = torch.where(
                edge_valid,
                self._dense_edge_target(edge_break),
                torch.zeros_like(edge_break),
            )
            contact_heatmap = torch.max(dense_edge, dim=1, keepdim=True).values
            contact_valid = support_target | contact_binary | (contact_heatmap > 0.0)

            # [AUDIT][Risk:High][Scope:phase2_support_freeze]
            # As in V57, support/exterior/ROI are not optimized in phase 2.
            # The branch learns marker/contact/edge energy on top of the frozen
            # support representation. If this fails, the remaining blocker is
            # the BICM marker/contact objective family, not broader training.
            core_loss = self._heatmap_bce(
                logits[:, 2:3],
                core_heatmap,
                support_target.expand_as(core_heatmap),
                pos_weight=18.0,
                soft_weight=5.0,
                neg_weight=1.0,
            )
            core_loss = core_loss + self.core_floor_lambda * self._floor_on_target(
                prob[:, 2:3],
                core_heatmap,
                cutoff=0.70,
            )
            support_noncore = support_target & (core_heatmap <= 0.01)
            core_loss = core_loss + self.core_cap_lambda * self._topk_hinge_on_mask(
                prob[:, 2:3],
                support_noncore,
                cap=self.negative_cap,
            )
            core_loss = core_loss + self.core_mass_lambda * self._core_mass_ratio_loss(
                prob[:, 2:3],
                (core_heatmap >= 0.70).float(),
                support_target.float(),
            )
            core_loss = core_loss + self.rank_lambda * self._rank_head_against_support_negatives(
                prob[:, 2:3],
                core_heatmap,
                support_noncore,
                positive_cutoff=0.70,
                negative_fraction=0.03,
            )

            contact_loss = self._heatmap_bce(
                logits[:, 1:2],
                contact_heatmap,
                contact_valid.expand_as(contact_heatmap),
                pos_weight=14.0,
                soft_weight=5.0,
                neg_weight=1.0,
            )
            support_noncontact = support_target & (contact_heatmap <= 0.01)
            contact_loss = contact_loss + self.contact_floor_lambda * self._floor_on_target(
                prob[:, 1:2],
                contact_heatmap,
                cutoff=0.70,
            )
            contact_loss = contact_loss + self.contact_cap_lambda * self._topk_hinge_on_mask(
                prob[:, 1:2],
                support_noncontact,
                cap=self.negative_cap,
            )
            contact_loss = contact_loss + self.rank_lambda * self._rank_head_against_support_negatives(
                prob[:, 1:2],
                contact_heatmap,
                support_noncontact,
                positive_cutoff=0.70,
                negative_fraction=0.02,
            )

            edge_loss = self._heatmap_bce(
                logits[:, 5:8],
                dense_edge,
                edge_valid,
                pos_weight=10.0,
                soft_weight=4.0,
                neg_weight=1.0,
            )
            edge_loss = edge_loss + self.edge_floor_lambda * self._floor_on_target(
                prob[:, 5:8],
                dense_edge,
                cutoff=0.70,
            )
            rank_loss = self._dense_rank(prob[:, 5:8], dense_edge, edge_valid, instance)

            total = (
                self.core_heatmap_lambda * core_loss
                + self.contact_heatmap_lambda * contact_loss
                + self.edge_heatmap_lambda * edge_loss
                + self.rank_lambda * rank_loss
            )
            if not torch.isfinite(total):
                raise ValueError(f"BICMV58HeatmapMarkerContactLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV59CorePreservingContactLoss(BICMV58HeatmapMarkerContactLoss):
    """V59 contact/edge heatmap phase with core-marker preservation.

    [AUDIT][Risk:High][Scope:single_variable_after_v58]
    V58 proved calibrated heatmap supervision can recover contact recall, but
    the same phase deleted core markers and overpainted contact. V59 keeps the
    V58 target interpretation, sampler, fixed threshold, raw-logit evaluator,
    and decoder. The changed variable is phase-2 coupling: the paired trainer
    freezes core-marker parameters, and this loss optimizes only contact/edge
    heatmap/ranking terms after ``marker_phase_epoch``.

    [QA][Gate:case003_before_expansion][Status:Required]
    This loss is still a case003 root-cause diagnostic. It cannot unlock 159,
    20-case, fold0, or fulltrain unless full-volume fixed-decoder JSON passes
    the support/contact/core-topology/IoU-F gate.
    """

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if not self._is_marker_phase():
            return BICMV54SparseHeadBalancedLoss.forward(self, pred_logits, target)

        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV59CorePreservingContactLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

            support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
            contact_binary = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5
            edge_break = target["edge_break"].to(logits.device).float()
            edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
            instance = target["instance"].to(logits.device).long()

            prob = torch.sigmoid(logits)
            dense_edge = torch.where(
                edge_valid,
                self._dense_edge_target(edge_break),
                torch.zeros_like(edge_break),
            )
            contact_heatmap = torch.max(dense_edge, dim=1, keepdim=True).values
            contact_valid = support_target | contact_binary | (contact_heatmap > 0.0)
            support_noncontact = support_target & (contact_heatmap <= 0.01)

            # [AUDIT][Risk:High][Scope:core_preservation]
            # Do not include a core-marker loss in phase 2. The paired V59
            # trainer freezes the core row so contact heatmap/ranking pressure
            # cannot improve contact by erasing marker topology, which was the
            # measured V58 failure. Core quality is assessed only by the fixed
            # full-volume seed-topology evaluator.
            contact_loss = self._heatmap_bce(
                logits[:, 1:2],
                contact_heatmap,
                contact_valid.expand_as(contact_heatmap),
                pos_weight=14.0,
                soft_weight=5.0,
                neg_weight=1.0,
            )
            contact_loss = contact_loss + self.contact_floor_lambda * self._floor_on_target(
                prob[:, 1:2],
                contact_heatmap,
                cutoff=0.70,
            )
            contact_loss = contact_loss + self.contact_cap_lambda * self._topk_hinge_on_mask(
                prob[:, 1:2],
                support_noncontact,
                cap=self.negative_cap,
            )
            contact_loss = contact_loss + self.rank_lambda * self._rank_head_against_support_negatives(
                prob[:, 1:2],
                contact_heatmap,
                support_noncontact,
                positive_cutoff=0.70,
                negative_fraction=0.02,
            )

            edge_loss = self._heatmap_bce(
                logits[:, 5:8],
                dense_edge,
                edge_valid,
                pos_weight=10.0,
                soft_weight=4.0,
                neg_weight=1.0,
            )
            edge_loss = edge_loss + self.edge_floor_lambda * self._floor_on_target(
                prob[:, 5:8],
                dense_edge,
                cutoff=0.70,
            )
            rank_loss = self._dense_rank(prob[:, 5:8], dense_edge, edge_valid, instance)

            total = (
                self.contact_heatmap_lambda * contact_loss
                + self.edge_heatmap_lambda * edge_loss
                + self.rank_lambda * rank_loss
            )
            if not torch.isfinite(total):
                raise ValueError(f"BICMV59CorePreservingContactLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV60StrictCoreTopologyLoss(BICMV58HeatmapMarkerContactLoss):
    """V60 strict fragment-scale core-marker topology diagnostic.

    [AUDIT][Risk:High][Scope:single_variable_after_v59]
    V59 preserved core coverage but seed topology stayed invalid. V60 therefore
    stops optimizing contact in phase 2 and tests one question only: can an
    independent decoder-feature core branch learn compact fragment-scale markers
    without merging across fragment contact surfaces? Contact metrics are still
    reported by full-volume eval, but they are not optimized in this diagnostic.

    [METRIC][Invariant:fixed_decoder]
    This loss changes train-time core topology pressure only. Evaluation still
    uses raw-logit export, threshold 0.5, and the fixed BICM watershed decoder.
    """

    def __init__(
        self,
        *,
        marker_phase_epoch: int = 5,
        core_heatmap_lambda: float = 3.50,
        core_floor_lambda: float = 3.00,
        core_cap_lambda: float = 2.60,
        contact_barrier_cap_lambda: float = 2.20,
        fragment_mass_lambda: float = 2.00,
        rank_lambda: float = 1.40,
        positive_floor: float = 0.68,
        support_negative_cap: float = 0.16,
        contact_negative_cap: float = 0.08,
    ):
        super().__init__(
            marker_phase_epoch=marker_phase_epoch,
            core_heatmap_lambda=core_heatmap_lambda,
            core_floor_lambda=core_floor_lambda,
            core_cap_lambda=core_cap_lambda,
            rank_lambda=rank_lambda,
            positive_floor=positive_floor,
            negative_cap=support_negative_cap,
        )
        self.contact_barrier_cap_lambda = float(contact_barrier_cap_lambda)
        self.fragment_mass_lambda = float(fragment_mass_lambda)
        self.support_negative_cap = float(support_negative_cap)
        self.contact_negative_cap = float(contact_negative_cap)

    @staticmethod
    def _squeeze_instance(instance: torch.Tensor) -> torch.Tensor:
        if instance.ndim == 5 and int(instance.shape[1]) == 1:
            return instance[:, 0].long()
        if instance.ndim == 4:
            return instance.long()
        raise ValueError(f"BICMV60 expected instance target [B,1,D,H,W] or [B,D,H,W], got {tuple(instance.shape)}")

    def _fragment_core_mass_loss(
        self,
        core_prob: torch.Tensor,
        core_heatmap: torch.Tensor,
        instance: torch.Tensor,
    ) -> torch.Tensor:
        """Constrain each GT fragment to a compact positive core mass.

        [QC][Invariant:fragment_scale_marker]
        Core coverage alone can be perfect while all fragments share one seed
        component. This term uses GT instance IDs from sidecars as supervision
        only and penalizes per-fragment core mass that is far below or far above
        the compact marker target. It does not expose instance IDs to the model.
        """
        prob = core_prob[:, 0]
        strong_target = (core_heatmap[:, 0] >= 0.70).float()
        inst = self._squeeze_instance(instance)
        losses: list[torch.Tensor] = []
        for b in range(int(prob.shape[0])):
            ids = torch.unique(inst[b][inst[b] > 0])
            for frag_id in ids:
                mask = inst[b] == frag_id
                if not mask.any():
                    continue
                target_mass = strong_target[b][mask].sum().clamp_min(1.0)
                pred_mass = prob[b][mask].sum()
                ratio = pred_mass / target_mass
                # [QC][Risk:training_stability]
                # Raw pred/target mass ratios can be thousands at
                # initialization because each fragment contains many support
                # voxels but only a compact marker target. Use a log high-mass
                # penalty so the term still ranks broad cores as bad without
                # producing million-scale losses before the first optimizer
                # step.
                low = F.relu(0.65 - ratio)
                high = torch.log1p(F.relu(ratio - 2.20))
                losses.append(low.pow(2) + high.pow(2))
        if not losses:
            return core_prob.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        if not self._is_marker_phase():
            return BICMV54SparseHeadBalancedLoss.forward(self, pred_logits, target)

        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV60StrictCoreTopologyLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

            support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
            core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
            contact_binary = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1) > 0.5
            edge_break = target["edge_break"].to(logits.device).float()
            edge_valid = target["edge_valid"].to(logits.device).float() > 0.5
            instance = target["instance"].to(logits.device).long()

            core_prob = torch.sigmoid(logits[:, 2:3])
            core_heatmap = self._dense_marker_heatmap(core_target.float(), support_target)
            dense_edge = torch.where(
                edge_valid,
                self._dense_edge_target(edge_break),
                torch.zeros_like(edge_break),
            )
            contact_heatmap = torch.max(dense_edge, dim=1, keepdim=True).values

            support_noncore = support_target & (core_heatmap <= 0.01)
            contact_barrier = support_target & (contact_binary | (contact_heatmap > 0.02))

            # [AUDIT][Risk:High][Scope:contact_disabled]
            # Phase 2 intentionally contains no contact/edge positive loss.
            # V60 isolates marker topology; a contact-zero result is expected
            # unless phase-1 contact survived. Progression requires a later
            # fixed full-volume run to pass the original combined gate.
            core_loss = self._heatmap_bce(
                logits[:, 2:3],
                core_heatmap,
                support_target.expand_as(core_heatmap),
                pos_weight=20.0,
                soft_weight=5.0,
                neg_weight=1.0,
            )
            core_loss = core_loss + self.core_floor_lambda * self._floor_on_target(
                core_prob,
                core_heatmap,
                cutoff=0.70,
            )
            core_loss = core_loss + self.core_cap_lambda * self._topk_hinge_on_mask(
                core_prob,
                support_noncore,
                cap=self.support_negative_cap,
            )
            core_loss = core_loss + self.contact_barrier_cap_lambda * self._topk_hinge_on_mask(
                core_prob,
                contact_barrier,
                cap=self.contact_negative_cap,
            )
            core_loss = core_loss + self.fragment_mass_lambda * self._fragment_core_mass_loss(
                core_prob,
                core_heatmap,
                instance,
            )
            core_loss = core_loss + self.rank_lambda * self._rank_head_against_support_negatives(
                core_prob,
                core_heatmap,
                support_noncore | contact_barrier,
                positive_cutoff=0.70,
                negative_fraction=0.03,
            )

            total = self.core_heatmap_lambda * core_loss
            if not torch.isfinite(total):
                raise ValueError(f"BICMV60StrictCoreTopologyLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV61PeakSeedLoss(BICMV58HeatmapMarkerContactLoss):
    """V61 peak-seed marker representation diagnostic.

    [AUDIT][Risk:High][Scope:marker_representation]
    V60 kept the old decoder contract where every voxel with core probability
    above 0.5 becomes part of a connected-component seed. That contract turns
    broad core plateaus into merged anatomy-level markers and turns noisy core
    islands into seed explosions. V61 changes the seed-supervision contract:
    channel 2 is trained as a compact peak heatmap, and paired evaluation uses
    fixed local maxima as markers. Output channels, Dataset537 materialization,
    sidecars, sampler, and contact/edge heads remain unchanged.

    [QA][Gate:case003_before_expansion][Status:Required]
    This is still a root-cause diagnostic. It cannot unlock `159`, 20-case,
    fold0, or fulltrain unless fixed full-volume case003 JSON passes the
    support/contact/core-topology/IoU-F gate.
    """

    def __init__(
        self,
        *,
        peak_heatmap_lambda: float = 2.40,
        peak_floor_lambda: float = 1.60,
        peak_rank_lambda: float = 1.20,
        peak_cap_lambda: float = 0.90,
        positive_floor: float = 0.62,
        negative_cap: float = 0.20,
    ):
        super().__init__(
            marker_phase_epoch=10 ** 9,
            positive_floor=positive_floor,
            negative_cap=negative_cap,
        )
        self.peak_heatmap_lambda = float(peak_heatmap_lambda)
        self.peak_floor_lambda = float(peak_floor_lambda)
        self.peak_rank_lambda = float(peak_rank_lambda)
        self.peak_cap_lambda = float(peak_cap_lambda)

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        # [AUDIT][Scope:single_variable]
        # Keep the V54 support/contact/edge objective active so this run does
        # not silently become a support-only retrain. The added term changes
        # only how core marker positives are represented for the paired
        # peak-seed decoder.
        total = BICMV54SparseHeadBalancedLoss.forward(self, pred_logits, target)
        with torch.cuda.amp.autocast(enabled=False):
            logits = pred_logits.float()
            if logits.ndim != 5 or int(logits.shape[1]) != 8:
                raise ValueError(f"BICMV61PeakSeedLoss expected logits [B,8,D,H,W], got {tuple(logits.shape)}")

            support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1) > 0.5
            core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1) > 0.5
            core_prob = torch.sigmoid(logits[:, 2:3])
            peak_heatmap = self._dense_marker_heatmap(core_target.float(), support_target)
            support_nonpeak = support_target & (peak_heatmap <= 0.01)

            # [METRIC][Invariant:fixed_threshold]
            # The strongest heatmap voxels must clear the same 0.5 threshold
            # used by the fixed peak-seed decoder. We do not tune per-run
            # thresholds; local maxima below 0.5 are intentionally not seeds.
            peak_loss = self._heatmap_bce(
                logits[:, 2:3],
                peak_heatmap,
                support_target.expand_as(peak_heatmap),
                pos_weight=18.0,
                soft_weight=4.0,
                neg_weight=0.35,
            )
            peak_loss = peak_loss + self.peak_floor_lambda * self._floor_on_target(
                core_prob,
                peak_heatmap,
                cutoff=0.70,
            )
            peak_loss = peak_loss + self.peak_cap_lambda * self._topk_hinge_on_mask(
                core_prob,
                support_nonpeak,
                cap=self.negative_cap,
            )
            peak_loss = peak_loss + self.peak_rank_lambda * self._rank_head_against_support_negatives(
                core_prob,
                peak_heatmap,
                support_nonpeak,
                positive_cutoff=0.70,
                negative_fraction=0.03,
            )
            total = total + self.peak_heatmap_lambda * peak_loss
            if not torch.isfinite(total):
                raise ValueError(f"BICMV61PeakSeedLoss produced non-finite loss: {float(total.detach().cpu())}")
            return total


class BICMV40EdgePrimaryCoreSeparationLoss(BICMV39EdgePrimaryLoss):
    """V40 edge-primary loss with staged core anti-bridge pressure.

    [AUDIT][Risk:High][Scope:single_variable_after_v39]
    V39 proved edge-primary decoding restores contact signal, but every ROI
    still decoded as one fragment because the core head became one large
    anatomy-level marker. V40 keeps V39's edge-primary contact contract and
    changes only core topology pressure, reusing the measured V22/V23
    anti-bridge idea in the V38/V39 sidecar trainer.
    """

    def __init__(
        self,
        *,
        core_noncore_cap_lambda: float = 1.00,
        core_contact_cap_lambda: float = 0.60,
        core_mass_ratio_lambda: float = 0.40,
        core_margin_lambda: float = 0.25,
        core_noncore_cap: float = 0.32,
        core_contact_cap: float = 0.22,
        core_margin: float = 0.35,
        topk_core_fraction: float = 0.03,
        warmup_epochs: int = 2,
        ramp_epochs: int = 3,
    ):
        super().__init__()
        self.core_noncore_cap_lambda = float(core_noncore_cap_lambda)
        self.core_contact_cap_lambda = float(core_contact_cap_lambda)
        self.core_mass_ratio_lambda = float(core_mass_ratio_lambda)
        self.core_margin_lambda = float(core_margin_lambda)
        self.core_noncore_cap = float(core_noncore_cap)
        self.core_contact_cap = float(core_contact_cap)
        self.core_margin = float(core_margin)
        self.topk_core_fraction = float(topk_core_fraction)
        self.warmup_epochs = int(warmup_epochs)
        self.ramp_epochs = max(1, int(ramp_epochs))
        self.current_epoch = 0

    def set_current_epoch(self, epoch: int) -> None:
        self.current_epoch = int(epoch)

    def _phase_weight(self) -> float:
        if self.current_epoch < self.warmup_epochs:
            return 0.0
        return min(1.0, float(self.current_epoch - self.warmup_epochs + 1) / float(self.ramp_epochs))

    def _topk_hinge_on_mask(self, prob: torch.Tensor, mask: torch.Tensor, cap: float) -> torch.Tensor:
        if not mask.any():
            return prob.new_zeros(())
        vals = prob[:, 0][mask[:, 0]]
        if vals.numel() == 0:
            return prob.new_zeros(())
        k = max(1, int(round(float(vals.numel()) * self.topk_core_fraction)))
        hard = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return F.relu(hard - float(cap)).pow(2).mean()

    def _core_mass_ratio_loss(
        self,
        core_prob: torch.Tensor,
        core_target: torch.Tensor,
        support_target: torch.Tensor,
    ) -> torch.Tensor:
        total = core_prob.new_zeros(())
        count = 0
        for idx in range(int(core_prob.shape[0])):
            ct = core_target[idx, 0] > 0.5
            if not ct.any():
                continue
            st = support_target[idx, 0] > 0.5
            pred_mass = (core_prob[idx, 0][st] if st.any() else core_prob[idx, 0].reshape(-1)).sum()
            target_mass = ct.float().sum()
            # [METRIC][Risk:High][Scope:core_marker_size]
            # V39 failed with support-wide core. This log-ratio penalizes core
            # floods without introducing a validation-tuned component-size
            # threshold or postprocess.
            total = total + torch.log((pred_mass + 1.0) / (target_mass + 1.0)).pow(2)
            count += 1
        return total / max(count, 1)

    def _core_vs_shell_margin(
        self,
        core_logit: torch.Tensor,
        support_logit: torch.Tensor,
        core_target: torch.Tensor,
        support_noncore: torch.Tensor,
    ) -> torch.Tensor:
        if not support_noncore.any():
            return core_logit.new_zeros(())
        vals = core_logit[support_noncore] - support_logit[support_noncore] + self.core_margin
        loss = F.relu(vals).mean()
        if core_target.any():
            pos_vals = support_logit[core_target] - core_logit[core_target] + self.core_margin
            loss = loss + 0.25 * F.relu(pos_vals).mean()
        return loss

    def forward(self, pred_logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        total = super().forward(pred_logits, target)
        phase = self._phase_weight()
        if phase <= 0.0:
            return total
        logits = pred_logits.float()
        prob = torch.sigmoid(logits)
        support_prob = prob[:, 0:1]
        core_prob = prob[:, 2:3]
        support_target = self._squeeze_binary(target["support"]).to(logits.device).unsqueeze(1)
        contact_target = self._squeeze_binary(target["contact"]).to(logits.device).unsqueeze(1)
        core_target = self._squeeze_binary(target["core"]).to(logits.device).unsqueeze(1)
        support_noncore = (support_target > 0.5) & (core_target <= 0.5)

        # [QA][Gate:case003_before_159][Status:Required]
        # These staged terms target the exact V39 failure: one broad seed per
        # anatomy. If case003 full-volume still reports seed_components=1 for
        # LeftHip, 159/20-case/fold0/fulltrain remain forbidden.
        total = total + phase * self.core_noncore_cap_lambda * self._topk_hinge_on_mask(
            core_prob, support_noncore, cap=self.core_noncore_cap
        )
        total = total + phase * self.core_contact_cap_lambda * self._topk_hinge_on_mask(
            core_prob, contact_target > 0.5, cap=self.core_contact_cap
        )
        total = total + phase * self.core_mass_ratio_lambda * self._core_mass_ratio_loss(
            core_prob, core_target, support_target
        )
        total = total + phase * self.core_margin_lambda * self._core_vs_shell_margin(
            logits[:, 2],
            logits[:, 0],
            core_target[:, 0] > 0.5,
            support_noncore[:, 0],
        )
        if not torch.isfinite(total):
            raise ValueError(f"BICMV40EdgePrimaryCoreSeparationLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV6SupportCoreLoss(BICMV6FactorizedLoss):
    """Support/core-only V6 diagnostic objective.

    [AUDIT][Risk:High][Scope:root_cause_isolation]
    V6 proved core seed coverage can pass, but both V6 and V6.1 still failed
    full-volume support/contact precision. This diagnostic intentionally
    removes contact supervision from the loss so the next question is singular:
    can the same ct_lut ROI and V5 target geometry overfit support and core on
    case003 before contact is reintroduced?
    """

    def __init__(
        self,
        *,
        support_bce_lambda: float = 1.0,
        support_dice_lambda: float = 1.25,
        support_fp_topk_lambda: float = 0.75,
        core_focal_lambda: float = 1.00,
        core_tversky_lambda: float = 0.70,
        exterior_bce_lambda: float = 0.20,
        core_containment_lambda: float = 0.35,
        topk_fraction: float = 0.02,
        smooth: float = 1e-5,
    ):
        super().__init__(
            support_bce_lambda=support_bce_lambda,
            support_dice_lambda=support_dice_lambda,
            support_fp_topk_lambda=support_fp_topk_lambda,
            contact_focal_lambda=0.0,
            contact_tversky_lambda=0.0,
            core_focal_lambda=core_focal_lambda,
            core_tversky_lambda=core_tversky_lambda,
            exterior_bce_lambda=exterior_bce_lambda,
            containment_lambda=0.0,
            topk_fraction=topk_fraction,
            smooth=smooth,
        )
        self.core_containment_lambda = float(core_containment_lambda)

    def forward(self, pred_logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        labels = self._labels(target).to(device=pred_logits.device)
        self._check_contract(pred_logits, labels)
        # [QC][Risk:High][Invariant:finite_amp_loss]
        # Same AMP guard as the full V6 loss: focal/log operations must run in
        # fp32 or saturated fp16 sigmoid values can create non-finite losses.
        logits = pred_logits.float()
        prob = torch.sigmoid(logits)
        support_prob = prob[:, 0:1]
        core_prob = prob[:, 2:3]

        support_target = ((labels == 2) | (labels == 3) | (labels == 4)).float().unsqueeze(1)
        core_target = (labels == 3).float().unsqueeze(1)
        exterior_target = (labels == 1).float().unsqueeze(1)

        total = logits.new_zeros(())
        total = total + self.support_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 0:1], support_target
        )
        total = total + self.support_dice_lambda * self._dice_loss(support_prob, support_target)
        total = total + self.support_fp_topk_lambda * self._topk_false_positive(support_prob, support_target)
        total = total + self.core_tversky_lambda * self._tversky(
            core_prob, core_target, fp_weight=0.35, fn_weight=0.75
        )
        total = total + self.core_focal_lambda * self._balanced_focal(
            core_prob, core_target, pos_alpha=0.85, neg_alpha=0.12
        )
        total = total + self.exterior_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 3:4], exterior_target
        )
        # [QC][Invariant:core_subset_support]
        # Core markers must live inside predicted support for the fixed decoder.
        # Contact is intentionally not part of this diagnostic loss.
        total = total + self.core_containment_lambda * F.relu(core_prob - support_prob).mean()
        if not torch.isfinite(total):
            raise ValueError(f"BICMV6SupportCoreLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV6SupportPrecisionLoss(BICMV6SupportCoreLoss):
    """Support-precision V6 diagnostic after sampling-only failed.

    [AUDIT][Risk:High][Scope:support_geometry_root_cause]
    V6.2 removed contact supervision and V6.3 added exterior-heavy sampling,
    but case003 support HD95 stayed near 80 mm. This profile changes only the
    support/core loss pressure while keeping the V6 output heads, Dataset537
    ROI, fixed threshold, decoder, and mixed sampling unchanged.

    [METRIC][Gate:case003_support_geometry]
    The pass/fail evidence is still full-volume support Dice/HD95/NSD JSON,
    not patch validation. This profile is not a promotion recipe by itself.
    """

    def __init__(self):
        super().__init__(
            support_bce_lambda=1.15,
            support_dice_lambda=0.75,
            support_fp_topk_lambda=2.50,
            core_focal_lambda=0.90,
            core_tversky_lambda=0.65,
            exterior_bce_lambda=0.55,
            core_containment_lambda=0.35,
            topk_fraction=0.08,
            smooth=1e-5,
        )

    def forward(self, pred_logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        labels = self._labels(target).to(device=pred_logits.device)
        self._check_contract(pred_logits, labels)
        logits = pred_logits.float()
        prob = torch.sigmoid(logits)
        support_prob = prob[:, 0:1]
        core_prob = prob[:, 2:3]

        support_target = ((labels == 2) | (labels == 3) | (labels == 4)).float().unsqueeze(1)
        core_target = (labels == 3).float().unsqueeze(1)
        exterior_target = (labels == 1).float().unsqueeze(1)

        total = logits.new_zeros(())
        total = total + self.support_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 0:1], support_target
        )
        total = total + self.support_dice_lambda * self._dice_loss(support_prob, support_target)
        # [METRIC][Risk:High][Scope:support_fp_hd95]
        # HD95 is dominated by distant false support islands. The precision
        # Tversky term and larger top-k fraction explicitly penalize high
        # support probability on non-support voxels instead of only optimizing
        # overlap volume.
        total = total + 0.90 * self._tversky(
            support_prob, support_target, fp_weight=0.80, fn_weight=0.30
        )
        total = total + self.support_fp_topk_lambda * self._topk_false_positive(
            support_prob, support_target
        )
        total = total + self.core_tversky_lambda * self._tversky(
            core_prob, core_target, fp_weight=0.35, fn_weight=0.75
        )
        total = total + self.core_focal_lambda * self._balanced_focal(
            core_prob, core_target, pos_alpha=0.85, neg_alpha=0.12
        )
        total = total + self.exterior_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 3:4], exterior_target
        )
        total = total + self.core_containment_lambda * F.relu(core_prob - support_prob).mean()
        if not torch.isfinite(total):
            raise ValueError(f"BICMV6SupportPrecisionLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV6SupportSurfaceLoss(BICMV6SupportCoreLoss):
    """Support surface-distance diagnostic for V6.6.

    [AUDIT][Risk:High][Scope:support_hd95]
    V6.2-V6.5 removed contact, changed sampling, changed FP pressure, and
    lowered LR, but case003 support HD95 stayed near 80 mm. The remaining
    single changed variable is explicit support surface supervision. The target
    signed-distance map is derived only from the current crop labels; no
    validation threshold, GT instance IDs, or decoder output is used.

    [QC][Performance]
    Exact EDT is computed on CPU from the target crop. This is intentionally a
    small case003 root-cause experiment, not a fulltrain-ready optimized
    sidecar path. If it passes, the distance maps should be materialized as
    preprocessed sidecars before 20-case/fold0 training.
    """

    def __init__(
        self,
        *,
        support_surface_lambda: float = 0.45,
        surface_clip_vox: float = 32.0,
    ):
        super().__init__(
            support_bce_lambda=1.0,
            support_dice_lambda=1.10,
            support_fp_topk_lambda=0.85,
            core_focal_lambda=1.00,
            core_tversky_lambda=0.70,
            exterior_bce_lambda=0.20,
            core_containment_lambda=0.35,
            topk_fraction=0.03,
            smooth=1e-5,
        )
        self.support_surface_lambda = float(support_surface_lambda)
        self.surface_clip_vox = float(surface_clip_vox)

    def _support_signed_distance(self, support_target: torch.Tensor) -> torch.Tensor:
        """Return clipped signed distance for target support.

        Negative values are inside GT support and positive values are outside.
        The Kervadec-style boundary term `mean(p * phi)` then penalizes false
        positives far outside support and rewards support probability inside.
        """
        support_np = support_target.detach().to(device="cpu", dtype=torch.bool).numpy()
        out = np.zeros(support_np.shape, dtype=np.float32)
        clip = max(float(self.surface_clip_vox), 1.0)
        for b in range(support_np.shape[0]):
            mask = support_np[b, 0]
            if not mask.any():
                out[b, 0] = 1.0
                continue
            if mask.all():
                out[b, 0] = -1.0
                continue
            outside = ndi.distance_transform_edt(~mask)
            inside = ndi.distance_transform_edt(mask)
            phi = np.clip(outside - inside, -clip, clip) / clip
            out[b, 0] = phi.astype(np.float32, copy=False)
        return torch.from_numpy(out).to(device=support_target.device, dtype=torch.float32)

    def forward(self, pred_logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        labels = self._labels(target).to(device=pred_logits.device)
        self._check_contract(pred_logits, labels)
        logits = pred_logits.float()
        prob = torch.sigmoid(logits)
        support_prob = prob[:, 0:1]
        core_prob = prob[:, 2:3]

        support_target = ((labels == 2) | (labels == 3) | (labels == 4)).float().unsqueeze(1)
        core_target = (labels == 3).float().unsqueeze(1)
        exterior_target = (labels == 1).float().unsqueeze(1)

        total = logits.new_zeros(())
        total = total + self.support_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 0:1], support_target
        )
        total = total + self.support_dice_lambda * self._dice_loss(support_prob, support_target)
        total = total + self.support_fp_topk_lambda * self._topk_false_positive(
            support_prob, support_target
        )
        # [METRIC][Risk:High][Scope:surface_distance]
        # This term is the V6.6 changed variable. It directly links support
        # probability to the signed distance from the GT support surface, which
        # BCE/Dice/top-k failed to control in V6.2-V6.5.
        signed_distance = self._support_signed_distance(support_target)
        total = total + self.support_surface_lambda * (support_prob * signed_distance).mean()
        total = total + self.core_tversky_lambda * self._tversky(
            core_prob, core_target, fp_weight=0.35, fn_weight=0.75
        )
        total = total + self.core_focal_lambda * self._balanced_focal(
            core_prob, core_target, pos_alpha=0.85, neg_alpha=0.12
        )
        total = total + self.exterior_bce_lambda * F.binary_cross_entropy_with_logits(
            logits[:, 3:4], exterior_target
        )
        total = total + self.core_containment_lambda * F.relu(core_prob - support_prob).mean()
        if not torch.isfinite(total):
            raise ValueError(f"BICMV6SupportSurfaceLoss produced non-finite loss: {float(total.detach().cpu())}")
        return total


class BICMV5SparseDeepSupervisionWrapper(nn.Module):
    """Apply V5 sparse rare-class terms only at full resolution.

    [AUDIT][Risk:High][Scope:deep_supervision]
    The V5 core markers are often single-digit voxels. Low-resolution deep
    supervision can erase those markers during downsampling, so sparse
    core/contact terms are restricted to the full-resolution output. Auxiliary
    scales still receive base DC+CE plus support Dice as a coarse geometry
    health check.
    """

    def __init__(self, fullres_loss: nn.Module, aux_loss: nn.Module, weight_factors):
        super().__init__()
        self.fullres_loss = fullres_loss
        self.aux_loss = aux_loss
        self.weight_factors = tuple(float(x) for x in weight_factors)
        if not any(x != 0 for x in self.weight_factors):
            raise ValueError("At least one deep-supervision weight must be nonzero")

    def forward(self, *args):
        if not all(isinstance(i, (tuple, list)) for i in args):
            raise AssertionError(f"all args must be tuple/list, got {[type(i) for i in args]}")
        total = None
        for idx, inputs in enumerate(zip(*args)):
            weight = self.weight_factors[idx]
            if weight == 0:
                continue
            loss = self.fullres_loss(*inputs) if idx == 0 else self.aux_loss(*inputs)
            total = weight * loss if total is None else total + weight * loss
        return total


# =============================================================================
# 1. Boundary DoU loss (3D) — surface-aware regularizer
# =============================================================================
class BoundaryDoULoss3D(nn.Module):
    """3D adaptation of Sun et al. MICCAI'23 Boundary DoU loss.

    Algorithm (per foreground class c, each batch item):
      1. Identify "interior" voxels of the target: voxels whose 6 axis-aligned
         neighbors are ALL inside the target. Boundary band = target − interior.
      2. Compute boundary fraction α_c = 1 − boundary / total (per class).
         Clip to ≤ 0.8 for numerical stability (paper recommendation).
      3. Loss_c = (z + y − 2·intersect) / (z + y − (1 + α)·intersect)
         where z = ||score||², y = ||target||², intersect = ⟨score, target⟩.
         When α → 1 (target mostly interior), denom → numer, loss saturates.
         When α → 0 (target is mostly boundary), loss reduces to DoU acting
         like standard Dice but emphasizing boundary alignment.
      4. Mean across foreground classes (background excluded).

    Why 3D adaptation matters:
        Original paper does per-slice 2D conv on (B, H, W). For volumetric CT
        (B, C, D, H, W), 2D convs would only see in-plane neighbors; we use a
        7-tap 3D cross kernel so erosion respects through-plane connectivity.
        This is critical for PENGWIN where fracture surfaces span multiple
        slices.

    Args:
        n_classes: total number of classes including background. Background
            (class 0) is skipped in the loss sum.
        smooth: numerical smoothing constant (1e-5 matches paper).
        background_index: class index treated as background (default 0).

    Forward:
        logits:      (B, C, D, H, W) raw network outputs (pre-softmax)
        target:      (B, D, H, W) integer class labels OR (B, 1, D, H, W)
    Returns: scalar loss (mean over foreground classes).
    """

    def __init__(self, n_classes: int, smooth: float = 1e-5,
                 background_index: int = 0):
        super().__init__()
        self.n_classes = n_classes
        self.smooth = smooth
        self.background_index = background_index
        # 6-connected 3D cross kernel (D=H=W=3). 7 ones total: center + 6 neighbors.
        # Convolving binary target with this counts how many of {self ∪ 6 axis
        # neighbors} are foreground. Maximum value 7 = "fully interior".
        kernel = torch.zeros(1, 1, 3, 3, 3)
        kernel[0, 0, 1, 1, 1] = 1   # center
        kernel[0, 0, 0, 1, 1] = 1   # -z
        kernel[0, 0, 2, 1, 1] = 1   # +z
        kernel[0, 0, 1, 0, 1] = 1   # -y
        kernel[0, 0, 1, 2, 1] = 1   # +y
        kernel[0, 0, 1, 1, 0] = 1   # -x
        kernel[0, 0, 1, 1, 2] = 1   # +x
        # Buffer (not parameter) — moves with .to(device) automatically.
        self.register_buffer("kernel", kernel)
        self._kernel_sum = float(kernel.sum().item())

    def _alpha(self, target_c: torch.Tensor) -> torch.Tensor:
        """Boundary fraction-derived α coefficient for one class.

        target_c: (B, D, H, W) binary {0,1} mask.
        Returns scalar α ∈ [-1, 0.8] (clipped per paper).
        """
        if target_c.sum() == 0:
            # Empty class in this batch — degenerate; return α=0 (≡ standard Dice form).
            return target_c.new_zeros(())

        x = target_c.unsqueeze(1).float()                # (B,1,D,H,W) — float32
        # AMP+device safe: kernel buffer was registered without .cuda(), and
        # nnU-Net's `loss = loss.to(device)` may not always propagate to
        # buffers added in subclasses. Explicitly match BOTH device + dtype.
        kernel = self.kernel.to(device=x.device, dtype=x.dtype)
        conv = F.conv3d(x, kernel, padding=1)       # neighbor sum
        # Voxel is "interior" iff ALL 7 kernel positions land on foreground.
        # Strict equality avoids surface tangents counting as interior.
        interior = (conv >= self._kernel_sum) & (x > 0)
        n_interior = interior.float().sum()
        n_total = x.sum() + self.smooth
        boundary_frac = 1.0 - (n_interior / n_total)
        # α = 1 - boundary_frac (so high α = "mostly interior" → loss less aggressive)
        alpha = 1.0 - boundary_frac
        # Map [0,1] → [-1, 1] then clamp ≤ 0.8 (paper Sec. 3.2 stability).
        alpha = (2 * alpha - 1).clamp(max=0.8)
        return alpha

    def _per_class(self, score_c: torch.Tensor,
                   target_c: torch.Tensor) -> torch.Tensor:
        """DoU-like loss for one class (paper Eq. 8 in 3D form)."""
        alpha = self._alpha(target_c)
        target_f = target_c.float()
        intersect = (score_c * target_f).sum()
        y_sum = (target_f * target_f).sum()
        z_sum = (score_c * score_c).sum()
        num = z_sum + y_sum - 2 * intersect + self.smooth
        den = z_sum + y_sum - (1.0 + alpha) * intersect + self.smooth
        return num / den

    def forward(self, logits: torch.Tensor,
                target: torch.Tensor) -> torch.Tensor:
        """Compute mean boundary DoU loss across foreground classes.

        Inputs are aligned with nnU-Net convention:
            logits:  (B, C, D, H, W)  -- pre-softmax (any dtype: AMP fp16 OK)
            target:  (B, D, H, W) or (B, 1, D, H, W) integer labels

        AMP-safe: disables `torch.cuda.amp.autocast` inside, so all internal
        arithmetic (softmax + conv3d + DoU formula) runs in float32 regardless
        of the surrounding autocast context. Without this guard, calling
        `tensor.float()` inside autocast still gets re-cast to half on
        autocast-enabled ops (conv3d, mul, etc.), which then mismatches our
        float32 kernel buffer. nnU-Net's GradScaler handles the float32 scalar
        return correctly. Boundary loss is <5% of total compute so float32 is
        cheap.
        """
        if target.dim() == 5:
            target = target.squeeze(1)
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            probs = F.softmax(logits_f32, dim=1)
            n_fg = 0
            loss = logits_f32.new_zeros(())
            for c in range(self.n_classes):
                if c == self.background_index:
                    continue
                target_c = (target == c).long()
                score_c = probs[:, c]
                # Skip empty-on-both-sides classes to avoid degenerate gradients.
                if target_c.sum() == 0 and score_c.sum() < self.smooth:
                    continue
                loss = loss + self._per_class(score_c, target_c)
                n_fg += 1
            if n_fg == 0:
                return loss
            return loss / n_fg


# =============================================================================
# 2. Compound loss (Dice + CE + BoundaryDoU) wrapper
# =============================================================================
class DC_CE_BD_loss(nn.Module):
    """Compound loss: w_dc·Dice + w_ce·CE + w_bd·BoundaryDoU.

    Designed as a drop-in replacement for nnU-Net's `DC_and_CE_loss` so the
    deep-supervision wrapper continues to work unchanged. Wraps an existing
    `DC_and_CE_loss` instance (passed in) and adds a BoundaryDoU3D term.

    Default weights chosen for PENGWIN:
        w_dc = 1.0, w_ce = 1.0, w_bd = 0.3
        — Sun et al. recommend ~0.3 for additive boundary; matches typical
        compound loss budget where boundary pulls without dominating.

    Why we wrap rather than re-implement DC+CE:
        nnU-Net's DC_and_CE_loss handles `ignore_label`, `batch_dice`,
        DDP smoothing, and edge cases. Re-implementing risks subtle bugs.

    Args:
        dc_ce_loss:  pre-built nnU-Net DC_and_CE_loss instance.
        n_classes:   number of segmentation classes (incl. background).
        weight_dc_ce: weight for the DC+CE term (default 1.0).
        weight_bd:   weight for the boundary DoU term (default 0.3).

    Forward:
        logits:  (B, C, D, H, W)
        target:  (B, 1, D, H, W) integer labels (nnU-Net convention)
    """

    def __init__(self, dc_ce_loss: nn.Module, n_classes: int,
                 weight_dc_ce: float = 1.0, weight_bd: float = 0.3):
        super().__init__()
        self.dc_ce = dc_ce_loss
        self.bd = BoundaryDoULoss3D(n_classes=n_classes)
        self.weight_dc_ce = weight_dc_ce
        self.weight_bd = weight_bd
        # Expose `.dc` so nnU-Net's torch.compile path (which calls
        # `loss.dc = torch.compile(loss.dc)` in nnUNetTrainer._build_loss)
        # still works without modification.
        if hasattr(dc_ce_loss, "dc"):
            self.dc = dc_ce_loss.dc

    def forward(self, logits: torch.Tensor,
                target: torch.Tensor) -> torch.Tensor:
        l_dc_ce = self.dc_ce(logits, target)
        l_bd = self.bd(logits, target)
        return self.weight_dc_ce * l_dc_ce + self.weight_bd * l_bd


# =============================================================================
# 3. Tversky loss (3D) — weak-class / recall-oriented ablation
# =============================================================================
class SoftTverskyLoss3D(nn.Module):
    """Weighted multi-class Tversky loss for 3D anatomy segmentation.

    Tversky generalizes Dice with separate false-positive and false-negative
    weights:

        T = TP / (TP + alpha * FP + beta * FN)

    By default this keeps foreground-only behavior. Ablations can pass
    `active_classes` to include a targeted subset, including background.

    Args:
        n_classes: total classes including background.
        alpha: false-positive weight. Smaller values tolerate extra foreground.
        beta: false-negative weight. Larger values emphasize recall.
        smooth: numerical smoothing.
        background_index: class skipped only when active_classes is omitted.
        active_classes: explicit class IDs to include. If None, use all classes
            except background_index.
        class_weights: optional dense list or {class_id: weight}; weights are
            normalized by the sum of weights actually used in the batch.
    """

    def __init__(self, n_classes: int, alpha: float = 0.3, beta: float = 0.7,
                 smooth: float = 1e-5, background_index: int = 0,
                 active_classes: list[int] | tuple[int, ...] | None = None,
                 class_weights: list[float] | tuple[float, ...] | dict[int, float] | None = None):
        super().__init__()
        self.n_classes = int(n_classes)
        self.alpha = float(alpha)
        self.beta = float(beta)
        self.smooth = float(smooth)
        self.background_index = int(background_index)
        if active_classes is None:
            active_classes = [c for c in range(self.n_classes) if c != self.background_index]
        self.active_classes = tuple(int(c) for c in active_classes if 0 <= int(c) < self.n_classes)

        weight_arr = torch.ones(self.n_classes, dtype=torch.float32)
        if class_weights is not None:
            if isinstance(class_weights, dict):
                for k, v in class_weights.items():
                    k = int(k)
                    if 0 <= k < self.n_classes:
                        weight_arr[k] = float(v)
            else:
                arr = torch.as_tensor(class_weights, dtype=torch.float32)
                if arr.numel() != self.n_classes:
                    raise ValueError(
                        f"class_weights must have {self.n_classes} values, got {arr.numel()}"
                    )
                weight_arr = arr.reshape(self.n_classes)
        self.register_buffer("class_weights", weight_arr)

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        if target.dim() == 5:
            target = target.squeeze(1)
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            probs = F.softmax(logits_f32, dim=1)
            loss = logits_f32.new_zeros(())
            weight_sum = logits_f32.new_zeros(())
            for c in self.active_classes:
                target_c = (target == c).float()
                score_c = probs[:, c]
                # Empty-on-both classes add noise but no useful gradient.
                if target_c.sum() == 0 and score_c.sum() < self.smooth:
                    continue
                tp = (score_c * target_c).sum()
                fp = (score_c * (1.0 - target_c)).sum()
                fn = ((1.0 - score_c) * target_c).sum()
                tversky = (tp + self.smooth) / (
                    tp + self.alpha * fp + self.beta * fn + self.smooth
                )
                weight = self.class_weights.to(device=logits_f32.device, dtype=logits_f32.dtype)[c]
                loss = loss + weight * (1.0 - tversky)
                weight_sum = weight_sum + weight
            if weight_sum <= 0:
                return loss
            return loss / weight_sum


class ContactEnergyLoss3D(nn.Module):
    """Non-Dice objective for Contact-Energy ABBC training.

    Contact-Energy V2 should not optimize the class-3 fracture/contact surface
    as a broad overlap mask. The decoder uses contact probability as a crossing
    cost, so false-positive contact ridges are expensive and stable core seeds
    are required for marker assignment. This loss therefore uses:

    - weighted cross entropy for the full semantic contract;
    - focal one-vs-rest contact supervision, with stronger negative penalty;
    - focal one-vs-rest core supervision for marker stability.

    No Dice/Tversky term is used here. Deep supervision can wrap this module in
    the same way it wraps nnU-Net's default loss.
    """

    def __init__(self, n_classes: int,
                 ce_weight: torch.Tensor | None = None,
                 ignore_label: int | None = None,
                 contact_class: int = 3,
                 core_class: int = 2,
                 contact_weight: float = 2.0,
                 contact_fp_weight: float = 3.0,
                 contact_pos_weight: float = 1.0,
                 core_weight: float = 0.75,
                 core_fp_weight: float = 1.0,
                 core_pos_weight: float = 1.25,
                 gamma: float = 2.0,
                 eps: float = 1e-6):
        super().__init__()
        self.n_classes = int(n_classes)
        self.ignore_label = ignore_label
        self.contact_class = int(contact_class)
        self.core_class = int(core_class)
        self.contact_weight = float(contact_weight)
        self.contact_fp_weight = float(contact_fp_weight)
        self.contact_pos_weight = float(contact_pos_weight)
        self.core_weight = float(core_weight)
        self.core_fp_weight = float(core_fp_weight)
        self.core_pos_weight = float(core_pos_weight)
        self.gamma = float(gamma)
        self.eps = float(eps)
        if ce_weight is None:
            self.register_buffer("ce_weight", None)
        else:
            self.register_buffer("ce_weight", ce_weight.detach().float().clone())

    def _binary_focal(self, prob: torch.Tensor, target: torch.Tensor,
                      valid: torch.Tensor, *, pos_weight: float,
                      neg_weight: float) -> torch.Tensor:
        prob = prob.clamp(self.eps, 1.0 - self.eps)
        target = target.bool() & valid
        negative = (~target) & valid
        loss = prob.new_zeros(())
        denom = prob.new_zeros(())
        if target.any():
            pos = -((1.0 - prob[target]) ** self.gamma) * torch.log(prob[target])
            loss = loss + float(pos_weight) * pos.mean()
            denom = denom + float(pos_weight)
        if negative.any():
            neg = -(prob[negative] ** self.gamma) * torch.log1p(-prob[negative])
            loss = loss + float(neg_weight) * neg.mean()
            denom = denom + float(neg_weight)
        if denom <= 0:
            return loss
        return loss / denom

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        if target.dim() == 5:
            target = target.squeeze(1)
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            target_long = target.long()
            valid = torch.ones_like(target_long, dtype=torch.bool)
            ce_target = target_long
            if self.ignore_label is not None:
                valid = target_long != int(self.ignore_label)
                ce_target = target_long.clone()
                ce_target[~valid] = 0

            ce_weight = None
            if self.ce_weight is not None:
                ce_weight = self.ce_weight.to(device=logits_f32.device, dtype=logits_f32.dtype)
            ce = F.cross_entropy(
                logits_f32,
                ce_target,
                weight=ce_weight,
                ignore_index=int(self.ignore_label) if self.ignore_label is not None else -100,
            )

            probs = F.softmax(logits_f32, dim=1)
            contact_target = ce_target == self.contact_class
            core_target = ce_target == self.core_class

            # Contact negatives are evaluated inside the valid region. Normalizing
            # positive and negative terms separately prevents background volume
            # from overwhelming the sparse contact surface.
            contact = self._binary_focal(
                probs[:, self.contact_class],
                contact_target,
                valid,
                pos_weight=self.contact_pos_weight,
                neg_weight=self.contact_fp_weight,
            )
            core = self._binary_focal(
                probs[:, self.core_class],
                core_target,
                valid,
                pos_weight=self.core_pos_weight,
                neg_weight=self.core_fp_weight,
            )
            return ce + self.contact_weight * contact + self.core_weight * core


class ContactFuseLoss3D(ContactEnergyLoss3D):
    """Contact-LegacyFuse objective with explicit hard-negative supervision.

    Dataset537 adds class 4 (`contact_hard_negative`) for voxels where contact
    false positives are especially damaging: outside-pelvis bone-like CT,
    foundation leakage, and non-contact cortical surfaces. The class is not a
    decoder fragment. It exists to teach the contact head where *not* to build
    an energy ridge.

    The objective keeps dense CE for the 5-class semantic contract, then adds:
        - precision-oriented contact focal loss;
        - core focal loss for marker stability;
        - class-4 focal loss for hard-negative recognition;
        - online top-k false-contact mining over non-contact voxels.

    No Dice/Tversky term is used for contact because overlap-heavy objectives
    encouraged high-recall, low-precision separator maps in the previous runs.
    """

    def __init__(self, n_classes: int,
                 ce_weight: torch.Tensor | None = None,
                 ignore_label: int | None = None,
                 contact_class: int = 3,
                 core_class: int = 2,
                 hard_negative_class: int = 4,
                 contact_weight: float = 2.5,
                 contact_fp_weight: float = 5.0,
                 contact_pos_weight: float = 0.75,
                 core_weight: float = 0.80,
                 core_fp_weight: float = 1.0,
                 core_pos_weight: float = 1.35,
                 hard_negative_weight: float = 1.25,
                 hard_negative_contact_penalty: float = 2.5,
                 topk_false_contact_weight: float = 1.5,
                 topk_fraction: float = 0.02,
                 gamma: float = 2.0,
                 eps: float = 1e-6):
        super().__init__(
            n_classes=n_classes,
            ce_weight=ce_weight,
            ignore_label=ignore_label,
            contact_class=contact_class,
            core_class=core_class,
            contact_weight=contact_weight,
            contact_fp_weight=contact_fp_weight,
            contact_pos_weight=contact_pos_weight,
            core_weight=core_weight,
            core_fp_weight=core_fp_weight,
            core_pos_weight=core_pos_weight,
            gamma=gamma,
            eps=eps,
        )
        self.hard_negative_class = int(hard_negative_class)
        self.hard_negative_weight = float(hard_negative_weight)
        self.hard_negative_contact_penalty = float(hard_negative_contact_penalty)
        self.topk_false_contact_weight = float(topk_false_contact_weight)
        self.topk_fraction = float(topk_fraction)

    def _topk_false_contact(self, contact_prob: torch.Tensor,
                            contact_target: torch.Tensor,
                            valid: torch.Tensor) -> torch.Tensor:
        negative = valid & ~contact_target.bool()
        if not negative.any():
            return contact_prob.new_zeros(())
        vals = contact_prob[negative].clamp(self.eps, 1.0 - self.eps)
        k = max(1, int(round(float(vals.numel()) * self.topk_fraction)))
        vals = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return -((vals ** self.gamma) * torch.log1p(-vals)).mean()

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        if target.dim() == 5:
            target = target.squeeze(1)
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            target_long = target.long()
            valid = torch.ones_like(target_long, dtype=torch.bool)
            ce_target = target_long
            if self.ignore_label is not None:
                valid = target_long != int(self.ignore_label)
                ce_target = target_long.clone()
                ce_target[~valid] = 0

            ce_weight = None
            if self.ce_weight is not None:
                ce_weight = self.ce_weight.to(device=logits_f32.device, dtype=logits_f32.dtype)
            ce = F.cross_entropy(
                logits_f32,
                ce_target,
                weight=ce_weight,
                ignore_index=int(self.ignore_label) if self.ignore_label is not None else -100,
            )

            probs = F.softmax(logits_f32, dim=1)
            contact_prob = probs[:, self.contact_class]
            contact_target = ce_target == self.contact_class
            core_target = ce_target == self.core_class
            hard_target = ce_target == self.hard_negative_class

            contact = self._binary_focal(
                contact_prob,
                contact_target,
                valid,
                pos_weight=self.contact_pos_weight,
                neg_weight=self.contact_fp_weight,
            )
            core = self._binary_focal(
                probs[:, self.core_class],
                core_target,
                valid,
                pos_weight=self.core_pos_weight,
                neg_weight=self.core_fp_weight,
            )
            hard_negative = self._binary_focal(
                probs[:, self.hard_negative_class],
                hard_target,
                valid,
                pos_weight=1.5,
                neg_weight=0.5,
            )

            hard_contact_penalty = contact_prob.new_zeros(())
            if hard_target.any():
                hp = contact_prob[hard_target & valid].clamp(self.eps, 1.0 - self.eps)
                hard_contact_penalty = -((hp ** self.gamma) * torch.log1p(-hp)).mean()

            topk_false = self._topk_false_contact(contact_prob, contact_target, valid)
            return (
                ce
                + self.contact_weight * contact
                + self.core_weight * core
                + self.hard_negative_weight * hard_negative
                + self.hard_negative_contact_penalty * hard_contact_penalty
                + self.topk_false_contact_weight * topk_false
            )


class LegacyTopologyLoss3D(nn.Module):
    """Multi-head loss for Dataset537 Contact-Instance V1.

    This loss intentionally avoids softmax Dice. Dataset537 labels are raw
    pelvic fragment IDs, while the network predicts a fixed instance
    representation:

        0 support, 1 core/center, 2 contact energy, 3 hard-negative,
        4..6 offset-to-fragment-center, 7..14 embedding.

    The sparse contact head is optimized for precision via focal negatives and
    top-k false-contact mining. Offset and embedding terms are evaluated only
    inside GT support so background volume does not dominate the objective.
    """

    def __init__(self,
                 contact_weight: float = 3.0,
                 contact_fp_weight: float = 8.0,
                 contact_pos_weight: float = 1.0,
                 core_weight: float = 1.0,
                 support_weight: float = 0.75,
                 hard_negative_weight: float = 1.5,
                 hard_negative_contact_penalty: float = 4.0,
                 offset_weight: float = 0.25,
                 embedding_weight: float = 0.10,
                 topk_false_contact_weight: float = 2.0,
                 topk_fraction: float = 0.02,
                 gamma: float = 2.0,
                 eps: float = 1e-6,
                 offset_scale: float = 64.0,
                 max_embedding_voxels: int = 4096):
        super().__init__()
        self.contact_weight = float(contact_weight)
        self.contact_fp_weight = float(contact_fp_weight)
        self.contact_pos_weight = float(contact_pos_weight)
        self.core_weight = float(core_weight)
        self.support_weight = float(support_weight)
        self.hard_negative_weight = float(hard_negative_weight)
        self.hard_negative_contact_penalty = float(hard_negative_contact_penalty)
        self.offset_weight = float(offset_weight)
        self.embedding_weight = float(embedding_weight)
        self.topk_false_contact_weight = float(topk_false_contact_weight)
        self.topk_fraction = float(topk_fraction)
        self.gamma = float(gamma)
        self.eps = float(eps)
        self.offset_scale = float(offset_scale)
        self.max_embedding_voxels = int(max_embedding_voxels)

    @staticmethod
    def _squeeze_binary(target: torch.Tensor) -> torch.Tensor:
        if target.dim() == 5 and target.shape[1] == 1:
            target = target[:, 0]
        return target.float()

    def _binary_focal(self, logits: torch.Tensor, target: torch.Tensor,
                      *, pos_weight: float = 1.0,
                      neg_weight: float = 1.0) -> torch.Tensor:
        target = target.float()
        prob = torch.sigmoid(logits).clamp(self.eps, 1.0 - self.eps)
        pos = target > 0.5
        neg = ~pos
        loss = logits.new_zeros(())
        denom = 0.0
        if pos.any():
            l_pos = -((1.0 - prob[pos]) ** self.gamma) * torch.log(prob[pos])
            loss = loss + float(pos_weight) * l_pos.mean()
            denom += float(pos_weight)
        if neg.any():
            l_neg = -(prob[neg] ** self.gamma) * torch.log1p(-prob[neg])
            loss = loss + float(neg_weight) * l_neg.mean()
            denom += float(neg_weight)
        return loss if denom <= 0 else loss / denom

    def _topk_false_contact(self, contact_logits: torch.Tensor,
                            contact_target: torch.Tensor) -> torch.Tensor:
        contact_prob = torch.sigmoid(contact_logits).clamp(self.eps, 1.0 - self.eps)
        negative = contact_target <= 0.5
        if not negative.any():
            return contact_logits.new_zeros(())
        vals = contact_prob[negative]
        k = max(1, int(round(float(vals.numel()) * self.topk_fraction)))
        vals = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return -((vals ** self.gamma) * torch.log1p(-vals)).mean()

    def _offset_loss(self, pred_offset: torch.Tensor,
                     target_offset: torch.Tensor,
                     support: torch.Tensor) -> torch.Tensor:
        support_mask = support[:, None] > 0.5
        if not support_mask.any():
            return pred_offset.new_zeros(())
        return F.smooth_l1_loss(pred_offset[support_mask.expand_as(pred_offset)],
                                target_offset[support_mask.expand_as(target_offset)],
                                beta=1.0)

    def _embedding_loss(self, emb: torch.Tensor,
                        instance: torch.Tensor,
                        support: torch.Tensor) -> torch.Tensor:
        if instance.dim() == 5 and instance.shape[1] == 1:
            instance = instance[:, 0]
        emb = F.normalize(emb.float(), dim=1)
        losses = []
        for b in range(emb.shape[0]):
            ids = instance[b].long()
            fg_ids = torch.unique(ids[support[b] > 0.5])
            fg_ids = fg_ids[(fg_ids > 0) & (fg_ids <= MAX_INSTANCE_ID)]
            if fg_ids.numel() == 0:
                continue
            means = []
            pull = emb.new_zeros(())
            n_pull = 0
            for inst_id in fg_ids:
                mask = ids == inst_id
                coords = torch.nonzero(mask, as_tuple=False)
                if coords.shape[0] < 2:
                    continue
                if coords.shape[0] > self.max_embedding_voxels:
                    perm = torch.randperm(coords.shape[0], device=coords.device)[:self.max_embedding_voxels]
                    coords = coords[perm]
                vals = emb[b, :, coords[:, 0], coords[:, 1], coords[:, 2]].T
                mean = vals.mean(0)
                means.append(mean)
                dist = torch.norm(vals - mean[None], dim=1)
                pull = pull + torch.clamp(dist - 0.35, min=0.0).pow(2).mean()
                n_pull += 1
            if n_pull:
                pull = pull / float(n_pull)
            if len(means) >= 2:
                means_t = torch.stack(means)
                dist = torch.cdist(means_t[None], means_t[None])[0]
                tri = torch.triu(torch.ones_like(dist, dtype=torch.bool), diagonal=1)
                push = torch.clamp(1.5 - dist[tri], min=0.0).pow(2).mean() if tri.any() else emb.new_zeros(())
            else:
                push = emb.new_zeros(())
            losses.append(pull + push)
        if not losses:
            return emb.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            support = self._squeeze_binary(target["support"]).to(logits_f32.device)
            core = self._squeeze_binary(target["core"]).to(logits_f32.device)
            contact = self._squeeze_binary(target["contact"]).to(logits_f32.device)
            hard_negative = self._squeeze_binary(target["hard_negative"]).to(logits_f32.device)
            offset = target["offset"].to(logits_f32.device).float()
            instance = target["instance"].to(logits_f32.device).long()

            support_loss = self._binary_focal(logits_f32[:, 0], support, pos_weight=1.5, neg_weight=0.75)
            core_loss = self._binary_focal(logits_f32[:, 1], core, pos_weight=2.0, neg_weight=1.0)
            contact_loss = self._binary_focal(
                logits_f32[:, 2],
                contact,
                pos_weight=self.contact_pos_weight,
                neg_weight=self.contact_fp_weight,
            )
            hard_loss = self._binary_focal(logits_f32[:, 3], hard_negative, pos_weight=1.5, neg_weight=0.5)
            hard_contact_penalty = logits_f32.new_zeros(())
            if (hard_negative > 0.5).any():
                hp = torch.sigmoid(logits_f32[:, 2][hard_negative > 0.5]).clamp(self.eps, 1.0 - self.eps)
                hard_contact_penalty = -((hp ** self.gamma) * torch.log1p(-hp)).mean()
            topk_false = self._topk_false_contact(logits_f32[:, 2], contact)
            offset_loss = self._offset_loss(logits_f32[:, 4:7], offset, support)
            embedding_loss = self._embedding_loss(logits_f32[:, 7:15], instance, support)
            return (
                self.support_weight * support_loss
                + self.core_weight * core_loss
                + self.contact_weight * contact_loss
                + self.hard_negative_weight * hard_loss
                + self.hard_negative_contact_penalty * hard_contact_penalty
                + self.topk_false_contact_weight * topk_false
                + self.offset_weight * offset_loss
                + self.embedding_weight * embedding_loss
            )


class FactorizedInstanceV4Loss(LegacyTopologyLoss3D):
    """Primary Dataset537 V4 loss for factorized instance representation.

    Channel order:
        0 support, 1 contact energy, 2 core seed, 3 hard-negative,
        4..6 offset, 7..14 embedding.

    Compared with the old sigmoid prototype, support gets an explicit Dice and
    boundary-band term so geometry failures are visible before decoder IoU-F,
    while embedding is disabled by default until support/contact/core pass the
    overfit gates.
    """

    def __init__(self,
                 contact_weight: float = 4.0,
                 contact_fp_weight: float = 5.0,
                 contact_pos_weight: float = 4.0,
                 core_weight: float = 1.25,
                 support_weight: float = 1.0,
                 support_dice_weight: float = 0.75,
                 support_boundary_weight: float = 0.35,
                 hard_negative_weight: float = 1.5,
                 hard_negative_contact_penalty: float = 5.0,
                 offset_weight: float = 0.25,
                 embedding_weight: float = 0.0,
                 topk_false_contact_weight: float = 2.0,
                 support_topk_false_weight: float = 0.0,
                 support_hard_penalty_weight: float = 0.0,
                 core_topk_false_weight: float = 0.0,
                 support_pos_weight: float = 1.5,
                 support_neg_weight: float = 0.75,
                 core_pos_weight: float = 2.0,
                 core_neg_weight: float = 1.0,
                 hard_pos_weight: float = 1.5,
                 hard_neg_weight: float = 0.5,
                 topk_fraction: float = 0.02,
                 gamma: float = 2.0,
                 eps: float = 1e-6,
                 offset_scale: float = 64.0,
                 max_embedding_voxels: int = 4096):
        super().__init__(
            contact_weight=contact_weight,
            contact_fp_weight=contact_fp_weight,
            contact_pos_weight=contact_pos_weight,
            core_weight=core_weight,
            support_weight=support_weight,
            hard_negative_weight=hard_negative_weight,
            hard_negative_contact_penalty=hard_negative_contact_penalty,
            offset_weight=offset_weight,
            embedding_weight=embedding_weight,
            topk_false_contact_weight=topk_false_contact_weight,
            topk_fraction=topk_fraction,
            gamma=gamma,
            eps=eps,
            offset_scale=offset_scale,
            max_embedding_voxels=max_embedding_voxels,
        )
        self.support_dice_weight = float(support_dice_weight)
        self.support_boundary_weight = float(support_boundary_weight)
        self.support_topk_false_weight = float(support_topk_false_weight)
        self.support_hard_penalty_weight = float(support_hard_penalty_weight)
        self.core_topk_false_weight = float(core_topk_false_weight)
        self.support_pos_weight = float(support_pos_weight)
        self.support_neg_weight = float(support_neg_weight)
        self.core_pos_weight = float(core_pos_weight)
        self.core_neg_weight = float(core_neg_weight)
        self.hard_pos_weight = float(hard_pos_weight)
        self.hard_neg_weight = float(hard_neg_weight)

    def _dice_loss(self, prob: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        dims = tuple(range(1, prob.ndim))
        inter = (prob * target).sum(dim=dims)
        denom = prob.sum(dim=dims) + target.sum(dim=dims)
        return (1.0 - (2.0 * inter + self.eps) / (denom + self.eps)).mean()

    @staticmethod
    def _boundary_band(target: torch.Tensor) -> torch.Tensor:
        if target.ndim == 4:
            target_5d = target[:, None]
        else:
            target_5d = target
        dil = F.max_pool3d(target_5d.float(), kernel_size=3, stride=1, padding=1)
        ero = 1.0 - F.max_pool3d(1.0 - target_5d.float(), kernel_size=3, stride=1, padding=1)
        return ((dil - ero) > 0.0).float().squeeze(1)

    def forward(self, logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            support = self._squeeze_binary(target["support"]).to(logits_f32.device)
            core = self._squeeze_binary(target["core"]).to(logits_f32.device)
            contact = self._squeeze_binary(target["contact"]).to(logits_f32.device)
            hard_negative = self._squeeze_binary(target["hard_negative"]).to(logits_f32.device)
            offset = target["offset"].to(logits_f32.device).float()
            instance = target["instance"].to(logits_f32.device).long()

            support_logits = logits_f32[:, 0]
            contact_logits = logits_f32[:, 1]
            core_logits = logits_f32[:, 2]
            hard_logits = logits_f32[:, 3]
            support_prob = torch.sigmoid(support_logits).clamp(self.eps, 1.0 - self.eps)

            support_focal = self._binary_focal(
                support_logits,
                support,
                pos_weight=self.support_pos_weight,
                neg_weight=self.support_neg_weight,
            )
            support_dice = self._dice_loss(support_prob, support)
            support_topk_false = logits_f32.new_zeros(())
            if self.support_topk_false_weight > 0 and (support <= 0.5).any():
                sp = support_prob[support <= 0.5]
                k = max(1, int(round(float(sp.numel()) * self.topk_fraction)))
                vals = torch.topk(sp, k=min(k, sp.numel()), largest=True).values
                support_topk_false = -((vals ** self.gamma) * torch.log1p(-vals)).mean()
            band = self._boundary_band(support)
            if band.any():
                support_boundary = F.binary_cross_entropy_with_logits(
                    support_logits[band > 0.5],
                    support[band > 0.5],
                )
            else:
                support_boundary = logits_f32.new_zeros(())

            core_loss = self._binary_focal(
                core_logits,
                core,
                pos_weight=self.core_pos_weight,
                neg_weight=self.core_neg_weight,
            )
            core_topk_false = logits_f32.new_zeros(())
            if self.core_topk_false_weight > 0:
                support_noncore = (support > 0.5) & (core <= 0.5)
                if support_noncore.any():
                    cp = torch.sigmoid(core_logits[support_noncore]).clamp(self.eps, 1.0 - self.eps)
                    k = max(1, int(round(float(cp.numel()) * self.topk_fraction)))
                    vals = torch.topk(cp, k=min(k, cp.numel()), largest=True).values
                    core_topk_false = -((vals ** self.gamma) * torch.log1p(-vals)).mean()
            contact_loss = self._binary_focal(
                contact_logits,
                contact,
                pos_weight=self.contact_pos_weight,
                neg_weight=self.contact_fp_weight,
            )
            hard_loss = self._binary_focal(
                hard_logits,
                hard_negative,
                pos_weight=self.hard_pos_weight,
                neg_weight=self.hard_neg_weight,
            )
            support_hard_penalty = logits_f32.new_zeros(())
            if self.support_hard_penalty_weight > 0 and (support > 0.5).any():
                # [AUDIT][Risk:Major][Scope:full_volume_support_gate]
                # Full-volume case003 failed because true support voxels had
                # high hard-negative probability and were removed by the fixed
                # support gate. This penalty is scoped to GT support so it does
                # not weaken the external hard-negative target.
                hp_support = torch.sigmoid(hard_logits[support > 0.5]).clamp(self.eps, 1.0 - self.eps)
                support_hard_penalty = -((hp_support ** self.gamma) * torch.log1p(-hp_support)).mean()
            hard_contact_penalty = logits_f32.new_zeros(())
            if (hard_negative > 0.5).any():
                hp = torch.sigmoid(contact_logits[hard_negative > 0.5]).clamp(self.eps, 1.0 - self.eps)
                hard_contact_penalty = -((hp ** self.gamma) * torch.log1p(-hp)).mean()
            support_noncontact = (support > 0.5) & (contact <= 0.5)
            support_contact_penalty = logits_f32.new_zeros(())
            if support_noncontact.any():
                cp = torch.sigmoid(contact_logits[support_noncontact]).clamp(self.eps, 1.0 - self.eps)
                k = max(1, int(round(float(cp.numel()) * self.topk_fraction)))
                vals = torch.topk(cp, k=min(k, cp.numel()), largest=True).values
                support_contact_penalty = -((vals ** self.gamma) * torch.log1p(-vals)).mean()
            topk_false = self._topk_false_contact(contact_logits, contact)
            offset_loss = self._offset_loss(logits_f32[:, 4:7], offset, support)
            embedding_loss = self._embedding_loss(logits_f32[:, 7:15], instance, support)
            return (
                self.support_weight * support_focal
                + self.support_dice_weight * support_dice
                + self.support_boundary_weight * support_boundary
                + self.support_topk_false_weight * support_topk_false
                + self.core_weight * core_loss
                + self.core_topk_false_weight * core_topk_false
                + self.contact_weight * contact_loss
                + self.hard_negative_weight * hard_loss
                + self.support_hard_penalty_weight * support_hard_penalty
                + self.hard_negative_contact_penalty * hard_contact_penalty
                + self.topk_false_contact_weight * (topk_false + support_contact_penalty)
                + self.offset_weight * offset_loss
                + self.embedding_weight * embedding_loss
            )


class FactorizedInstanceV4SeedFitLoss(FactorizedInstanceV4Loss):
    """V4.1 loss for the observed case003 full-volume failure.

    This profile keeps the successful contact objective mostly intact and
    concentrates the change on the failed heads: support/hard-negative geometry
    and compact core marker specificity.
    """

    def __init__(self):
        super().__init__(
            contact_weight=4.0,
            contact_fp_weight=5.0,
            contact_pos_weight=4.0,
            core_weight=2.5,
            support_weight=1.5,
            support_dice_weight=1.0,
            support_boundary_weight=0.75,
            hard_negative_weight=2.5,
            hard_negative_contact_penalty=5.0,
            offset_weight=0.25,
            embedding_weight=0.0,
            topk_false_contact_weight=2.0,
            support_topk_false_weight=1.5,
            support_hard_penalty_weight=2.0,
            core_topk_false_weight=2.5,
            topk_fraction=0.02,
        )


class FactorizedInstanceV4StagedLoss(FactorizedInstanceV4Loss):
    """V4.2 staged loss for the support/core collapse root cause.

    [AUDIT][Risk:Major][Scope:training_dynamics]
    V4.1 applied compact core targets and hard-negative suppression from epoch 0.
    The observed run collapsed contact/core before full-volume evaluation. This
    profile exposes all critical weights as mutable fields so the trainer can
    warm up support/contact/core before increasing hard-negative and top-k
    precision pressure.
    """

    def __init__(self):
        super().__init__(
            contact_weight=4.0,
            contact_fp_weight=2.0,
            contact_pos_weight=8.0,
            core_weight=4.0,
            support_weight=1.0,
            support_dice_weight=1.0,
            support_boundary_weight=0.35,
            hard_negative_weight=0.5,
            hard_negative_contact_penalty=2.0,
            offset_weight=0.25,
            embedding_weight=0.0,
            topk_false_contact_weight=1.0,
            support_topk_false_weight=0.0,
            support_hard_penalty_weight=0.0,
            core_topk_false_weight=0.0,
            support_pos_weight=1.5,
            support_neg_weight=0.75,
            core_pos_weight=12.0,
            core_neg_weight=0.5,
            hard_pos_weight=1.0,
            hard_neg_weight=0.5,
            topk_fraction=0.01,
        )


class FactorizedInstanceV4SupportFocusLoss(FactorizedInstanceV4Loss):
    """V4.4 loss for the observed full-volume support HD95 failure.

    [AUDIT][Risk:Major][Scope:root_cause_experiment]
    V4.3 made contact precision viable on case003, but full-volume support still
    produced distant false-positive support islands (HD95 57.28 mm). This loss
    keeps the V4.3 contact/core contract and changes only the support pressure:
    stronger support negatives, top-k support false-positive mining, and a
    moderate boundary term. It intentionally avoids the V4.2 abrupt hard-negative
    schedule that collapsed contact/core.

    [QA][Gate:003_support_smoke][Status:Planned]
    This profile is not promotable by patch validation. It is only acceptable if
    full-volume `factorized-instance-eval` improves support Dice/HD95 before a
    longer overfit run is allowed.
    """

    def __init__(self):
        super().__init__(
            contact_weight=3.5,
            contact_fp_weight=5.0,
            contact_pos_weight=5.0,
            core_weight=1.75,
            support_weight=2.0,
            support_dice_weight=1.25,
            support_boundary_weight=0.75,
            hard_negative_weight=1.0,
            hard_negative_contact_penalty=4.0,
            offset_weight=0.25,
            embedding_weight=0.0,
            topk_false_contact_weight=1.5,
            support_topk_false_weight=1.25,
            support_hard_penalty_weight=0.35,
            core_topk_false_weight=0.35,
            support_pos_weight=1.5,
            support_neg_weight=1.25,
            core_pos_weight=4.0,
            core_neg_weight=1.0,
            hard_pos_weight=1.0,
            hard_neg_weight=0.75,
            topk_fraction=0.01,
        )


class LegacyTopologyExclusiveLoss3D(nn.Module):
    """Dataset537 V2 loss with mutually exclusive morphology logits.

    Channels:
        0..3  morphology softmax: background, support_noncontact, contact,
              hard_negative
        4     core/center sigmoid logit
        5..7  offset-to-fragment-center
        8..15 embedding
        16..18 z/y/x edge-break logits

    The important change from `LegacyTopologyLoss3D` is that contact must
    compete directly with ordinary pelvic support and hard negatives. This
    attacks the observed failure mode where the independent sigmoid contact head
    assigned nearly identical probabilities to GT contact and support
    non-contact voxels.
    """

    BG = 0
    SUPPORT = 1
    CONTACT = 2
    HARD = 3

    def __init__(self,
                 morphology_weight: float = 1.0,
                 contact_focal_weight: float = 4.0,
                 contact_margin_weight: float = 0.75,
                 contact_positive_weight: float = 10.0,
                 support_false_contact_weight: float = 3.0,
                 hard_false_contact_weight: float = 6.0,
                 background_false_contact_weight: float = 0.25,
                 topk_false_contact_weight: float = 0.75,
                 topk_fraction: float = 0.02,
                 core_weight: float = 1.0,
                 edge_weight: float = 2.0,
                 edge_pos_weight: float = 6.0,
                 edge_neg_weight: float = 2.0,
                 edge_near_neg_weight: float = 6.0,
                 edge_support_neg_weight: float = 4.0,
                 edge_bg_neg_weight: float = 1.0,
                 offset_weight: float = 0.25,
                 embedding_weight: float = 0.10,
                 gamma: float = 2.0,
                 eps: float = 1e-6,
                 max_embedding_voxels: int = 4096):
        super().__init__()
        self.morphology_weight = float(morphology_weight)
        self.contact_focal_weight = float(contact_focal_weight)
        self.contact_margin_weight = float(contact_margin_weight)
        self.contact_positive_weight = float(contact_positive_weight)
        self.support_false_contact_weight = float(support_false_contact_weight)
        self.hard_false_contact_weight = float(hard_false_contact_weight)
        self.background_false_contact_weight = float(background_false_contact_weight)
        self.topk_false_contact_weight = float(topk_false_contact_weight)
        self.topk_fraction = float(topk_fraction)
        self.core_weight = float(core_weight)
        self.edge_weight = float(edge_weight)
        self.edge_pos_weight = float(edge_pos_weight)
        self.edge_neg_weight = float(edge_neg_weight)
        self.edge_near_neg_weight = float(edge_near_neg_weight)
        self.edge_support_neg_weight = float(edge_support_neg_weight)
        self.edge_bg_neg_weight = float(edge_bg_neg_weight)
        self.offset_weight = float(offset_weight)
        self.embedding_weight = float(embedding_weight)
        self.gamma = float(gamma)
        self.eps = float(eps)
        self.max_embedding_voxels = int(max_embedding_voxels)

    @staticmethod
    def _squeeze(target: torch.Tensor) -> torch.Tensor:
        if target.dim() == 5 and target.shape[1] == 1:
            target = target[:, 0]
        return target

    def _contact_focal(self, contact_prob: torch.Tensor, morphology: torch.Tensor) -> torch.Tensor:
        contact_prob = contact_prob.clamp(self.eps, 1.0 - self.eps)
        pos = morphology == self.CONTACT
        neg_support = morphology == self.SUPPORT
        neg_hard = morphology == self.HARD
        neg_bg = morphology == self.BG
        loss = contact_prob.new_zeros(())
        denom = 0.0
        if pos.any():
            value = -((1.0 - contact_prob[pos]) ** self.gamma) * torch.log(contact_prob[pos])
            loss = loss + self.contact_positive_weight * value.mean()
            denom += self.contact_positive_weight
        for mask, weight in (
            (neg_support, self.support_false_contact_weight),
            (neg_hard, self.hard_false_contact_weight),
            (neg_bg, self.background_false_contact_weight),
        ):
            if mask.any():
                value = -(contact_prob[mask] ** self.gamma) * torch.log1p(-contact_prob[mask])
                loss = loss + float(weight) * value.mean()
                denom += float(weight)
        return loss if denom <= 0 else loss / denom

    def _contact_margin(self, morph_logits: torch.Tensor, morphology: torch.Tensor) -> torch.Tensor:
        contact = morph_logits[:, self.CONTACT]
        support = morph_logits[:, self.SUPPORT]
        hard = morph_logits[:, self.HARD]
        bg = morph_logits[:, self.BG]
        margin = 1.0
        losses = []
        pos = morphology == self.CONTACT
        if pos.any():
            strongest_other = torch.stack([support[pos], hard[pos], bg[pos]], dim=0).amax(dim=0)
            losses.append(torch.relu(strongest_other - contact[pos] + margin).mean())
        sup = morphology == self.SUPPORT
        if sup.any():
            losses.append(torch.relu(contact[sup] - support[sup] + margin).mean())
        hn = morphology == self.HARD
        if hn.any():
            losses.append(torch.relu(contact[hn] - hard[hn] + margin).mean())
        background = morphology == self.BG
        if background.any():
            vals = torch.relu(contact[background] - bg[background] + margin)
            k = max(1, int(round(float(vals.numel()) * self.topk_fraction)))
            losses.append(torch.topk(vals, k=min(k, vals.numel()), largest=True).values.mean())
        if not losses:
            return contact.new_zeros(())
        return torch.stack(losses).mean()

    def _topk_false_contact(self, contact_prob: torch.Tensor, morphology: torch.Tensor) -> torch.Tensor:
        negative = morphology != self.CONTACT
        if not negative.any():
            return contact_prob.new_zeros(())
        vals = contact_prob[negative].clamp(self.eps, 1.0 - self.eps)
        k = max(1, int(round(float(vals.numel()) * self.topk_fraction)))
        vals = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
        return -((vals ** self.gamma) * torch.log1p(-vals)).mean()

    def _core_loss(self, core_logits: torch.Tensor, core_target: torch.Tensor) -> torch.Tensor:
        core_target = core_target.float()
        prob = torch.sigmoid(core_logits).clamp(self.eps, 1.0 - self.eps)
        pos = core_target > 0.5
        neg = ~pos
        loss = core_logits.new_zeros(())
        denom = 0.0
        if pos.any():
            loss = loss + 2.0 * (-((1.0 - prob[pos]) ** self.gamma) * torch.log(prob[pos])).mean()
            denom += 2.0
        if neg.any():
            loss = loss + (-((prob[neg]) ** self.gamma) * torch.log1p(-prob[neg])).mean()
            denom += 1.0
        return loss if denom <= 0 else loss / denom

    def _offset_loss(self, pred_offset: torch.Tensor,
                     target_offset: torch.Tensor,
                     support: torch.Tensor) -> torch.Tensor:
        support_mask = support[:, None] > 0.5
        if not support_mask.any():
            return pred_offset.new_zeros(())
        return F.smooth_l1_loss(pred_offset[support_mask.expand_as(pred_offset)],
                                target_offset[support_mask.expand_as(target_offset)],
                                beta=1.0)

    def _edge_context_masks(self, instance: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        if instance.dim() == 5 and instance.shape[1] == 1:
            instance = instance[:, 0]
        inst = instance.long()
        near_neg = torch.zeros((inst.shape[0], 3, *inst.shape[1:]), dtype=torch.bool, device=inst.device)
        support_touch = torch.zeros_like(near_neg)
        for axis in range(3):
            a_sl = [slice(None)] * 4
            b_sl = [slice(None)] * 4
            a_sl[axis + 1] = slice(0, -1)
            b_sl[axis + 1] = slice(1, None)
            a = inst[tuple(a_sl)]
            b = inst[tuple(b_sl)]
            a_fg = (a > 0) & (a <= MAX_INSTANCE_ID)
            b_fg = (b > 0) & (b <= MAX_INSTANCE_ID)
            same_anatomy = a_fg & b_fg & (((a - 1) // 50) == ((b - 1) // 50))
            near_axis = near_neg[:, axis]
            touch_axis = support_touch[:, axis]
            near_axis[tuple(a_sl)] = same_anatomy & (a == b)
            touch_axis[tuple(a_sl)] = a_fg | b_fg
        return near_neg, support_touch

    def _edge_loss(self, edge_logits: torch.Tensor,
                   edge_break: torch.Tensor,
                   edge_valid: torch.Tensor,
                   instance: torch.Tensor) -> torch.Tensor:
        valid = edge_valid > 0.5
        if not valid.any():
            return edge_logits.new_zeros(())
        prob = torch.sigmoid(edge_logits).clamp(self.eps, 1.0 - self.eps)
        target = edge_break > 0.5
        near_neg, support_touch = self._edge_context_masks(instance.to(edge_logits.device))
        pos = valid & target
        near = valid & ~target & near_neg
        support_neg = valid & ~target & support_touch & ~near_neg
        bg_neg = valid & ~target & ~support_touch
        neg = valid & ~target
        loss = edge_logits.new_zeros(())
        denom = 0.0
        if pos.any():
            loss = loss + self.edge_pos_weight * (-((1.0 - prob[pos]) ** self.gamma) * torch.log(prob[pos])).mean()
            denom += self.edge_pos_weight
        for mask, weight in (
            (near, self.edge_near_neg_weight),
            (support_neg, self.edge_support_neg_weight),
            (bg_neg, self.edge_bg_neg_weight),
        ):
            if mask.any() and float(weight) > 0:
                vals = prob[mask]
                loss = loss + float(weight) * (-((vals ** self.gamma) * torch.log1p(-vals))).mean()
                denom += float(weight)
        if neg.any() and self.edge_neg_weight > 0:
            vals = prob[neg]
            base = -((vals ** self.gamma) * torch.log1p(-vals))
            loss = loss + self.edge_neg_weight * base.mean()
            denom += self.edge_neg_weight
            k = max(1, int(round(float(vals.numel()) * self.topk_fraction)))
            hard_vals = torch.topk(vals, k=min(k, vals.numel()), largest=True).values
            loss = loss + 0.5 * self.edge_neg_weight * (
                -((hard_vals ** self.gamma) * torch.log1p(-hard_vals))
            ).mean()
            denom += 0.5 * self.edge_neg_weight
        return loss if denom <= 0 else loss / denom

    def _embedding_loss(self, emb: torch.Tensor,
                        instance: torch.Tensor,
                        support: torch.Tensor) -> torch.Tensor:
        if instance.dim() == 5 and instance.shape[1] == 1:
            instance = instance[:, 0]
        emb = F.normalize(emb.float(), dim=1)
        losses = []
        for b in range(emb.shape[0]):
            ids = instance[b].long()
            fg_ids = torch.unique(ids[support[b] > 0.5])
            fg_ids = fg_ids[(fg_ids > 0) & (fg_ids <= MAX_INSTANCE_ID)]
            if fg_ids.numel() == 0:
                continue
            means = []
            pull = emb.new_zeros(())
            n_pull = 0
            for inst_id in fg_ids:
                mask = ids == inst_id
                coords = torch.nonzero(mask, as_tuple=False)
                if coords.shape[0] < 2:
                    continue
                if coords.shape[0] > self.max_embedding_voxels:
                    perm = torch.randperm(coords.shape[0], device=coords.device)[:self.max_embedding_voxels]
                    coords = coords[perm]
                vals = emb[b, :, coords[:, 0], coords[:, 1], coords[:, 2]].T
                mean = vals.mean(0)
                means.append(mean)
                dist = torch.norm(vals - mean[None], dim=1)
                pull = pull + torch.clamp(dist - 0.35, min=0.0).pow(2).mean()
                n_pull += 1
            if n_pull:
                pull = pull / float(n_pull)
            if len(means) >= 2:
                means_t = torch.stack(means)
                dist = torch.cdist(means_t[None], means_t[None])[0]
                tri = torch.triu(torch.ones_like(dist, dtype=torch.bool), diagonal=1)
                push = torch.clamp(1.5 - dist[tri], min=0.0).pow(2).mean() if tri.any() else emb.new_zeros(())
            else:
                push = emb.new_zeros(())
            losses.append(pull + push)
        if not losses:
            return emb.new_zeros(())
        return torch.stack(losses).mean()

    def forward(self, logits: torch.Tensor, target: dict[str, torch.Tensor]) -> torch.Tensor:
        with torch.cuda.amp.autocast(enabled=False):
            logits_f32 = logits.float()
            morphology = self._squeeze(target["morphology"]).to(logits_f32.device).long()
            support = self._squeeze(target["support"]).to(logits_f32.device).float()
            core = self._squeeze(target["core"]).to(logits_f32.device).float()
            offset = target["offset"].to(logits_f32.device).float()
            instance = target["instance"].to(logits_f32.device).long()
            edge_break = target.get("edge_break")
            edge_valid = target.get("edge_valid")

            morph_logits = logits_f32[:, 0:4]
            # Contact remains rare, but an overly large contact CE weight made
            # support non-contact voxels compete poorly and produced broad
            # pelvis-surface contact. Keep contact above support, but let
            # support/hard-negative labels win when the evidence is ordinary
            # bone surface rather than fragment-to-fragment separation.
            weights = logits_f32.new_tensor([0.05, 1.50, 4.0, 2.0])
            morphology_loss = F.cross_entropy(morph_logits, morphology, weight=weights)
            morph_prob = F.softmax(morph_logits, dim=1)
            contact_prob = morph_prob[:, self.CONTACT]
            contact_focal = self._contact_focal(contact_prob, morphology)
            contact_margin = self._contact_margin(morph_logits, morphology)
            topk_false = self._topk_false_contact(contact_prob, morphology)
            core_loss = self._core_loss(logits_f32[:, 4], core)
            offset_loss = self._offset_loss(logits_f32[:, 5:8], offset, support)
            embedding_loss = self._embedding_loss(logits_f32[:, 8:16], instance, support)
            edge_loss = logits_f32.new_zeros(())
            if logits_f32.shape[1] >= 19 and edge_break is not None and edge_valid is not None:
                edge_loss = self._edge_loss(
                    logits_f32[:, 16:19],
                    edge_break.to(logits_f32.device).float(),
                    edge_valid.to(logits_f32.device).float(),
                    instance,
                )
            return (
                self.morphology_weight * morphology_loss
                + self.contact_focal_weight * contact_focal
                + self.contact_margin_weight * contact_margin
                + self.topk_false_contact_weight * topk_false
                + self.core_weight * core_loss
                + self.edge_weight * edge_loss
                + self.offset_weight * offset_loss
                + self.embedding_weight * embedding_loss
            )


class DC_CE_TV_BD_loss(nn.Module):
    """Compound loss: DC+CE plus optional Tversky and BoundaryDoU terms.

    This wrapper exists for controlled split-anatomy upgrades:

    - `tversky_07`: DC+CE + 0.5 * Tversky(alpha=0.3, beta=0.7)
    - `tversky_08`: DC+CE + 0.5 * Tversky(alpha=0.2, beta=0.8)
    - `combo_tversky_bd005`: DC+CE + 0.35 * Tversky + 0.05 * BoundaryDoU
    - `abbc_contact_energy_v1`: Contact-Energy ABBC core/contact Tversky for
      stable seeds and precise fracture surfaces

    We keep DC+CE as the anchor term so the optimization landscape remains
    close to the already-good baseline. Tversky/BD are small corrective forces,
    not replacements.
    """

    def __init__(self, dc_ce_loss: nn.Module, n_classes: int,
                 weight_dc_ce: float = 1.0,
                 weight_tversky: float = 0.0,
                 tversky_alpha: float = 0.3,
                 tversky_beta: float = 0.7,
                 weight_bd: float = 0.0,
                 tversky_active_classes: list[int] | tuple[int, ...] | None = None,
                 tversky_class_weights: list[float] | tuple[float, ...] | dict[int, float] | None = None):
        super().__init__()
        self.dc_ce = dc_ce_loss
        self.weight_dc_ce = float(weight_dc_ce)
        self.weight_tversky = float(weight_tversky)
        self.weight_bd = float(weight_bd)
        self.tversky = SoftTverskyLoss3D(
            n_classes=n_classes,
            alpha=tversky_alpha,
            beta=tversky_beta,
            active_classes=tversky_active_classes,
            class_weights=tversky_class_weights,
        )
        self.bd = BoundaryDoULoss3D(n_classes=n_classes) if weight_bd > 0 else None
        if hasattr(dc_ce_loss, "dc"):
            self.dc = dc_ce_loss.dc

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        loss = self.weight_dc_ce * self.dc_ce(logits, target)
        if self.weight_tversky > 0:
            loss = loss + self.weight_tversky * self.tversky(logits, target)
        if self.bd is not None and self.weight_bd > 0:
            loss = loss + self.weight_bd * self.bd(logits, target)
        return loss


# =============================================================================
# 4. Class weight estimation — frequency-inverse with PENGWIN tweaks
# =============================================================================
def compute_class_weights(label_array_or_iter, n_classes: int,
                          min_weight: float = 0.5,
                          max_weight: float = 2.0,
                          smoothing: float = 1.0) -> np.ndarray:
    """Compute frequency-inverse class weights for cross-entropy.

    Args:
        label_array_or_iter: Either a single np.ndarray of integer labels OR
            an iterable of arrays (will be summed). For PENGWIN we pass a
            list of training-set GT label arrays (one per case).
        n_classes: total class count (incl. background).
        min_weight, max_weight: clamp range. Default (0.5, 2.0) prevents
            the rare class (e.g., a 0.05% sec fragment) from dominating
            gradients while still up-weighting it ~2×.
        smoothing: pseudocount added to each class count to avoid div-by-zero
            for classes absent in the sample. 1.0 ≡ Laplace smoothing.

    Returns:
        np.ndarray of shape (n_classes,), dtype float32.

    Algorithm:
        counts[c] = #voxels labeled c (across all provided arrays)
        freq[c] = (counts[c] + smoothing) / sum(counts + smoothing)
        weight[c] = 1 / freq[c], normalized so mean(weight) = 1.0,
                    then clamped to [min_weight, max_weight].

    Why PENGWIN specifics:
        Background dominates most voxels. Standard inverse frequency can give
        extreme rare-class weights, which can hurt calibration and boundary
        quality. Clamping to [0.5, 2.0] keeps this an ablation knob rather than
        a hidden training regime change.
    """
    if isinstance(label_array_or_iter, np.ndarray):
        arrays = [label_array_or_iter]
    else:
        arrays = list(label_array_or_iter)

    counts = np.zeros(n_classes, dtype=np.float64)
    for arr in arrays:
        # bincount is O(N); minlength ensures we cover all classes even if some
        # don't appear in this particular case (Pelvic case has no Femur, etc.).
        bc = np.bincount(arr.ravel(), minlength=n_classes).astype(np.float64)
        if len(bc) > n_classes:
            bc = bc[:n_classes]
        counts[:len(bc)] += bc

    counts_smooth = counts + smoothing
    freq = counts_smooth / counts_smooth.sum()
    weights = 1.0 / freq
    weights /= weights.mean()                  # mean-1 normalization
    weights = np.clip(weights, min_weight, max_weight).astype(np.float32)
    return weights


def compute_median_frequency_class_weights(label_array_or_iter, n_classes: int,
                                           min_weight: float = 0.5,
                                           max_weight: float = 2.0,
                                           smoothing: float = 1.0) -> np.ndarray:
    """Compute clipped median-frequency CE weights.

    This is the trainer's `CE_CLASS_WEIGHTS="auto"` implementation. Median
    frequency weighting is less aggressive than raw inverse frequency:

        weight[c] = median(freq[present classes]) / freq[c]

    The result is clipped to [0.5, 2.0], because PENGWIN IoU-F is very sensitive
    to fragment topology. Extreme CE weights can create more foreground blobs
    and worsen unmatched predicted fragment counts even if anatomy Dice rises.
    """
    if isinstance(label_array_or_iter, np.ndarray):
        arrays = [label_array_or_iter]
    else:
        arrays = list(label_array_or_iter)

    counts = np.zeros(n_classes, dtype=np.float64)
    for arr in arrays:
        bc = np.bincount(arr.ravel(), minlength=n_classes).astype(np.float64)
        counts += bc[:n_classes]
    counts_smooth = counts + smoothing
    freq = counts_smooth / counts_smooth.sum()
    present = counts > 0
    median = np.median(freq[present]) if present.any() else np.median(freq)
    weights = median / freq
    weights = np.clip(weights, min_weight, max_weight).astype(np.float32)
    return weights


# =============================================================================
# 4. Self-test (smoke) — run as `python loss.py`
# =============================================================================
def _smoke_test():
    """Quick sanity check — verify shapes/finite values on small CPU tensors."""
    print("[loss.py smoke]")
    torch.manual_seed(0)
    B, C, D, H, W = 1, 4, 8, 16, 16
    logits = torch.randn(B, C, D, H, W, requires_grad=True)
    target = torch.randint(0, C, (B, D, H, W))

    # 1. BoundaryDoULoss3D
    bd = BoundaryDoULoss3D(n_classes=C)
    val = bd(logits, target)
    assert torch.isfinite(val), f"BD loss not finite: {val}"
    val.backward()
    assert logits.grad is not None and torch.isfinite(logits.grad).all()
    print(f"  BoundaryDoULoss3D({C}c): {val.item():.4f}  ✓")

    # 2. compute_class_weights
    arr = np.random.randint(0, 4, size=(20, 20, 20))
    w = compute_class_weights(arr, n_classes=4)
    assert w.shape == (4,) and np.all(w > 0) and np.all(np.isfinite(w))
    print(f"  compute_class_weights: weights={w} (mean={w.mean():.3f})  ✓")

    print("[loss.py smoke] OK")


if __name__ == "__main__":
    _smoke_test()
